#[derive(Clone, Default)]
pub struct Global {
    pub enable: Vec<String>,
    pub disable: Vec<String>,
    pub exclude: Vec<String>,
    pub include: Vec<String>,
    pub respect_gitignore: bool,
    pub line_length: i64,
    pub fixable: Vec<String>,
    pub unfixable: Vec<String>,
    pub flavor: Flavor,
    pub force_exclude: bool,
    pub cache: bool,
    pub cache_dir: String,
    pub output_format: String,
    pub per_file_ignores: Vec<(String, Vec<String>)>,
    pub per_file_flavor: Vec<(String, Flavor)>,
}

pub struct Config {
    pub global: Global,
    /// rule name (e.g. MD013) -> kebab-case key -> raw toml value
    pub rules: BTreeMap<String, BTreeMap<String, toml::Value>>,
    pub path: Option<PathBuf>,
    pub source: ConfigSource,
    pub warnings: Vec<String>,
}

impl Config {
    pub fn get(&self, rule: &str, key: &str) -> Option<&toml::Value> {
        self.rules.get(rule).and_then(|m| m.get(key))
    }
    pub fn i64(&self, rule: &str, key: &str, default: i64) -> i64 {
        match self.get(rule, key) {
            Some(toml::Value::Integer(v)) => *v,
            _ => default,
        }
    }
    pub fn boolean(&self, rule: &str, key: &str, default: bool) -> bool {
        match self.get(rule, key) {
            Some(toml::Value::Boolean(v)) => *v,
            _ => default,
        }
    }
    pub fn string(&self, rule: &str, key: &str, default: &str) -> String {
        match self.get(rule, key) {
            Some(toml::Value::String(v)) => v.clone(),
            _ => default.to_string(),
        }
    }
    pub fn strings(&self, rule: &str, key: &str, default: &[&str]) -> Vec<String> {
        match self.get(rule, key) {
            Some(toml::Value::Array(v)) => v
                .iter()
                .filter_map(|x| x.as_str().map(|s| s.to_string()))
                .collect(),
            _ => default.iter().map(|s| s.to_string()).collect(),
        }
    }
    pub fn has_rule(&self, rule: &str) -> bool {
        self.rules.contains_key(rule)
    }
    /// List of (rule, key) pairs provided by the config file for `rule`.
    pub fn provided_keys(&self, rule: &str) -> Vec<String> {
        match self.rules.get(rule) {
            Some(m) => m.keys().cloned().collect(),
            None => vec![],
        }
    }
}

/// normalize a config key: snake_case -> kebab-case
pub fn norm_key(k: &str) -> String {
    k.replace('_', "-")
}

fn to_v(t: &toml::Value) -> toml::Value {
    t.clone()
}

/// Extract `[global]` settings (accepting both snake_case and kebab-case keys).
fn parse_global(table: &toml::Table, path: &Path, warnings: &mut Vec<String>) -> Global {
    let mut g = defaults();
    let mut seen: BTreeMap<String, &toml::Value> = BTreeMap::new();
    for (k, v) in table {
        seen.insert(norm_key(k), v);
    }
    let warn = |unknown: &str, warnings: &mut Vec<String>| {
        warnings.push(format!(
            "[config warning] Unknown global option in {}: {}",
            file_name_of(path),
            unknown
        ));
    };
    let known = [
        "enable",
        "disable",
        "exclude",
        "include",
        "respect-gitignore",
        "line-length",
        "fixable",
        "unfixable",
        "flavor",
        "force-exclude",
        "cache",
        "cache-dir",
        "output-format",
        "per-file-ignores",
        "per-file-flavor",
    ];
    for k in seen.keys() {
        if !known.contains(&k.as_str()) {
            warn(k, warnings);
        }
    }
    if let Some(v) = seen.get("enable") {
        if let Some(a) = as_str_array(v) {
            g.enable = a;
        }
    }
    if let Some(v) = seen.get("disable") {
        if let Some(a) = as_str_array(v) {
            g.disable = a;
        }
    }
    if let Some(v) = seen.get("exclude") {
        if let Some(a) = as_str_array(v) {
            g.exclude = a;
        }
    }
    if let Some(v) = seen.get("include") {
        if let Some(a) = as_str_array(v) {
            g.include = a;
        }
    }
    if let Some(v) = seen.get("respect-gitignore") {
        if let Some(b) = v.as_bool() {
            g.respect_gitignore = b;
        }
    }
    if let Some(v) = seen.get("line-length") {
        if let Some(i) = v.as_integer() {
            g.line_length = i;
        }
    }
    if let Some(v) = seen.get("fixable") {
        if let Some(a) = as_str_array(v) {
            g.fixable = a;
        }
    }
    if let Some(v) = seen.get("unfixable") {
        if let Some(a) = as_str_array(v) {
            g.unfixable = a;
        }
    }
    if let Some(v) = seen.get("flavor") {
        if let Some(s) = v.as_str() {
            g.flavor = Flavor::parse(s).unwrap_or(Flavor::Standard);
        }
    }
    if let Some(v) = seen.get("force-exclude") {
        if let Some(b) = v.as_bool() {
            g.force_exclude = b;
        }
    }
    if let Some(v) = seen.get("cache") {
        if let Some(b) = v.as_bool() {
            g.cache = b;
        }
    }
    if let Some(v) = seen.get("cache-dir") {
        if let Some(s) = v.as_str() {
            g.cache_dir = s.to_string();
        }
    }
    if let Some(v) = seen.get("output-format") {
        if let Some(s) = v.as_str() {
            g.output_format = s.to_string();
        }
    }
    if let Some(v) = seen.get("per-file-ignores") {
        if let Some(t) = v.as_table() {
            for (k, val) in t {
                if let Some(a) = as_str_array(val) {
                    g.per_file_ignores.push((k.clone(), a));
                }
            }
        }
    }
    if let Some(v) = seen.get("per-file-flavor") {
        if let Some(t) = v.as_table() {
            for (k, val) in t {
                if let Some(s) = val.as_str() {
                    if let Some(f) = Flavor::parse(s) {
                        g.per_file_flavor.push((k.clone(), f));
                    }
                }
            }
        }
    }
    g
}

fn as_str_array(v: &toml::Value) -> Option<Vec<String>> {
    let arr = v.as_array()?;
    let mut out = Vec::new();
    for item in arr {
        match item.as_str() {
            Some(s) => out.push(s.to_string()),
            None => return None,
        }
    }
    Some(out)
}

pub fn file_name_of(p: &Path) -> String {
    p.file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| p.to_string_lossy().to_string())
}

