/// Parse a raw config table (already deserialized) into a Config.
fn from_table(root: &toml::Table, path: &Path, source: ConfigSource) -> Config {
    let mut warnings: Vec<String> = Vec::new();
    let mut rules: BTreeMap<String, BTreeMap<String, toml::Value>> = BTreeMap::new();
    let mut global = defaults();
    let mut gtable: Option<&toml::Table> = None;

    for (k, v) in root {
        if k == "global" {
            if let Some(t) = v.as_table() {
                gtable = Some(t);
            }
            continue;
        }
        if k == "per-file-ignores" || k == "per-file-flavor" || k == "code-block-tools" {
            continue;
        }
        let upper = k.to_uppercase();
        if crate::rules::ALL.iter().any(|r| r.eq_ignore_ascii_case(&upper)) {
            let code = upper.to_string();
            if let Some(t) = v.as_table() {
                let mut m: BTreeMap<String, toml::Value> = BTreeMap::new();
                let known = known_keys(&code);
                for (kk, vv) in t {
                    let nk = norm_key(kk);
                    if !known.contains(&nk.as_str()) {
                        warnings.push(format!(
                            "[config warning] Unknown option for rule {}: {}",
                            code,
                            kk
                        ));
                        if let Some(ty) = type_name(vv) {
                            warnings.push(format!(
                                "[config warning] Type mismatch for {}.{}: expected {}, got {}",
                                code,
                                nk,
                                type_for(&code, &nk).unwrap_or("value"),
                                ty
                            ));
                        }
                    }
                    m.insert(nk, to_v(vv));
                }
                rules.insert(code, m);
            }
        } else {
            let sug = crate::rules::suggest_rule(&upper);
            warnings.push(format!(
                "[config warning] Unknown rule in {}: {}{}",
                file_name_of(path),
                k,
                sug
            ));
        }
    }
    if let Some(t) = gtable {
        global = parse_global(t, path, &mut warnings);
    }
    // pyproject: also honour tool.rumdl sub-keys at root? handled by caller
    Config {
        global,
        rules,
        path: Some(path.to_path_buf()),
        source,
        warnings,
    }
}

fn type_name(v: &toml::Value) -> Option<&'static str> {
    match v {
        toml::Value::String(_) => Some("string"),
        toml::Value::Integer(_) => Some("integer"),
        toml::Value::Float(_) => Some("float"),
        toml::Value::Boolean(_) => Some("boolean"),
        toml::Value::Datetime(_) => Some("datetime"),
        toml::Value::Array(_) => Some("array"),
        toml::Value::Table(_) => Some("table"),
    }
}

fn type_for(rule: &str, key: &str) -> Option<&'static str> {
    match default_value(rule, key) {
        Some(toml::Value::String(_)) => Some("string"),
        Some(toml::Value::Integer(_)) => Some("integer"),
        Some(toml::Value::Boolean(_)) => Some("boolean"),
        Some(toml::Value::Array(_)) => Some("array"),
        Some(toml::Value::Table(_)) => Some("table"),
        _ => None,
    }
}

pub fn empty() -> Config {
    Config {
        global: defaults(),
        rules: BTreeMap::new(),
        path: None,
        source: ConfigSource::Default,
        warnings: vec![],
    }
}

const CANDIDATES: &[&str] = &[
    ".rumdl.toml",
    "rumdl.toml",
    ".markdownlint.json",
    "markdownlint.json",
    ".markdownlint.yaml",
    "markdownlint.yaml",
    "markdownlint.yml",
    ".markdownlint.yml",
    "pyproject.toml",
];

/// Find the configuration file, searching upwards from `start`.
pub fn discover(start: &Path) -> Option<(PathBuf, ConfigSource)> {
    let mut dir: Option<&Path> = Some(start);
    let mut hit_git: Option<&Path> = None;
    while let Some(d) = dir {
        let git = d.join(".git");
        let marker = if git.exists() { Some(d) } else { hit_git.take() };
        for name in CANDIDATES {
            let p = d.join(name);
            if p.is_file() {
                if name.starts_with("pyproject") {
                    if let Ok(txt) = std::fs::read_to_string(&p) {
                        if let Ok(v) = txt.parse::<toml::Value>() {
                            if v.get("tool")
                                .and_then(|t| t.get("rumdl"))
                                .and_then(|r| r.as_table())
                                .map(|t| !t.is_empty())
                                .unwrap_or(false)
                            {
                                return Some((p, ConfigSource::Pyproject));
                            }
                        }
                    }
                    continue;
                }
                return Some((p, ConfigSource::Project));
            }
        }
        if marker.is_some() {
            break;
        }
        dir = d.parent();
    }
    None
}

pub fn user_config_path() -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_default();
    PathBuf::from(home).join(".config/rumdl/rumdl.toml")
}

/// Load config from `--config` path if given, else discover.
pub fn load(explicit: Option<&Path>, start_dir: &Path) -> Config {
    let found = match explicit {
        Some(p) => {
            let src = if p.ends_with("pyproject.toml") {
                ConfigSource::Pyproject
            } else {
                ConfigSource::Project
            };
            Some((p.to_path_buf(), src))
        }
        None => discover(start_dir),
    };
    let cfg = match found {
        Some((p, src)) => {
            let txt = std::fs::read_to_string(&p).unwrap_or_default();
            match parse_config_text(&txt, src) {
                Some(mut c) => {
                    c.path = Some(p.clone());
                    c
                }
                None => {
                    let mut c = empty();
                    c.path = Some(p.clone());
                    c.source = src;
                    c
                }
            }
        }
        None => {
            let up = user_config_path();
            if up.is_file() {
                let txt = std::fs::read_to_string(&up).unwrap_or_default();
                let mut c = parse_config_text(&txt, ConfigSource::User).unwrap_or_else(empty);
                c.path = Some(up);
                c.source = ConfigSource::User;
                c
            } else {
                empty()
            }
        }
    };
    if cfg.source == ConfigSource::Pyproject {
        // flatten tool.rumdl
        let mut cfg = cfg;
        if let Some(p) = cfg.path.clone() {
            let txt = std::fs::read_to_string(&p).unwrap_or_default();
            if let Ok(v) = txt.parse::<toml::Value>() {
                if let Some(t) = v
                    .get("tool")
                    .and_then(|t| t.get("rumdl"))
                    .and_then(|r| r.as_table())
                {
                    let mut c = from_table(t, &p, ConfigSource::Pyproject);
                    c.warnings = cfg.warnings;
                    cfg = c;
                }
            }
        }
        return cfg;
    }
    cfg
}

fn parse_config_text(txt: &str, src: ConfigSource) -> Option<Config> {
    // toml first
    if let Ok(v) = txt.parse::<toml::Value>() {
        let t = v.as_table()?.clone();
        let path = PathBuf::from("config");
        let mut c = from_table(&t, &path, src);
        c.source = src;
        return Some(c);
    }
    // markdownlint JSON / YAML
    let val = crate::utils::parse_json_or_yaml(txt)?;
    Some(markdownlint_to_config(&val, Path::new("config"), src))
}

pub fn markdownlint_to_config(
    v: &crate::utils::Yaml,
    path: &Path,
    src: ConfigSource,
) -> Config {
    use crate::utils::Yaml as Y;
    let mut warnings = Vec::new();
    let mut rules: BTreeMap<String, BTreeMap<String, toml::Value>> = BTreeMap::new();
    let mut g = defaults();
    if let Y::Mapping(map) = v {
        for (k, val) in map {
            let upper = k.to_uppercase();
            if crate::rules::ALL.iter().any(|r| r.eq_ignore_ascii_case(&upper)) {
                let code = upper.to_string();
                let mut m: BTreeMap<String, toml::Value> = BTreeMap::new();
                match val {
                    Y::Bool(b) => {
                        if !*b {
                            g.disable.push(code.clone());
                        }
                    }
                    Y::Mapping(sub) => {
                        for (kk, vv) in sub {
                            m.insert(norm_key(kk), crate::utils::yaml_to_toml(vv));
                        }
                    }
                    _ => {}
                }
                rules.insert(code, m);
            } else if k == "default" {
                if let Y::Bool(false) = val {
                    for r in crate::rules::ALL {
                        g.disable.push(r.to_string());
                    }
                }
            }
        }
    }
    let _ = &mut warnings;
    Config {
        global: g,
        rules,
        path: Some(path.to_path_buf()),
        source: src,
        warnings,
    }
}
