    Unknown,
}

impl FixAvail {
    pub fn desc(&self) -> &'static str {
        match self {
            FixAvail::Always => "Fix is always available.",
            FixAvail::Never => "Fix is not available.",
            FixAvail::Unknown => "Fix availability is unknown.",
        }
    }
}

pub struct R {
    pub code: &'static str,
    pub name: &'static str,
    pub summary: &'static str,
    pub category: Category,
    pub fix: FixAvail,
    pub aliases: &'static [&'static str],
}

include!("rules_table.rs");

pub fn find(query: &str) -> Option<&'static R> {
    let q = query.trim();
    let q_upper = q.to_uppercase();
    for r in ALL {
        if r.code == q_upper || r.name == q || r.aliases.iter().any(|a| a == &q) {
            return Some(r);
        }
    }
    let q_lower = q.to_lowercase();
    for r in ALL {
        if r.name == q_lower {
            return Some(r);
        }
    }
    None
}

pub fn categories() -> Vec<(Category, usize)> {
    let mut order = [
        Category::Blockquote,
        Category::CodeBlock,
        Category::Emphasis,
        Category::FrontMatter,
        Category::Heading,
        Category::Html,
        Category::Link,
        Category::List,
        Category::Other,
        Category::Whitespace,
    ];
    order.sort_by_key(|c| c.name());
    order
        .into_iter()
        .map(|c| {
            let n = ALL.iter().filter(|r| r.category == c).count();
            (c, n)
        })
        .collect()
}

/// Levenshtein distance, for the "did you mean" hint.
pub fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

pub fn suggest_rule(query: &str) -> String {
    let mut best: Option<(&R, usize)> = None;
    for r in ALL {
        let d = edit_distance(&query.to_uppercase(), r.code);
        if best.map(|(_, bd)| d < bd).unwrap_or(true) {
            best = Some((r, d));
        }
    }
    match best {
        Some((r, d)) if d <= 2 => format!(" (did you mean: {}?)", r.code),
        _ => String::new(),
    }
}

pub fn list_all() -> Vec<&'static R> {
    ALL.to_vec()
}
