}

include!("rules_table.rs");

pub fn find(query: &str) -> Option<&'static R> {
    let q = query.trim();
    let q_upper = q.to_uppercase();
    for r in ALL {
        if r.code == q_upper || r.name == q || r.aliases.iter().any(|a| a == &q) {
            return Some(r);
        }
    }
    let q_lower = q.to_lowercase();
    for r in ALL {
        if r.name == q_lower {
            return Some(r);
        }
    }
    None
}

pub fn categories() -> Vec<(Category, usize)> {
    let mut order = [
        Category::Blockquote,
        Category::CodeBlock,
        Category::Emphasis,
        Category::FrontMatter,
        Category::Heading,
        Category::Html,
        Category::Link,
        Category::List,
        Category::Other,
        Category::Whitespace,
    ];
    order.sort_by_key(|c| c.name());
    order
        .into_iter()
        .map(|c| {
            let n = ALL.iter().filter(|r| r.category == c).count();
            (c, n)
        })
        .collect()
