/// Levenshtein distance, for the "did you mean" hint.
pub fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

pub fn suggest_rule(query: &str) -> String {
    let mut best: Option<(&R, usize)> = None;
    for r in ALL {
        let d = edit_distance(&query.to_uppercase(), r.code);
        if best.map(|(_, bd)| d < bd).unwrap_or(true) {
            best = Some((r, d));
        }
    }
    match best {
        Some((r, d)) if d <= 2 => format!(" (did you mean: {}?)", r.code),
        _ => String::new(),
    }
}

pub fn list_all() -> Vec<&'static R> {
    ALL.to_vec()
}
