        ),
    }
}

fn yv_to_yaml(v: &YValue) -> Yaml {
    match v {
        YValue::Null => Yaml::Null,
        YValue::Bool(b) => Yaml::Bool(*b),
        YValue::Number(n) => {
            if let Some(i) = n.as_i64() {
                Yaml::Int(i)
            } else {
                Yaml::Float(n.as_f64().unwrap_or(0.0))
            }
        }
        YValue::String(s) => Yaml::Str(s.clone()),
        YValue::Sequence(a) => Yaml::Seq(a.iter().map(yv_to_yaml).collect()),
        YValue::Mapping(m) => Yaml::Mapping(
            m.iter()
                .map(|(k, v)| (yaml_str(k), yv_to_yaml(v)))
                .collect(),
        ),
        YValue::Tagged(t) => yv_to_yaml(&t.value),
    }
}

fn yaml_str(v: &YValue) -> String {
    match v {
        YValue::String(s) => s.clone(),
        YValue::Bool(b) => b.to_string(),
        YValue::Number(n) => n.to_string(),
        _ => serde_yaml::to_string(v).unwrap_or_default().trim().to_string(),
    }
}

pub fn yaml_to_toml(v: &Yaml) -> toml::Value {
    match v {
        Yaml::Null => toml::Value::String(String::new()),
        Yaml::Bool(b) => toml::Value::Boolean(*b),
        Yaml::Int(i) => toml::Value::Integer(*i),
        Yaml::Float(f) => toml::Value::Float(*f),
        Yaml::Str(s) => toml::Value::String(s.clone()),
        Yaml::Seq(a) => toml::Value::Array(a.iter().map(yaml_to_toml).collect()),
        Yaml::Mapping(m) => {
            let mut t = toml::map::Map::new();
            for (k, v) in m {
                t.insert(k.clone(), yaml_to_toml(v));
            }
            toml::Value::Table(t)
        }
    }
}

/// Simple glob matching supporting `*`, `?`, `**`, `{a,b}`.
pub struct Glob {
    alts: Vec<String>,
}

impl Glob {
    pub fn new(pattern: &str) -> Glob {
        let mut alts = Vec::new();
        expand_braces(pattern, &mut alts);
        if alts.is_empty() {
            alts.push(pattern.to_string());
        }
        Glob { alts }
    }

    pub fn matches(&self, path: &str) -> bool {
        let path = path.replace('\\', "/");
        for p in &self.alts {
            if glob_match(p, &path) {
                return true;
            }
        }
        false
    }
}

fn expand_braces(pat: &str, out: &mut Vec<String>) {
    if let Some(open) = pat.find('{') {
        // find matching close
        let mut depth = 0;
        let mut close = None;
        for (i, c) in pat.char_indices().skip_while(|(i, _)| *i < open) {
            match c {
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        close = Some(i);
                        break;
                    }
                }
                _ => {}
            }
        }
        if let Some(close) = close {
            let inner = &pat[open + 1..close];
            let mut parts = Vec::new();
            let mut cur = String::new();
            let mut d = 0;
            for c in inner.chars() {
                match c {
                    '{' => {
                        d += 1;
                        cur.push(c)
                    }
                    '}' => {
                        d -= 1;
                        cur.push(c)
                    }
                    ',' if d == 0 => {
                        parts.push(cur.clone());
                        cur.clear();
                    }
                    _ => cur.push(c),
                }
            }
            parts.push(cur);
            if parts.len() > 1 {
                for part in parts {
                    expand_braces(&format!("{}{}{}", &pat[..open], part, &pat[close + 1..]), out);
                }
                return;
            }
        }
    }
    out.push(pat.to_string());
}

/// glob matcher: `**` matches across path separators, `*` within a segment.
pub fn glob_match(pattern: &str, path: &str) -> bool {
    let pat: Vec<&str> = pattern.split('/').filter(|s| !s.is_empty()).collect();
    let pth: Vec<&str> = path.split('/').filter(|s| !s.is_empty()).collect();
    m(&pat, &pth)
}

fn m(pat: &[&str], pth: &[&str]) -> bool {
    if pat.is_empty() {
        return pth.is_empty();
    }
    if pat[0] == "**" {
        // `**` matches zero or more segments
        for i in 0..=pth.len() {
            if m(&pat[1..], &pth[i..]) {
                return true;
            }
        }
        return false;
    }
    if pth.is_empty() {
        return false;
    }
    if seg_match(pat[0], pth[0]) {
        m(&pat[1..], &pth[1..])
    } else {
        false
    }
}

pub fn seg_match(pat: &str, text: &str) -> bool {
    let p: Vec<char> = pat.chars().collect();
    let t: Vec<char> = text.chars().collect();
    let mut pi = 0;
    let mut ti = 0;
    let mut star = usize::MAX;
    let mut mark = 0;
    while ti < t.len() {
        if pi < p.len() && (p[pi] == '?' || p[pi] == t[ti]) {
            pi += 1;
            ti += 1;
        } else if pi < p.len() && p[pi] == '*' {
            star = pi;
            mark = ti;
            pi += 1;
        } else if star != usize::MAX {
            pi = star + 1;
            mark += 1;
            ti = mark;
        } else {
            return false;
        }
    }
    while pi < p.len() && p[pi] == '*' {
        pi += 1;
    }
    pi == p.len()
}

/// ANSI colouring helpers
pub struct Colors {
    pub enabled: bool,
}

impl Colors {
    pub fn new(mode: &str) -> Colors {
        let enabled = match mode {
            "always" => true,
            "never" => false,
            _ => std::env::var("NO_COLOR").is_err() && is_stdout_tty(),
        };
        Colors { enabled }
    }
    pub fn dim(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[2m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    pub fn yellow(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    pub fn cyan(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[36m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    pub fn red(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    pub fn green(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    pub fn blue(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[34m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

pub fn is_stdout_tty() -> bool {
    unsafe { libc_isatty(1) }
}

fn libc_isatty(fd: i32) -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(fd) != 0 }
}

pub fn is_stderr_tty() -> bool {
    extern "C" {
        fn isatty(fd: i32) -> i32;
    }
    unsafe { isatty(2) != 0 }
}
