{"command": "cd /workspace && cat > src/doc.rs <<'RSEOF'
use crate::config::Flavor;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum BlockKind {
    None,
    Fenced { fence_char: u8, len: usize, indent: usize, lang: String },
    Indented,
    Frontmatter,
    HtmlComment,
}

pub struct Doc {
    pub text: String,
    /// byte offset of the start of each line; last entry = text.len()
    pub starts: Vec<usize>,
    /// byte offset of the end of each line (excluding newline chars)
    pub ends: Vec<usize>,
    pub flavor: Flavor,
}

impl Doc {
    pub fn new(text: &str, flavor: Flavor) -> Doc {
        let mut starts = Vec::new();
        let mut ends = Vec::new();
        let bytes = text.as_bytes();
        let mut i = 0usize;
        while i <= bytes.len() {
            starts.push(i);
            let mut j = i;
            while j < bytes.len() && bytes[j] != b'\n' {
                j += 1;
            }
            ends.push(j);
            if j >= bytes.len() {
                break;
            }
            i = j + 1;
        }
        Doc {
            text: text.to_string(),
            starts,
            ends,
            flavor,
        }
    }

    pub fn nlines(&self) -> usize {
        self.starts.len()
    }

    /// line content without the newline (includes a trailing \r if present)
    pub fn line(&self, i: usize) -> &str {
        let s = self.starts[i];
        let e = self.ends[i];
        &self.text[s..e]
    }

    pub fn line_trimmed(&self, i: usize) -> &str {
        self.line(i).trim_end_matches('\r').trim_end()
    }

    pub fn is_blank(&self, i: usize) -> bool {
        self.line_trimmed(i).trim().is_empty()
    }

    /// offset of the first byte of line i
    pub fn start(&self, i: usize) -> usize {
        self.starts[i]
    }

    /// offset just past the newline of line i
    pub fn next_start(&self, i: usize) -> usize {
        let e = self.ends[i];
        if e < self.text.len() {
            e + 1
        } else {
            e
        }
    }

    /// 1-based column for a 0-based char index within line i
    pub fn col_char(&self, i: usize, char_idx: usize) -> usize {
        char_idx + 1
    }

    /// 1-based column for a byte offset
    pub fn col_byte(&self, i: usize, byte_off: usize) -> usize {
        let s = self.starts[i];
        byte_off - s + 1
    }

    /// byte offset for a 0-based char index in line i
    pub fn char_to_byte(&self, i: usize, char_idx: usize) -> usize {
        let s = self.starts[i];
        let e = self.ends[i];
        let line = &self.text[s..e];
        line.char_indices()
            .nth(char_idx)
            .map(|(o, _)| s + o)
            .unwrap_or(e)
    }

    pub fn line_of_offset(&self, off: usize) -> usize {
        match self.starts.binary_search(&off) {
            Ok(i) => i,
            Err(i) => i.saturating_sub(1),
        }
    }

    /// all headings in the document (excluding frontmatter and code blocks)
    pub fn headings(&self) -> Vec<Heading> {
        let mut out = Vec::new();
        let skip = self.non_text_lines();
        for i in 0..self.nlines() {
            if skip[i] {
                continue;
            }
            if let Some(h) = self.parse_heading(i) {
                out.push(h);
            }
        }
        out
    }

    /// lines that should be ignored for heading/list detection:
    /// frontmatter, fenced code blocks, indented code blocks
    pub fn non_text_lines(&self) -> Vec<bool> {
        let n = self.nlines();
        let mut skip = vec![false; n];
        let mut i = 0usize;
        // frontmatter
        if n > 0 && self.line_trimmed(0) == "---" {
            skip[0] = true;
            i = 1;
            while i < n {
                skip[i] = true;
                if self.line_trimmed(i) == "---" || self.line_trimmed(i) == "..." {
                    break;
                }
                i += 1;
            }
        }
        let mut in_fence: Option<(u8, usize)> = None;
        while i < n {
            let l = self.line_trimmed(i);
            match in_fence {
                Some((ch, len)) => {
                    skip[i] = true;
                    if is_fence_close(l, ch, len) {
                        in_fence = None;
                    }
                }
                None => {
                    if let Some((ch, len)) = fence_open(l) {
                        skip[i] = true;
                        in_fence = Some((ch, len));
                    } else if l.starts_with("    ") || l.starts_with('\t') {
                        skip[i] = true;
                    }
                }
            }
            i += 1;
        }
        skip
    }

    pub fn parse_heading(&self, i: usize) -> Option<Heading> {
        let l = self.line_trimmed(i);
        let bytes = l.as_bytes();
        if bytes.is_empty() {
            return None;
        }
        let mut k = 0usize;
        while k < bytes.len() && bytes[k] == b'#' {
            k += 1;
        }
        if k == 0 || k > 6 {
            // setext?
            return None;
        }
        if k < bytes.len() && bytes[k] != b' ' {
            return None;
        }
        // content start
        let mut c = k;
        while c < bytes.len() && bytes[c] == b' ' {
            c += 1;
        }
        let content = &l[c..];
        // closed?
        let mut closed_end = None;
        if !content.is_empty() {
            let mut e = content.len();
            // trailing hashes
            while e > 0 && content.as_bytes()[e - 1] == b'#' {
                e -= 1;
            }
            if e < content.len() {
                let hashes = content.len() - e;
                if hashes == k && (e == 0 || content.as_bytes()[e - 1] == b' ') {
                    closed_end = Some(e);
                }
            }
        }
        let text = match closed_end {
            Some(e) => content[..e].trim_end().to_string(),
            None => content.to_string(),
        };
        Some(Heading {
            line: i,
            level: k,
            content_start_char: c,
            text,
            closed: closed_end.is_some(),
            hashes_start: 0,
            content_end_char: match closed_end {
                Some(e) => e,
                None => content.len(),
            },
            raw_indent: l.len() - l.trim_start().len(),
        })
    }

    pub fn setext_heading(&self, i: usize) -> Option<(usize, u8)> {
        // line i is the underline; heading is on line i-1
        if i == 0 {
            return None;
        }
        let l = self.line_trimmed(i);
        if l.is_empty() {
            return None;
        }
        let b = l.as_bytes();
        let ch = b[0];
        if ch != b'=' && ch != b'-' {
            return None;
        }
        if !b.iter().all(|&c| c == ch) {
            return None;
        }
        if l.len() < 3 {
            return None;
        }
        let prev = self.line_trimmed(i - 1);
        if prev.trim().is_empty() {
            return None;
        }
        if self.parse_heading(i - 1).is_some() {
            return None;
        }
        Some((i - 1, ch))
    }
}

#[derive(Clone, Debug)]
pub struct Heading {
    pub line: usize,
    pub level: usize,
    /// char index of the first non-space char after the hashes (within the trimmed line)
    pub content_start_char: usize,
    pub content_end_char: usize,
    pub text: String,
    pub closed: bool,
    pub hashes_start: usize,
    pub raw_indent: usize,
}

impl Heading {
    /// 1-based column of the heading content
    pub fn content_col(&self) -> usize {
        self.content_start_char + 1
    }
}

pub fn fence_open(l: &str) -> Option<(u8, usize)> {
    let b = l.as_bytes();
    if b.is_empty() {
        return None;
    }
    let ch = b[0];
    if ch != b'`' && ch != b'~' {
        return None;
    }
    let mut n = 0;
    while n < b.len() && b[n] == ch {
        n += 1;
    }
    if n < 3 {
        return None;
    }
    // info string must not contain the fence char
    if l[n..].contains(ch as char) {
        return None;
    }
    Some((ch, n))
}

pub fn is_fence_close(l: &str, ch: u8, len: usize) -> bool {
    let b = l.as_bytes();
    if b.len() < len {
        return false;
    }
    for i in 0..len {
        if b[i] != ch {
            return false;
        }
    }
    b[len..].iter().all(|&c| c == b' ' || c == b'\t')
}
