use crate::config::Config;
use crate::doc::Doc;
use crate::lint::Ctx;
use crate::rules::{Fix, Issue};
use unicode_width::UnicodeWidthChar;

fn trailing_ws(line: &str) -> usize {
    let b = line.as_bytes();
    let mut n = 0;
    while n < b.len() && (b[b.len() - 1 - n] == b' ' || b[b.len() - 1 - n] == b'\t') {
        n += 1;
    }
    n
}

pub fn md009(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let br = cfg.i64("MD009", "br-spaces", 2) as usize;
    let strict = cfg.boolean("MD009", "strict", false);
    let skip = doc.non_text_lines();
    let list_empty = cfg.boolean("MD009", "list-item-empty-lines", false);
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line(i);
        let n = trailing_ws(l.trim_end_matches('\r'));
        if n == 0 {
            continue;
        }
        if !strict && n == br {
            continue;
        }
        if !list_empty && l.trim().is_empty() {
            // blank line with only whitespace
        }
        let body = l.trim_end_matches('\r');
        let col = body.chars().count() - n + 1;
        let msg = if body.trim().is_empty() {
            "Empty line has trailing spaces".to_string()
        } else if n == 1 {
            "Trailing space found".to_string()
        } else {
            format!("{} trailing spaces found", n)
        };
        let keep = if strict { 0 } else { br };
        let start = doc.char_to_byte(i, body.chars().count() - n);
        let end = doc.start(i) + body.len();
        let fix = if keep < n {
            let rm = n - keep;
            let s = doc.char_to_byte(i, body.chars().count() - n);
            Some(Fix::new(s, s + rm, ""))
        } else {
            None
        };
        let _ = (start, end);
        out.push(Issue::new("MD009", i + 1, col, msg).with_fix_if(fix));
    }
    out
}

pub fn md010(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let per = cfg.i64("MD010", "spaces-per-tab", 4) as usize;
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line(i).trim_end_matches('\r');
        let mut count = 0usize;
        let mut start_char = None;
        for (ci, c) in l.char_indices() {
            if c == '\t' {
                count += 1;
                if start_char.is_none() {
                    start_char = Some(l[..ci].chars().count());
                }
            } else if c == ' ' {
                // spaces around a tab are not tabs
            } else {
                break;
            }
        }
        if count == 0 {
            continue;
        }
        // decide leading vs alignment
        let leading = l.chars().take_while(|c| *c == '\t').count();
        let msg = if leading == count {
            if count == 1 {
                format!("Found leading tab, use {} spaces instead", per)
            } else {
                format!("Found {} leading tabs, use {} spaces instead", count, per * count)
            }
        } else if count == 1 {
            "Found tab for alignment, use spaces instead".to_string()
        } else {
            format!("Found {} tabs for alignment, use spaces instead", count)
        };
        let s = start_char.unwrap_or(0);
        out.push(
            Issue::new("MD010", i + 1, s + 1, msg).with_fix(Fix::new(
                doc.char_to_byte(i, s),
                doc.char_to_byte(i, s + count),
                &" ".repeat(per * count),
            )),
        );
    }
    out
}

pub fn md012(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let max = cfg.i64("MD012", "maximum", 1) as usize;
    let n = doc.nlines();
    let mut run = 0usize;
    let mut run_start = 0usize;
    let mut at_end = false;
    for i in 0..n {
        if doc.is_blank(i) {
            if run == 0 {
                run_start = i;
            }
            run += 1;
        } else {
            if run > max {
                out.push(
                    Issue::new(
                        "MD012",
                        run_start + max + 1,
                        1,
                        "Multiple consecutive blank lines between content".to_string(),
                    )
                    .with_fix(Fix::new(
                        doc.start(run_start + max),
                        doc.start(i),
                        "",
                    )),
                );
            }
            run = 0;
        }
    }
    // trailing blank lines
    if run > max {
        at_end = true;
        let start = run_start + max;
        out.push(
            Issue::new(
                "MD012",
                start + 1,
                1,
                "Multiple consecutive blank lines at end of file".to_string(),
            )
            .with_fix(Fix::new(doc.start(start), doc.text.len(), "")),
        );
    }
    let _ = at_end;
    out
}

pub fn md013(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let limit = cfg.i64("MD013", "line-length", cfg.global.line_length) as usize;
    if limit == 0 {
        return out;
    }
    let check_code = cfg.boolean("MD013", "code-blocks", true);
    let check_tables = cfg.boolean("MD013", "tables", false);
    let check_headings = cfg.boolean("MD013", "headings", true);
    let check_paras = cfg.boolean("MD013", "paragraphs", true);
    let mode = cfg.string("MD013", "length-mode", "visual");
    let skip = doc.non_text_lines();
    // indented code blocks: MD013 checks them when code_blocks is true
    let indented = doc.indented_code_lines();
    for i in 0..doc.nlines() {
        if doc.is_blank(i) {
            continue;
        }
        if skip[i] && !indented[i] {
            continue;
        }
        if indented[i] && !check_code {
            continue;
        }
        let l = doc.line_trimmed(i);
        let trimmed = l.trim();
        if trimmed.starts_with('|') && trimmed.ends_with('|') {
            if !check_tables {
                continue;
            }
        }
        if crate::doc::fence_open(trimmed).is_some() {
            continue;
        }
        if let Some(h) = doc.parse_heading(i) {
            if !check_headings {
                continue;
            }
            let _ = h;
        } else if !check_paras {
            continue;
        }
        let width = crate::utils::line_width(l, &mode);
        if width > limit {
            out.push(
                Issue::new(
                    "MD013",
                    i + 1,
                    limit + 1,
                    format!("Line length {} exceeds {} characters", width, limit),
                ),
            );
        }
    }
    out
}

pub fn md014(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let show_output = cfg.boolean("MD014", "show-output", true);
    if !show_output {
        return out;
    }
    let mut i = 0usize;
    let mut in_fence: Option<(u8, usize)> = None;
    let mut block_start = 0usize;
    while i < doc.nlines() {
        let l = doc.line_trimmed(i);
        match in_fence {
            None => {
                if let Some((ch, len)) = crate::doc::fence_open(l) {
                    in_fence = Some((ch, len));
                    block_start = i + 1;
                }
            }
            Some((ch, len)) => {
                if crate::doc::is_fence_close(l, ch, len) {
                    // scan the block
                    for j in block_start..i {
                        let bl = doc.line_trimmed(j);
                        let t = bl.trim_start();
                        if t.starts_with("$ ") || t.starts_with("> ") {
                            let cmd = t[2..].trim();
                            // is there output after?
                            let has_output = (j + 1..i).any(|k| !doc.is_blank(k));
                            if !has_output && !cmd.is_empty() {
                                out.push(
                                    Issue::new(
                                        "MD014",
                                        j + 1,
                                        doc.line_trimmed(j).len()
                                            - doc.line_trimmed(j).trim_start().len()
                                            + 1,
                                        format!(
                                            "Command '{}' should show output (add example output or remove $ prompt)",
                                            cmd
                                        ),
                                    ),
                                );
                            }
                        }
                    }
                    in_fence = None;
                }
            }
        }
        i += 1;
    }
    out
}

pub fn md018(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let magiclink = cfg.boolean("MD018", "magiclink", false);
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        let raw = doc.line(i);
        if raw.trim_start() != l {
            continue;
        }
        if let Some(h) = doc.parse_heading(i) {
            let _ = h;
        } else {
            continue;
        }
        let hashes = l.chars().take_while(|c| *c == '#').count();
        if magiclink && l[hashes..].starts_with('#') {
            continue;
        }
        let rest = &l[hashes..];
        if rest.is_empty() {
            continue;
        }
        if !rest.starts_with(' ') {
            // no space at all -> only if it is a heading (level <= 6)
            if hashes <= 6 {
                out.push(
                    Issue::new(
                        "MD018",
                        i + 1,
                        hashes + 1,
                        format!("No space after {} in heading", &l[..hashes]),
                    )
                    .with_fix(Fix::new(
                        doc.char_to_byte(i, hashes),
                        doc.char_to_byte(i, hashes),
                        " ",
                    )),
                );
            }
        }
    }
    out
}

pub fn md019(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        if doc.parse_heading(i).is_none() {
            continue;
        }
        let hashes = l.chars().take_while(|c| *c == '#').count();
        let mut sp = 0usize;
        while hashes + sp < l.len() && l.as_bytes()[hashes + sp] == b' ' {
            sp += 1;
        }
        if sp > 1 {
            let msg = format!("Multiple spaces ({}) after {} in heading", sp, &l[..hashes]);
            let s = doc.char_to_byte(i, hashes + 1);
            let e = doc.char_to_byte(i, hashes + sp);
            out.push(
                Issue::new("MD019", i + 1, hashes + 2, msg)
                    .with_fix(Fix::new(s, e, " ")),
            );
        }
    }
    out
}

pub fn md020(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let h = match doc.parse_heading(i) {
            Some(h) => h,
            None => continue,
        };
        let l = doc.line_trimmed(i);
        if !h.closed {
            continue;
        }
        let hashes = h.level;
        // start: hashes followed by spaces
        let mut sp = 0usize;
        while hashes + sp < l.len() && l.as_bytes()[hashes + sp] == b' ' {
            sp += 1;
        }
        if sp == 0 {
            out.push(
                Issue::new(
                    "MD020",
                    i + 1,
                    hashes + 1,
                    "Missing space after # at start of closed heading".to_string(),
                )
                .with_fix(Fix::new(
                    doc.char_to_byte(i, hashes),
                    doc.char_to_byte(i, hashes),
                    " ",
                )),
            );
            continue;
        }
        // end: the closing hashes must be preceded by a space
        let end_hashes_start = h.content_end_char;
        let prev = if end_hashes_start == 0 {
            None
        } else {
            Some(l.as_bytes()[end_hashes_start - 1])
        };
        match prev {
            None => {}
            Some(b' ') => {}
            _ => {
                let run = &l[end_hashes_start..];
                let msg = format!("Missing space before {} at end of closed heading", run);
                let s = doc.char_to_byte(i, end_hashes_start);
                out.push(
                    Issue::new("MD020", i + 1, end_hashes_start + 1, msg)
                        .with_fix(Fix::new(s, s, " ")),
                );
            }
        }
    }
    out
}

pub fn md021(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let h = match doc.parse_heading(i) {
            Some(h) => h,
            None => continue,
        };
        if !h.closed {
            continue;
        }
        let l = doc.line_trimmed(i);
        let hashes = h.level;
        let mut sp_start = 0usize;
        while hashes + sp_start < l.len() && l.as_bytes()[hashes + sp_start] == b' ' {
            sp_start += 1;
        }
        // end spaces: between content end and closing hashes
        let end_start = h.content_end_char;
        let mut sp_end = 0usize;
        while end_start + sp_end < l.len() && l.as_bytes()[end_start + sp_end] == b' ' {
            sp_end += 1;
        }
        if sp_start <= 1 && sp_end <= 1 {
            continue;
        }
        let msg = if sp_start > 1 && sp_end > 1 {
            format!(
                "Multiple spaces ({} at start, {} at end) inside hashes on closed heading (with {} at start and end)",
                sp_start, sp_end, &l[..hashes]
            )
        } else if sp_start > 1 {
            format!(
                "Multiple spaces ({}) after {} at start of closed heading",
                sp_start, &l[..hashes]
            )
        } else {
            format!(
                "Multiple spaces ({}) before {} at end of closed heading",
                sp_end, &l[end_start..]
            )
        };
        // fix: single space each side
        let mut fixes: Vec<Fix> = Vec::new();
        if sp_start > 1 {
            fixes.push(Fix::new(
                doc.char_to_byte(i, hashes + 1),
                doc.char_to_byte(i, hashes + sp_start),
                " ",
            ));
        }
        if sp_end > 1 {
            fixes.push(Fix::new(
                doc.char_to_byte(i, end_start + 1),
                doc.char_to_byte(i, end_start + sp_end),
                " ",
            ));
        }
        let col = if sp_start > 1 {
            hashes + 2
        } else {
            end_start + 2
        };
        out.push(Issue::new("MD021", i + 1, col, msg).with_fixes(fixes));
    }
    out
}

pub fn md023(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        let ind = l.len() - l.trim_start().len();
        if ind == 0 {
            continue;
        }
        if doc.parse_heading(i).is_none() {
            continue;
        }
        // setext?
        let is_setext = i + 1 < doc.nlines() && doc.setext_heading(i + 1).is_some();
        if is_setext {
            continue;
        }
        let spaces = l[..ind].chars().count();
        let msg = if spaces == 1 {
            "Heading should not be indented by 1 space".to_string()
        } else {
            format!("Heading should not be indented by {} spaces", spaces)
        };
        out.push(
            Issue::new("MD023", i + 1, 1, msg)
                .with_fix(Fix::new(doc.start(i), doc.start(i) + ind, "")),
        );
    }
    out
}

pub fn md026(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let punct: Vec<char> = cfg.string("MD026", "punctuation", ".,;:!").chars().collect();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let h = match doc.parse_heading(i) {
            Some(h) => h,
            None => continue,
        };
        let text = &h.text;
        if text.is_empty() {
            continue;
        }
        let last = text.chars().last().unwrap();
        if punct.contains(&last) {
            let msg = format!(
                "Heading '{}' ends with punctuation '{}'",
                text,
                last
            );
            let fix = if h.level >= 2 {
                let s = doc.char_to_byte(i, h.content_end_char - 1);
                Some(Fix::new(s, s + last.len_utf8(), ""))
            } else {
                None
            };
            let mut iss = Issue::new(
                "MD026",
                i + 1,
                h.content_end_char,
                msg,
            );
            if let Some(f) = fix {
                iss = iss.with_fix(f);
            }
            out.push(iss);
        }
    }
    out
}

pub fn md034(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::bare_urls(l) {
            let msg = format!(
                "URL without angle brackets or link formatting: '{}'",
                m.text
            );
            let s = doc.char_to_byte(i, m.start_char);
            let e = doc.char_to_byte(i, m.start_char + m.text.chars().count());
            out.push(
                Issue::new("MD034", i + 1, m.start_char + 1, msg)
                    .with_fix(Fix::new(s, e, &format!("<{}>", m.text))),
            );
        }
    }
    out
}

pub fn md035(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let style = cfg.string("MD035", "style", "consistent");
    let skip = doc.non_text_lines();
    let mut hrs: Vec<(usize, String)> = Vec::new();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        if crate::rules::inline::is_hr(l) {
            hrs.push((i, l.to_string()));
        }
    }
    if hrs.is_empty() {
        return out;
    }
    let expected = if style == "consistent" {
        let mut counts: Vec<(String, usize)> = Vec::new();
        for (_, s) in &hrs {
            match counts.iter_mut().find(|(k, _)| k == s) {
                Some((_, c)) => *c += 1,
                None => counts.push((s.clone(), 1)),
            }
        }
        counts
            .into_iter()
            .max_by_key(|(_, c)| *c)
            .map(|(k, _)| k)
            .unwrap()
    } else {
        style.clone()
    };
    for (i, s) in hrs {
        if s != expected {
            let msg = format!("Horizontal rule style should be \"{}\"", expected);
            out.push(
                Issue::new("MD035", i + 1, 1, msg).with_fix(Fix::new(
                    doc.start(i),
                    doc.start(i) + doc.line(i).len(),
                    &expected,
                )),
            );
        }
    }
    out
}

pub fn md036(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let punct: Vec<char> = cfg
        .string("MD036", "punctuation", ".,;:!?")
        .chars()
        .collect();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        if doc.parse_heading(i).is_some() {
            continue;
        }
        for m in crate::rules::inline::emphasis_segments(l) {
            // only whole-line emphasis
            if m.start_char != l.trim_start().len() {
                continue;
            }
            if m.end_char != l.len() {
                continue;
            }
            let inner = m.text.trim_matches(|c| c == '*' || c == '_');
            let inner = inner.trim();
            if inner.is_empty() {
                continue;
            }
            let last = inner.chars().last().unwrap();
            if punct.contains(&last) {
                continue;
            }
            let msg = format!("Emphasis used instead of a heading: '{}'", inner);
            out.push(Issue::new("MD036", i + 1, m.start_char + 1, msg));
        }
    }
    out
}

pub fn md037(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::emphasis_bad_spaces(l) {
            let msg = format!("Spaces inside emphasis markers: '{}'", m.text);
            let s = doc.char_to_byte(i, m.start_char);
            let e = doc.char_to_byte(i, m.start_char + m.text.chars().count());
            out.push(
                Issue::new("MD037", i + 1, m.start_char + 1, msg)
                    .with_fix(Fix::new(s, e, &m.replacement)),
            );
        }
    }
    out
}

pub fn md038(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for cs in crate::rules::inline::code_spans(l) {
            let inner = &l[cs.start_char + cs.ticks..cs.end_char - cs.ticks];
            let mut bad = false;
            let mut rep = inner.to_string();
            if inner.starts_with(' ') && inner.ends_with(' ') && inner.len() > 1 {
                rep = inner.trim().to_string();
                bad = true;
            } else if inner.starts_with(' ') {
                rep = inner.trim_start().to_string();
                bad = true;
            } else if inner.ends_with(' ') {
                rep = inner.trim_end().to_string();
                bad = true;
            }
            if bad {
                let obsidian = doc.flavor == crate::config::Flavor::Obsidian
                    && (inner.trim_start().starts_with("= ") || inner.trim_start().starts_with("$= "));
                if obsidian {
                    continue;
                }
                let s = doc.char_to_byte(i, cs.start_char + cs.ticks);
                let e = doc.char_to_byte(i, cs.end_char - cs.ticks);
                out.push(
                    Issue::new(
                        "MD038",
                        i + 1,
                        cs.start_char + 1,
                        "Spaces inside code span elements".to_string(),
                    )
                    .with_fix(Fix::new(s, e, &rep)),
                );
            }
        }
    }
    out
}

pub fn md041(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let level = cfg.i64("MD041", "level", 1) as usize;
    let fm_title = cfg.string("MD041", "front-matter-title", "title");
    let fm_pat = cfg.string("MD041", "front-matter-title-pattern", "");
    // frontmatter?
    let n = doc.nlines();
    let mut first_line = 0usize;
    let mut fm = None;
    if n > 0 && doc.line_trimmed(0) == "---" {
        let mut j = 1;
        while j < n {
            if doc.line_trimmed(j) == "---" || doc.line_trimmed(j) == "..." {
                fm = Some((0, j));
                first_line = j + 1;
                break;
            }
            j += 1;
        }
    }
    if let Some((a, b)) = fm {
        for k in a..=b {
            let l = doc.line_trimmed(k);
            if let Some((key, val)) = l.split_once(':') {
                let key = key.trim();
                let val = val.trim().trim_matches(|c| c == '"' || c == '\'');
                let matches = if !fm_pat.is_empty() {
                    crate::rules::inline::starts_with_pattern(&format!("{}:", key), &fm_pat)
                } else {
                    key == fm_title
                };
                if matches && !val.is_empty() {
                    return out;
                }
            }
        }
    }
    // find first non-blank line
    let mut first = None;
    for i in 0..n {
        if !doc.is_blank(i) {
            first = Some(i);
            break;
        }
    }
    let first = match first {
        Some(f) => f,
        None => return out,
    };
    let h = doc.parse_heading(first);
    let ok = match h {
        Some(h) => h.level == level,
        None => false,
    };
    if !ok {
        out.push(Issue::new(
            "MD041",
            first + 1,
            1,
            format!("First line in file should be a level {} heading", level),
        ));
    }
    out
}

pub fn md044(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let names = cfg.strings("MD044", "names", &[]);
    if names.is_empty() {
        return out;
    }
    let in_code = cfg.boolean("MD044", "code-blocks", false);
    let html_elements = cfg.boolean("MD044", "html-elements", true);
    let html_comments = cfg.boolean("MD044", "html-comments", false);
    let skip = doc.non_text_lines();
    let indented = doc.indented_code_lines();
    for i in 0..doc.nlines() {
        if !in_code && (skip[i] || indented[i]) {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::proper_name_matches(l, &names) {
            if !html_elements && m.in_html_element {
                continue;
            }
            if !html_comments && m.in_html_comment {
                continue;
            }
            let msg = format!("Proper name '{}' should be '{}'", m.found, m.expected);
            let s = doc.char_to_byte(i, m.start_char);
            let e = doc.char_to_byte(i, m.start_char + m.found.chars().count());
            out.push(
                Issue::new("MD044", i + 1, m.start_char + 1, msg)
                    .with_fix(Fix::new(s, e, &m.expected)),
            );
        }
    }
    out
