pub fn md064(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let allow_double = cfg.boolean("MD064", "allow-sentence-double-space", false);
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        let bytes = l.as_bytes();
        let mut j = 0usize;
        while j < bytes.len() {
            if bytes[j] == b' ' {
                let mut k = j;
                while k < bytes.len() && bytes[k] == b' ' {
                    k += 1;
                }
                let n = k - j;
                if n >= 2 {
                    let mut allowed = false;
                    if allow_double && n == 2 {
                        let before = if j == 0 { ' ' } else { l[..j].chars().last().unwrap() };
                        let after = if k < l.len() { l[k..].chars().next().unwrap() } else { ' ' };
                        if matches!(before, '.' | '!' | '?') && after.is_alphabetic() {
                            allowed = true;
                        }
                    }
                    if !allowed {
                        // byte column
                        let col = j + 1;
                        let s = doc.start(i) + j;
                        out.push(
                            Issue::new(
                                "MD064",
                                i + 1,
                                col,
                                format!("Multiple consecutive spaces ({}) found", n),
                            )
                            .with_fix(Fix::new(s, s + n, " ")),
                        );
                    }
                }
                j = k;
            } else {
                j += 1;
            }
        }
    }
    out
}

pub fn md065(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
