use unicode_width::UnicodeWidthChar;

/// A code span: byte/char offsets within a line.
#[derive(Clone, Copy, Debug)]
pub struct CodeSpan {
    pub start_char: usize,
    pub end_char: usize,
    pub ticks: usize,
}

/// Scan a line for code spans (CommonMark-ish).
pub fn code_spans(l: &str) -> Vec<CodeSpan> {
    let b: Vec<char> = l.chars().collect();
    let mut out = Vec::new();
    let mut i = 0usize;
    // track escaping
    while i < b.len() {
        if b[i] == '\\' && i + 1 < b.len() {
            i += 2;
            continue;
        }
        if b[i] != '`' {
            i += 1;
            continue;
        }
        let start = i;
        let mut n = 0;
        while i < b.len() && b[i] == '`' {
            n += 1;
            i += 1;
        }
        // find matching run
        let mut j = i;
        let mut end = None;
        while j < b.len() {
            if b[j] == '\\' {
                j += 2;
                continue;
            }
            if b[j] == '`' {
                let s2 = j;
                let mut m = 0;
                while j < b.len() && b[j] == '`' {
                    m += 1;
                    j += 1;
                }
                if m == n {
                    end = Some((s2, j));
                    break;
                }
            } else {
                j += 1;
            }
        }
        match end {
            Some((s2, e2)) => {
                out.push(CodeSpan {
                    start_char: start,
                    end_char: e2,
                    ticks: n,
                });
                i = e2;
            }
            None => {
                i = start + n;
            }
        }
    }
    out
}

/// ranges of a line that are inline code (for suppression)
pub fn code_span_ranges(l: &str) -> Vec<(usize, usize)> {
    code_spans(l).iter().map(|c| (c.start_char, c.end_char)).collect()
}

#[derive(Clone, Copy, Debug)]
pub struct Img {
    pub start_char: usize,
    pub alt: String,
    pub url: String,
    pub is_image: bool,
}

/// Match a link/image starting at char index `i`.
/// Returns (text, url, end_index_exclusive) on success.
pub fn match_link(b: &[char], i: usize) -> Option<(usize, usize, usize, usize)> {
    // b[i] == '['; find matching ']' honouring nesting and code spans
    let mut depth = 0usize;
    let mut j = i;
    let mut close = None;
    let mut in_ticks = 0usize;
    while j < b.len() {
        let c = b[j];
        if c == '`' {
            let mut n = 0;
            while j < b.len() && b[j] == '`' {
                n += 1;
                j += 1;
            }
            if n == in_ticks {
                in_ticks = 0;
            } else if in_ticks == 0 {
                in_ticks = n;
            }
            continue;
        }
        if in_ticks > 0 {
            j += 1;
            continue;
        }
        if c == '\\' {
            j += 2;
            continue;
        }
        if c == '[' {
            depth += 1;
        } else if c == ']' {
            depth -= 1;
            if depth == 0 {
                close = Some(j);
                break;
            }
        }
        j += 1;
    }
    let close = close?;
    // inline link?
    if close + 1 < b.len() && b[close + 1] == '(' {
        // find matching ')'
        let mut k = close + 1;
        let mut d = 0usize;
        let mut end = None;
        while k < b.len() {
            match b[k] {
                '\\' => {
                    k += 2;
                    continue;
                }
                '(' => d += 1,
                ')' => {
                    d -= 1;
                    if d == 0 {
                        end = Some(k);
                        break;
                    }
                }
                _ => {}
            }
            k += 1;
        }
        let end = end?;
        return Some((i, close, close + 2, end));
    }
    // reference link [text][ref] or [text][]
    if close + 1 < b.len() && b[close + 1] == '[' {
        let mut k = close + 2;
        let mut d = 1usize;
        while k < b.len() {
            match b[k] {
                '[' => d += 1,
                ']' => {
                    d -= 1;
                    if d == 0 {
                        return Some((i, close, close + 2, k));
                    }
                }
                _ => {}
            }
            k += 1;
        }
    }
    // shortcut reference
    Some((i, close, usize::MAX, close))
}

pub fn images(l: &str) -> Vec<Img> {
    let b: Vec<char> = l.chars().collect();
    let mut out = Vec::new();
    for cs in code_spans(l) {
        let _ = cs;
    }
    let spans = code_spans(l);
    let mut i = 0usize;
    while i < b.len() {
        if b[i] == '`' {
            if let Some(cs) = spans.iter().find(|c| c.start_char == i) {
                i = cs.end_char;
                continue;
            }
            i += 1;
            continue;
        }
        if (b[i] == '!' && i + 1 < b.len() && b[i + 1] == '[') || b[i] == '[' {
            let is_image = b[i] == '!';
            let start = i;
            let bi = if is_image { i + 1 } else { i };
            if let Some((tb, close, url_start, url_end)) = match_link(&b, bi) {
                let text: String = b[tb + 1..close].iter().collect();
                let url: String = if url_start == usize::MAX {
                    String::new()
                } else {
                    b[url_start..url_end].iter().collect()
                };
                out.push(Img {
                    start_char: start,
                    alt: text,
                    url,
                    is_image,
                });
                i = if url_end == usize::MAX { close + 1 } else { url_end + 1 };
                continue;
            }
        }
        i += 1;
    }
    out
}

#[derive(Clone, Debug)]
pub struct BareUrl {
    pub start_char: usize,
    pub text: String,
}

pub fn bare_urls(l: &str) -> Vec<BareUrl> {
    let b: Vec<char> = l.chars().collect();
    let mut out = Vec::new();
    let spans = code_spans(l);
    let mut i = 0usize;
    while i < b.len() {
        if spans.iter().any(|c| c.start_char == i) {
            i = spans.iter().find(|c| c.start_char == i).unwrap().end_char;
            continue;
        }
        // <url> autolink -> skip
        if b[i] == '<' {
            if let Some(e) = (i + 1..b.len()).find(|&j| b[j] == '>') {
                let inner: String = b[i + 1..e].iter().collect();
                if is_url(&inner) || inner.contains("://") {
                    i = e + 1;
                    continue;
                }
            }
            i += 1;
            continue;
        }
        // find url start
        let rest: String = b[i..].iter().collect();
        if let Some(n) = url_start_len(&rest) {
            let mut j = i + n;
            while j < b.len() && !b[j].is_whitespace() {
                let c = b[j];
                if ".,;:!?)".contains(c) && (j + 1 >= b.len() || b[j + 1].is_whitespace() || b[j + 1] == ')') {
                    break;
                }
                j += 1;
            }
            let text: String = b[i..j].iter().collect();
            if is_url(&text) {
                out.push(BareUrl {
                    start_char: i,
                    text,
                });
                i = j;
                continue;
            }
            i += 1;
        } else {
            i += 1;
        }
    }
    out
}

fn url_start_len(s: &str) -> Option<usize> {
    for p in [
        "https://",
        "http://",
        "ftp://",
        "ftps://",
        "file://",
        "mailto:",
        "www.",
        "WWW.",
    ] {
        if s.len() >= p.len() && s[..p.len()].eq_ignore_ascii_case(p) {
            return Some(p.chars().count());
        }
    }
    None
}

pub fn is_url(s: &str) -> bool {
