pub fn is_hr(l: &str) -> bool {
    let t = l.trim();
    if t.is_empty() {
        return false;
    }
    let c = t.chars().next().unwrap();
    if c != '-' && c != '*' && c != '_' {
        return false;
    }
    if !t.chars().all(|x| x == c || x == ' ') {
        return false;
    }
    t.chars().filter(|x| *x == c).count() >= 3
}

/// visual width of a line
pub fn line_width(l: &str, mode: &str) -> usize {
    match mode {
        "bytes" => l.len(),
        "chars" => l.chars().count(),
        _ => l.chars().map(|c| c.width().unwrap_or(0)).sum(),
    }
}

pub fn starts_with_pattern(s: &str, pat: &str) -> bool {
    if pat.is_empty() {
        return false;
    }
    match regex::Regex::new(pat) {
        Ok(re) => re.is_match(s),
        Err(_) => false,
    }
}

#[derive(Clone, Debug)]
pub struct NameMatch {
