    pub expected: String,
    pub in_html_element: bool,
    pub in_html_comment: bool,
}

pub fn proper_name_matches(l: &str, names: &[String]) -> Vec<NameMatch> {
    let mut out = Vec::new();
    let spans = code_spans(l);
    let lower: Vec<(usize, usize, String)> = names
        .iter()
        .map(|n| (0usize, 0usize, n.to_lowercase()))
        .collect();
    let chars: Vec<char> = l.chars().collect();
    let html = html_regions(l);
    for name in names {
        let target = if lower.iter().any(|(_, _, n)| n == &name.to_lowercase()) {
            name.to_lowercase()
        } else {
            name.to_lowercase()
        };
        // find case-insensitive occurrences bounded by non-alphanumerics
        let hay: Vec<char> = l.to_lowercase().chars().collect();
        let pat: Vec<char> = target.chars().collect();
        let mut i = 0usize;
        while i + pat.len() <= hay.len() {
            if hay[i..i + pat.len()] == pat[..] {
                let before_ok = i == 0 || !hay[i - 1].is_alphanumeric();
                let after_idx = i + pat.len();
                let after_ok =
                    after_idx >= hay.len() || !hay[after_idx].is_alphanumeric();
                if before_ok && after_ok {
                    let in_comment = html.comments.iter().any(|(a, b)| i >= *a && i < *b);
                    let in_element = html
                        .elements
                        .iter()
                        .any(|(a, b)| i >= *a && i < *b)
                        && !in_comment;
                    out.push(NameMatch {
                        start_char: i,
                        found: chars[i..i + pat.len()].iter().collect(),
                        expected: name.clone(),
                        in_html_element: in_element,
                        in_html_comment: in_comment,
                    });
                    i += pat.len();
                    continue;
                }
            }
            i += 1;
        }
    }
    let _ = spans;
    out
}

pub struct HtmlRegions {
    pub elements: Vec<(usize, usize)>,
    pub comments: Vec<(usize, usize)>,
}

pub fn html_regions(l: &str) -> HtmlRegions {
    let chars: Vec<char> = l.chars().collect();
    let mut elements = Vec::new();
    let mut comments = Vec::new();
    let mut i = 0usize;
    while i < chars.len() {
        if chars[i] == '<' {
            if l.chars().skip(i).take(4).collect::<String>() == "<!--" {
                if let Some(e) = (i + 4..chars.len()).find(|&j| {
                    l.chars().skip(j).take(3).collect::<String>() == "-->"
                }) {
                    comments.push((i, e + 3));
                    i = e + 3;
                    continue;
                }
                comments.push((i, chars.len()));
                break;
            }
            if let Some(e) = (i + 1..chars.len()).find(|&j| chars[j] == '>') {
                let inner: String = chars[i + 1..e].iter().collect();
                if is_html_tag(&inner) {
                    elements.push((i, e + 1));
                    i = e + 1;
                    continue;
                }
            }
        }
        i += 1;
    }
    HtmlRegions {
        elements,
        comments,
    }
}

pub fn is_html_tag(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    let mut t = s;
    if t.starts_with('/') {
        t = &t[1..];
    }
    if let Some(sp) = t.find(|c: char| c.is_whitespace()) {
        t = &t[..sp];
    }
    if t.is_empty() {
        return false;
    }
    let mut cs = t.chars();
    let first = cs.next().unwrap();
    if !first.is_ascii_alphabetic() {
        return false;
    }
    t.chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == ':')
}

pub fn word_positions(l: &str, term: &str) -> Vec<usize> {
    let mut out = Vec::new();
    let hay: Vec<char> = l.chars().collect();
    let pat: Vec<char> = term.chars().collect();
    let mut i = 0;
    while i + pat.len() <= hay.len() {
        if hay[i..i + pat.len()] == pat[..] {
            out.push(i);
            i += pat.len().max(1);
        } else {
            i += 1;
        }
    }
    out
}

