use unicode_width::UnicodeWidthChar;

/// A code span: byte/char offsets within a line.
#[derive(Clone, Copy, Debug)]
pub struct CodeSpan {
    pub start_char: usize,
    pub end_char: usize,
    pub ticks: usize,
}

/// Scan a line for code spans (CommonMark-ish).
pub fn code_spans(l: &str) -> Vec<CodeSpan> {
    let b: Vec<char> = l.chars().collect();
    let mut out = Vec::new();
    let mut i = 0usize;
    // track escaping
    while i < b.len() {
        if b[i] == '\\' && i + 1 < b.len() {
            i += 2;
            continue;
        }
        if b[i] != '`' {
            i += 1;
            continue;
        }
        let start = i;
        let mut n = 0;
        while i < b.len() && b[i] == '`' {
            n += 1;
            i += 1;
        }
        // find matching run
        let mut j = i;
        let mut end = None;
        while j < b.len() {
            if b[j] == '\\' {
                j += 2;
                continue;
            }
            if b[j] == '`' {
                let s2 = j;
                let mut m = 0;
                while j < b.len() && b[j] == '`' {
                    m += 1;
                    j += 1;
                }
                if m == n {
                    end = Some((s2, j));
                    break;
                }
            } else {
                j += 1;
            }
        }
        match end {
            Some((s2, e2)) => {
                out.push(CodeSpan {
                    start_char: start,
                    end_char: e2,
                    ticks: n,
                });
                i = e2;
            }
            None => {
                i = start + n;
            }
        }
    }
    out
}

/// ranges of a line that are inline code (for suppression)
pub fn code_span_ranges(l: &str) -> Vec<(usize, usize)> {
    code_spans(l).iter().map(|c| (c.start_char, c.end_char)).collect()
}

