    pub alt: String,
    pub url: String,
    pub is_image: bool,
}

/// Match a link/image starting at char index `i`.
/// Returns (text, url, end_index_exclusive) on success.
pub fn match_link(b: &[char], i: usize) -> Option<(usize, usize, usize, usize)> {
    // b[i] == '['; find matching ']' honouring nesting and code spans
    let mut depth = 0usize;
    let mut j = i;
    let mut close = None;
    let mut in_ticks = 0usize;
    while j < b.len() {
        let c = b[j];
        if c == '`' {
            let mut n = 0;
            while j < b.len() && b[j] == '`' {
                n += 1;
                j += 1;
            }
            if n == in_ticks {
                in_ticks = 0;
            } else if in_ticks == 0 {
                in_ticks = n;
            }
            continue;
        }
        if in_ticks > 0 {
            j += 1;
            continue;
        }
        if c == '\\' {
            j += 2;
            continue;
        }
        if c == '[' {
            depth += 1;
        } else if c == ']' {
            depth -= 1;
            if depth == 0 {
                close = Some(j);
                break;
            }
        }
        j += 1;
    }
    let close = close?;
    // inline link?
    if close + 1 < b.len() && b[close + 1] == '(' {
        // find matching ')'
        let mut k = close + 1;
        let mut d = 0usize;
        let mut end = None;
        while k < b.len() {
            match b[k] {
                '\\' => {
                    k += 2;
                    continue;
                }
                '(' => d += 1,
                ')' => {
                    d -= 1;
                    if d == 0 {
                        end = Some(k);
                        break;
                    }
                }
                _ => {}
            }
            k += 1;
        }
        let end = end?;
        return Some((i, close, close + 2, end));
    }
    // reference link [text][ref] or [text][]
    if close + 1 < b.len() && b[close + 1] == '[' {
        let mut k = close + 2;
        let mut d = 1usize;
        while k < b.len() {
            match b[k] {
                '[' => d += 1,
                ']' => {
                    d -= 1;
                    if d == 0 {
                        return Some((i, close, close + 2, k));
                    }
                }
                _ => {}
            }
            k += 1;
        }
    }
    // shortcut reference
    Some((i, close, usize::MAX, close))
}

pub fn images(l: &str) -> Vec<Img> {
    let b: Vec<char> = l.chars().collect();
    let mut out = Vec::new();
    for cs in code_spans(l) {
        let _ = cs;
    }
    let spans = code_spans(l);
    let mut i = 0usize;
    while i < b.len() {
        if b[i] == '`' {
            if let Some(cs) = spans.iter().find(|c| c.start_char == i) {
                i = cs.end_char;
                continue;
            }
            i += 1;
            continue;
        }
        if (b[i] == '!' && i + 1 < b.len() && b[i + 1] == '[') || b[i] == '[' {
            let is_image = b[i] == '!';
            let start = i;
            let bi = if is_image { i + 1 } else { i };
            if let Some((tb, close, url_start, url_end)) = match_link(&b, bi) {
                let text: String = b[tb + 1..close].iter().collect();
                let url: String = if url_start == usize::MAX {
                    String::new()
                } else {
                    b[url_start..url_end].iter().collect()
                };
                out.push(Img {
                    start_char: start,
                    alt: text,
                    url,
                    is_image,
                });
                i = if url_end == usize::MAX { close + 1 } else { url_end + 1 };
                continue;
            }
        }
        i += 1;
    }
    out
}

#[derive(Clone, Debug)]
pub struct BareUrl {
    pub start_char: usize,
    pub text: String,
}

pub fn bare_urls(l: &str) -> Vec<BareUrl> {
    let b: Vec<char> = l.chars().collect();
    let mut out = Vec::new();
    let spans = code_spans(l);
    let mut i = 0usize;
    while i < b.len() {
        if spans.iter().any(|c| c.start_char == i) {
            i = spans.iter().find(|c| c.start_char == i).unwrap().end_char;
            continue;
        }
        // <url> autolink -> skip
        if b[i] == '<' {
            if let Some(e) = (i + 1..b.len()).find(|&j| b[j] == '>') {
                let inner: String = b[i + 1..e].iter().collect();
                if is_url(&inner) || inner.contains("://") {
                    i = e + 1;
                    continue;
                }
            }
            i += 1;
            continue;
        }
        // find url start
        let rest: String = b[i..].iter().collect();
        if let Some(n) = url_start_len(&rest) {
            let mut j = i + n;
            while j < b.len() && !b[j].is_whitespace() {
                let c = b[j];
                if ".,;:!?)".contains(c) && (j + 1 >= b.len() || b[j + 1].is_whitespace() || b[j + 1] == ')') {
                    break;
                }
                j += 1;
            }
            let text: String = b[i..j].iter().collect();
            if is_url(&text) {
                out.push(BareUrl {
                    start_char: i,
                    text,
                });
                i = j;
                continue;
            }
            i += 1;
        } else {
            i += 1;
        }
    }
    out
}

fn url_start_len(s: &str) -> Option<usize> {
    for p in [
        "https://",
        "http://",
        "ftp://",
        "ftps://",
        "file://",
        "mailto:",
        "www.",
        "WWW.",
    ] {
        if s.len() >= p.len() && s[..p.len()].eq_ignore_ascii_case(p) {
            return Some(p.chars().count());
        }
    }
    None
}

pub fn is_url(s: &str) -> bool {
    if url_start_len(s).is_some() {
        return true;
    }
    // scheme://...
    if let Some(p) = s.find("://") {
        let scheme = &s[..p];
        if !scheme.is_empty()
            && scheme
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.')
        {
            return true;
        }
    }
    false
}

#[derive(Clone, Debug)]
pub struct Emph {
    pub start_char: usize,
    pub end_char: usize,
    pub text: String,
    pub replacement: String,
}

/// Emphasis elements with stray spaces inside the delimiters.
pub fn emphasis_bad_spaces(l: &str) -> Vec<Emph> {
    let b: Vec<char> = l.chars().collect();
    let spans = code_spans(l);
    let in_code = |i: usize| spans.iter().any(|c| i >= c.start_char && i < c.end_char);
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < b.len() {
        if in_code(i) {
            i += 1;
            continue;
        }
        let c = b[i];
        if c == '\\' {
            i += 2;
            continue;
        }
        if c != '*' && c != '_' {
            i += 1;
            continue;
        }
        let mut n = 0;
        while i + n < b.len() && b[i + n] == c {
            n += 1;
        }
        if n > 3 {
            i += n;
            continue;
        }
        let ticks = if n == 3 { 1 } else { n.min(2) };
        let d: String = std::iter::repeat(c).take(ticks).collect();
        // find closing
        let mut j = i + n;
        let mut close = None;
        while j < b.len() {
            if in_code(j) {
                j += 1;
                continue;
            }
            if b[j] == '\\' {
                j += 2;
                continue;
            }
            if b[j] == c {
                let mut m = 0;
                while j + m < b.len() && b[j + m] == c {
                    m += 1;
                }
                if m >= ticks {
                    close = Some(j);
                    break;
                }
                j += m;
                continue;
            }
            j += 1;
        }
        match close {
            Some(j) => {
                let e = j + ticks;
                let text: String = b[i..e].iter().collect();
                let inner_first = b[i + ticks];
                let inner_last = b[e - ticks - 1];
                if inner_first.is_whitespace() || inner_last.is_whitespace() {
                    // build replacement
                    let mut rep: String = d.clone();
                    let mut k = i + ticks;
                    let mut started = false;
                    while k < e - ticks {
                        let ch = b[k];
                        if !started && ch.is_whitespace() {
                            k += 1;
                            continue;
                        }
                        started = true;
                        rep.push(ch);
                        k += 1;
                    }
                    // trim trailing ws
                    let trimmed = rep.trim_end();
                    rep = format!("{}{}", d, trimmed);
                    rep.push_str(&d);
                    out.push(Emph {
                        start_char: i,
                        end_char: e,
                        text,
                        replacement: rep,
                    });
                }
                i = e;
                continue;
            }
            None => {
                i += n.max(1);
                continue;
            }
        }
    }
    out
}

