pub fn md027(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        let mut j = 0usize;
        let chars: Vec<char> = l.chars().collect();
        // consecutive '>' markers
        while j < chars.len() && chars[j] == '>' {
            j += 1;
            if j < chars.len() && chars[j] == ' ' {
                j += 1;
                while j < chars.len() && chars[j] == '>' {
                    j += 1;
                    if j < chars.len() && chars[j] == ' ' {
                        j += 1;
                    }
                }
            }
        }
        if j >= chars.len() || chars[j] != ' ' {
            continue;
        }
        let mut n = 0usize;
        while j + n < chars.len() && chars[j + n] == ' ' {
            n += 1;
        }
        if n > 1 {
            let s = doc.char_to_byte(i, j + 1);
            let e = doc.char_to_byte(i, j + n);
            out.push(
                Issue::new(
                    "MD027",
                    i + 1,
                    j + 2,
                    "Multiple spaces after quote marker (>)".to_string(),
                )
                .with_fix(Fix::new(s, e, " ")),
            );
        }
    }
    out
}

pub fn md028(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
