    let n = doc.nlines();
    let mut i = 0usize;
    while i < n {
        if skip[i] {
            i += 1;
            continue;
        }
        let l = doc.line_trimmed(i);
        if l.trim_start().starts_with('>') {
            let level = l.trim_start().chars().take_while(|c| *c == '>').count();
            // look ahead for a blank line then another blockquote line
            let mut j = i + 1;
            let mut blanks = 0usize;
            while j < n && doc.is_blank(j) {
                blanks += 1;
                j += 1;
            }
            if blanks > 0 && j < n && !skip[j] {
                let l2 = doc.line_trimmed(j);
                if l2.trim_start().starts_with('>') {
