    let desc = |kind: &str| -> String {
        if let Some(rest) = kind.strip_prefix("atx:") {
            if rest == "false" {
                "# Heading".to_string()
            } else {
                "# Heading #".to_string()
            }
        } else if let Some(rest) = kind.strip_prefix("setext:") {
            if rest == "=" {
                "Heading (underlined with =)".to_string()
            } else {
                "Heading (underlined with -)".to_string()
            }
        } else {
            String::new()
        }
    };
    let target = if style == "consistent" {
        // majority style
        let mut counts: Vec<(String, usize)> = Vec::new();
        for (_, _, k) in &items {
            match counts.iter_mut().find(|(a, _)| a == k) {
                Some((_, c)) => *c += 1,
                None => counts.push((k.clone(), 1)),
            }
        }
        counts
            .into_iter()
            .max_by_key(|(_, c)| *c)
            .map(|(k, _)| k)
            .unwrap_or_else(|| "atx:false".to_string())
    } else {
        match style.as_str() {
            "atx" => "atx:false".to_string(),
            "atx_closed" => "atx:true".to_string(),
            "setext" => "setext:-".to_string(),
            "setext_with_atx" => "setext:-".to_string(),
            "setext_with_atx_closed" => "setext:-".to_string(),
            _ => "atx:false".to_string(),
        }
    };
    let target_desc = desc(&target);
    for (i, _, k) in &items {
        if k == &target {
            continue;
        }
        // setext_with_atx allows atx headings
        if style == "setext_with_atx" && k.starts_with("atx:") {
            continue;
        }
        if style == "setext_with_atx_closed" && k.starts_with("atx:") {
            continue;
        }
        let found = desc(k);
        let msg = format!("Heading style should be {}, found {}", target_desc, found);
        out.push(
            Issue::new("MD003", i + 1, 1, msg).with_fix(Fix::new(
                doc.start(*i),
                doc.start(*i) + doc.line(*i).len(),
                &crate::rules::heading::convert_style(doc, *i, &target),
            )),
        );
    }
    out
}

pub fn convert_style(doc: &Doc, line: usize, target: &str) -> String {
    let l = doc.line_trimmed(line);
    if let Some(rest) = target.strip_prefix("atx:") {
        if let Some(h) = doc.parse_heading(line) {
            let hashes = "#".repeat(h.level);
            let text = h.text.clone();
            return if rest == "false" {
                format!("{} {}", hashes, text)
            } else {
                format!("{} {} {}", hashes, text, hashes)
            };
        }
        return l.to_string();
    }
    if let Some(rest) = target.strip_prefix("setext:") {
        let ch = if rest == "=" { '=' } else { '-' };
        return format!("{}\n{}", l, std::iter::repeat(ch).take(l.len()).collect::<String>());
    }
    l.to_string()
}

pub fn md022(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let above = cfg.i64("MD022", "lines-above", 1) as usize;
    let below = cfg.i64("MD022", "lines-below", 1) as usize;
    let at_start = cfg.boolean("MD022", "allowed-at-start", true);
    let n = doc.nlines();
    let mut items: Vec<(usize, char)> = Vec::new();
    for i in 0..n {
        if doc.parse_heading(i).is_some() {
            items.push((i, 'a'));
        } else if let Some((l, _)) = doc.setext_heading(i) {
            items.push((l, 's'));
        }
    }
    for (i, _) in &items {
        let mut blanks = 0usize;
        let mut j = *i;
        while j > 0 && doc.is_blank(j - 1) {
            blanks += 1;
            j -= 1;
        }
        let is_first_content = j == 0;
        if blanks < above && !(at_start && is_first_content) {
            let msg = if above == 1 {
                "Expected 1 blank line above heading".to_string()
            } else {
                format!("Expected {} blank lines above heading", above)
            };
            out.push(
                Issue::new("MD022", i + 1, 1, msg)
                    .with_fix(Fix::new(doc.start(*i), doc.start(*i), "\n".repeat(above - blanks))),
            );
        }
        // below
        let mut k = *i + 1;
        let end_line = if doc.parse_heading(*i).is_some() {
            *i
        } else {
            match doc.setext_heading(*i + 1) {
                Some((_, _)) => *i + 1,
                None => *i,
            }
        };
        let _ = end_line;
        let mut blanks2 = 0usize;
        let mut k = end_line + 1;
        while k < n && doc.is_blank(k) {
            blanks2 += 1;
            k += 1;
        }
        if blanks2 < below && k < n {
            let msg = if below == 1 {
                "Expected 1 blank line below heading".to_string()
            } else {
                format!("Expected {} blank lines below heading", below)
            };
            let insert_at = if end_line + 1 <= n {
                doc.start(end_line + 1)
            } else {
                doc.text.len()
            };
            out.push(
                Issue::new("MD022", end_line + 1, 1, msg)
                    .with_fix(Fix::new(insert_at, insert_at, "\n".repeat(below - blanks2))),
            );
        }
    }
    out
}

pub fn md024(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let siblings = cfg.boolean("MD024", "siblings-only", true);
    let diff_nesting = cfg.boolean("MD024", "allow-different-nesting", false);
    let hs = doc.headings();
    // track by path of heading texts
    let mut paths: Vec<(String, usize)> = Vec::new(); // (path, line)
    let mut prev: Option<(usize, String)> = None;
    for h in &hs {
        let path = if siblings {
            match prev {
                Some((pl, ref pt)) => {
                    if pl >= h.level {
                        format!("{}|{}", pt, h.text)
                    } else {
                        format!("{}", h.text)
                    }
                }
                None => h.text.clone(),
            }
        } else {
            h.text.clone()
        };
        let _ = diff_nesting;
        let mut found = None;
        for (p, l) in &paths {
            if *p == path {
                found = Some(*l);
            }
        }
        if let Some(_l) = found {
            out.push(
                Issue::new(
                    "MD024",
                    h.line + 1,
                    h.content_start_char + 1,
                    format!("Duplicate heading: '{}'.", h.text),
                ),
            );
        } else {
            paths.push((path.clone(), h.line));
        }
        prev = Some((h.level, h.text.clone()));
    }
    out
}

pub fn md025(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let level = cfg.i64("MD025", "level", 1) as usize;
    let fm_title = cfg.string("MD025", "front-matter-title", "title");
    let allow_sections = cfg.boolean("MD025", "allow-document-sections", false);
    let allow_seps = cfg.boolean("MD025", "allow-with-separators", false);
    let _ = (allow_sections, allow_seps);
    // frontmatter title
    if doc.line_trimmed(0) == "---" {
        let n = doc.nlines();
        let mut j = 1;
        while j < n {
            let l = doc.line_trimmed(j);
            if l == "---" || l == "..." {
                break;
            }
            if let Some((k, v)) = l.split_once(':') {
                if k.trim() == fm_title && !v.trim().is_empty() {
                    return out;
                }
            }
            j += 1;
        }
    }
    let hs = doc.headings();
    let mut count = 0usize;
    let mut last_thb = usize::MAX;
    for h in &hs {
        if h.level == level {
            count += 1;
            if count > 1 {
                out.push(
                    Issue::new(
                        "MD025",
                        h.line + 1,
                        h.content_start_char + 1,
                        format!("Multiple top-level headings (level {}) in the same document", level),
                    )
                    .with_fix(Fix::new(
                        doc.start(h.line),
                        doc.start(h.line),
                        "#",
                    )),
                );
            }
        }
        last_thb = h.line;
    }
    out
}

pub fn md043(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let required = cfg.strings("MD043", "headings", &[]);
    if required.is_empty() {
        return out;
    }
    let match_case = cfg.boolean("MD043", "match-case", false);
    let hs = doc.headings();
    let norm = |s: &str| if match_case { s.to_string() } else { s.to_lowercase() };
    let req: Vec<String> = required.iter().map(|s| norm(s)).collect();
    // build actual structure
    let mut actual: Vec<String> = Vec::new();
    for h in &hs {
        let indent = if h.level > 1 {
            "  ".repeat(h.level - 1)
        } else {
            String::new()
        };
        actual.push(norm(&format!("{}{}", indent, h.text)));
    }
    // pattern match: req entries may contain "*"
    let mut i = 0usize;
    for r in &req {
        if r == "*" {
            continue;
        }
        let mut matched = false;
        while i < actual.len() {
            if actual[i] == *r {
                matched = true;
                i += 1;
                break;
            }
            i += 1;
        }
        if !matched {
            out.push(Issue::new(
                "MD043",
                1,
                1,
                "Heading structure does not match the required structure".to_string(),
            ));
            return out;
        }
    }
    if i < actual.len() {
        out.push(Issue::new(
            "MD043",
            1,
            1,
            "Heading structure does not match the required structure".to_string(),
        ));
    }
    out
}

pub fn md063(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    if !cfg.boolean("MD063", "enabled", false) {
        return out;
    }
    let style = cfg.string("MD063", "style", "title_case");
    let lower_words = cfg.strings(
        "MD063",
        "lowercase-words",
        &[
            "a", "an", "and", "as", "at", "but", "by", "for", "from", "in", "into", "nor", "of",
            "off", "on", "or", "per", "so", "the", "to", "up", "via", "with", "yet",
        ],
    );
    let ignore = cfg.strings("MD063", "ignore-words", &[]);
    let preserve = cfg.boolean("MD063", "preserve-cased-words", true);
    let min_l = cfg.i64("MD063", "min-level", 1) as usize;
    let max_l = cfg.i64("MD063", "max-level", 6) as usize;
    let hs = doc.headings();
    for h in &hs {
        if h.level < min_l || h.level > max_l {
            continue;
        }
        let text = h.text.clone();
        if ignore.iter().any(|w| w == &text) {
            continue;
        }
        let converted = match style.as_str() {
            "title_case" => crate::rules::heading::title_case(&text, &lower_words, preserve),
            "sentence_case" => crate::rules::heading::sentence_case(&text, &lower_words, preserve),
            "all_caps" => crate::rules::heading::all_caps(&text, preserve),
            _ => text.clone(),
        };
        if converted != text {
            let msg = format!(
                "Heading should use title case: '{}' -> '{}'",
                text,
                converted
            );
            let s = doc.char_to_byte(h.line, h.content_start_char);
            let e = s + text.len();
            out.push(
                Issue::new("MD063", h.line + 1, h.content_start_char + 1, msg)
                    .with_fix(Fix::new(s, e, &converted)),
            );
        }
    }
    out
}

pub fn title_case(text: &str, lower_words: &[String], preserve: bool) -> String {
    let words: Vec<&str> = text.split(' ').collect();
    let mut out: Vec<String> = Vec::new();
    let n = words.len();
    for (i, w) in words.iter().enumerate() {
        if w.is_empty() {
            out.push(w.to_string());
            continue;
        }
        let lw = w.to_lowercase();
        if preserve && w.chars().any(|c| c.is_uppercase()) && !w.chars().all(|c| c.is_uppercase()) {
            out.push(w.to_string());
            continue;
        }
        if i > 0 && i < n - 1 && lower_words.contains(&lw) {
            out.push(lw);
            continue;
        }
        // capitalize first char
        let mut cs = w.chars();
        let first = cs.next().unwrap().to_uppercase().collect::<String>();
        out.push(format!("{}{}", first, lw.chars().skip(1).collect::<String>()));
    }
    out.join(" ")
}

pub fn sentence_case(text: &str, _lower_words: &[String], preserve: bool) -> String {
    let mut out = String::new();
    let mut cap = true;
    for (i, c) in text.chars().enumerate() {
        if preserve && c.is_uppercase() {
            out.push(c);
            cap = false;
            continue;
        }
        if cap && c.is_alphabetic() {
            out.extend(c.to_uppercase());
            cap = false;
        } else {
            out.push(c.to_lowercase().next().unwrap_or(c));
        }
        if c == '.' || c == '!' || c == '?' {
            cap = true;
        }
        let _ = i;
    }
    out
}

pub fn all_caps(text: &str, _preserve: bool) -> String {
    text.to_uppercase()
}
