    if j == start || j >= chars.len() {
        return None;
    }
    if chars[j] != '.' && chars[j] != ')' {
        return None;
    }
    let marker: String = chars[start..=j].iter().collect();
    let num: u64 = chars[start..j].iter().collect::<String>().parse().unwrap_or(0);
    let mut k = j + 1;
    let mut sp = 0usize;
    while k < chars.len() && chars[k] == ' ' {
        sp += 1;
        k += 1;
    }
    if sp == 0 {
        return None;
    }
    Some((indent, marker, true, num, sp, k))
}

pub fn list_items(doc: &Doc) -> Vec<LItem> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        if let Some((indent, marker, ordered, num, sp, cs)) = parse_marker(l) {
            out.push(LItem {
                line: i,
                indent,
                marker: marker.clone(),
                ordered,
                number: num,
                spaces: sp,
                content_start_char: cs,
                content: l[cs..].to_string(),
            });
        }
    }
    out
}

pub fn md004(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let style = cfg.string("MD004", "style", "consistent");
    let items = list_items(doc);
    let ul: Vec<&LItem> = items.iter().filter(|i| !i.ordered).collect();
    if ul.is_empty() {
        return out;
    }
    let expected = if style == "consistent" {
        ul[0].marker.clone()
    } else {
        match style.as_str() {
            "asterisk" => "*".to_string(),
            "plus" => "+".to_string(),
            "dash" => "-".to_string(),
            "sublist" => ul[0].marker.clone(),
            _ => ul[0].marker.clone(),
        }
    };
    for it in &ul {
        if it.marker != expected {
            let msg = format!(
                "List marker '{}' does not match expected style '{}'",
                it.marker,
                expected
            );
            let indent_len = doc.line_trimmed(it.line).len()
                - doc.line_trimmed(it.line).trim_start().len();
            out.push(
                Issue::new("MD004", it.line + 1, indent_len + 1, msg).with_fix(Fix::new(
                    doc.char_to_byte(it.line, indent_len),
                    doc.char_to_byte(it.line, indent_len + 1),
                    &expected,
                )),
            );
        }
    }
    out
}

pub fn md005(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let items = list_items(doc);
    let mut stack: Vec<usize> = Vec::new();
    let mut first_at_level: Vec<usize> = Vec::new();
    for it in &items {
        while stack.len() > 0 && it.indent < stack.last().unwrap() + 2 {
            stack.pop();
            first_at_level.pop();
        }
        let level = stack.len();
        if level >= first_at_level.len() {
            first_at_level.push(it.indent);
        } else {
            let expected = first_at_level[level];
            if it.indent != expected {
                let msg = format!(
                    "Expected indentation of {} spaces, found {}",
                    expected,
                    it.indent
                );
                let spaces_needed = expected.saturating_sub(it.indent);
                let s = doc.char_to_byte(it.line, 0);
                let e = doc.char_to_byte(it.line, it.indent);
                let rep = if spaces_needed > it.indent {
                    " ".repeat(spaces_needed)
                } else {
                    String::new()
                };
                out.push(
                    Issue::new("MD005", it.line + 1, expected + 1, msg).with_fix(Fix::new(
                        s,
                        e,
                        &rep,
                    )),
                );
            }
        }
        stack.push(it.indent);
    }
    out
}

pub fn md007(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let indent_v = cfg.i64("MD007", "indent", 2) as usize;
    let start_indented = cfg.boolean("MD007", "start-indented", false);
    let start_indent = cfg.i64("MD007", "start-indent", 2) as usize;
    let items = list_items(doc);
    let mut stack: Vec<usize> = Vec::new();
    for it in &items {
        if it.ordered {
            // MD007 only applies to unordered lists
            continue;
        }
        while stack.len() > 0 && it.indent <= *stack.last().unwrap() {
            stack.pop();
        }
        let depth = stack.len();
        let expected = if depth == 0 {
            if start_indented {
                start_indent
            } else {
                0
            }
        } else {
            depth * indent_v
        };
        if it.indent != expected {
            let msg = format!(
                "Expected {} spaces for indent depth {}, found {}",
                expected,
                depth,
                it.indent
            );
            let s = doc.char_to_byte(it.line, 0);
            let e = doc.char_to_byte(it.line, it.indent);
            let rep = " ".repeat(expected);
            out.push(
                Issue::new("MD007", it.line + 1, expected + 1, msg)
                    .with_fix(Fix::new(s, e, &rep)),
            );
        }
        stack.push(it.indent);
    }
    out
}

pub fn md029(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let style = cfg.string("MD029", "style", "one-or-ordered");
    let items = list_items(doc);
    let ol: Vec<&crate::rules::list::LItem> = items.iter().filter(|i| i.ordered).collect();
    if ol.is_empty() {
        return out;
    }
    // Only nested ordered lists are checked (rumdl bug)
    let mut stack: Vec<usize> = Vec::new();
    let mut groups: Vec<Vec<usize>> = Vec::new();
    for (idx, it) in items.iter().enumerate() {
        while stack.len() > 0 && it.indent <= *stack.last().unwrap() {
            stack.pop();
        }
        if stack.len() > 0 {
            groups.push(vec![idx]);
        } else {
            groups.push(vec![]);
        }
        stack.push(it.indent);
    }
    // group nested ordered items by their parent list
    let mut lists: Vec<Vec<usize>> = Vec::new();
    let mut cur: Vec<usize> = Vec::new();
    let mut cur_depth = 0usize;
    let mut prev_indent = usize::MAX;
    for (idx, it) in items.iter().enumerate() {
        let depth = if groups[idx].is_empty() { 0 } else { 1 };
        let _ = depth;
        if it.ordered && it.indent > 0 {
            if cur_depth != 0 && it.indent != prev_indent {
                if !cur.is_empty() {
                    lists.push(std::mem::take(&mut cur));
                }
            }
            cur.push(idx);
            cur_depth = 1;
            prev_indent = it.indent;
        } else {
            if !cur.is_empty() {
                lists.push(std::mem::take(&mut cur));
            }
            cur_depth = 0;
            prev_indent = usize::MAX;
        }
    }
    if !cur.is_empty() {
        lists.push(cur);
    }
    // document style for "consistent"
    let mut doc_style = "";
    if style == "consistent" {
        let mut ones = 0usize;
        let mut ordered = 0usize;
        for l in &lists {
            let nums: Vec<u64> = l.iter().map(|i| ol[*i].number).collect();
            if nums.iter().all(|n| *n == 1) {
                ones += 1;
            } else {
                ordered += 1;
            }
        }
        doc_style = if ones > ordered {
            "one"
        } else {
            "ordered"
        };
    }
    for l in &lists {
        let nums: Vec<u64> = l.iter().map(|i| ol[*i].number).collect();
        let is_one = nums.iter().all(|n| *n == 1);
        let expected_style = if style == "consistent" {
            doc_style.to_string()
        } else if style == "one" || style == "one-one" {
            "one".to_string()
        } else if style == "ordered" {
            "ordered".to_string()
        } else if style == "ordered0" {
            "ordered0".to_string()
        } else {
            if is_one {
                "one".to_string()
            } else {
                "ordered".to_string()
            }
        };
        let explicit = style != "consistent" && style != "one-or-ordered";
        let style_word = if explicit {
            "configured style"
        } else if style == "consistent" {
            "document style"
        } else {
            "list style"
        };
        let mut prev = 0u64;
        for (k, idx) in l.iter().enumerate() {
            let it = ol[*idx];
            let expected: u64 = match expected_style.as_str() {
                "one" => 1,
                "ordered" => {
                    if k == 0 {
                        it.number
                    } else {
                        prev + 1
                    }
                }
                "ordered0" => k as u64,
                _ => it.number,
            };
            prev = it.number;
            if it.number != expected {
                let msg = format!(
                    "Ordered list item number {} does not match {} '{}' (expected {})",
                    it.number,
                    style_word,
                    expected_style,
                    expected
                );
                let fixable = expected_style == "one" || expected_style == "ordered";
                let indent_len = it.indent;
                let s = doc.char_to_byte(it.line, indent_len);
                let e = doc.char_to_byte(it.line, indent_len + it.marker.chars().count());
                let rep = format!("{}{}", expected, &it.marker[it.marker.len() - 1..]);
                let mut iss = Issue::new("MD029", it.line + 1, indent_len + 1, msg);
                if fixable {
                    iss = iss.with_fix(Fix::new(s, e, &rep));
                }
                out.push(iss);
            }
        }
    }
    out
}

pub fn md030(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let ul_single = cfg.i64("MD030", "ul-single", 1) as usize;
    let ul_multi = cfg.i64("MD030", "ul-multi", 1) as usize;
    let ol_single = cfg.i64("MD030", "ol-single", 1) as usize;
    let ol_multi = cfg.i64("MD030", "ol-multi", 1) as usize;
    let items = list_items(doc);
    let n = doc.nlines();
    for it in &items {
        let l = doc.line_trimmed(it.line);
        let chars: Vec<char> = l.chars().collect();
        let mut sp = it.spaces;
        let _ = &mut sp;
        // determine multi-line: is there a continuation?
        let mut multi = false;
        let mut j = it.line + 1;
        let mut blanks = 0;
        while j < n {
            if doc.is_blank(j) {
                blanks += 1;
                j += 1;
                continue;
            }
            if blanks > 1 {
                break;
            }
            let l2 = doc.line_trimmed(j);
            let ind2 = l2.len() - l2.trim_start().len();
            let cont = if it.indent > 0 {
                ind2 > it.indent
            } else {
                ind2 > 0
            };
            if cont {
                multi = true;
            }
            break;
        }
        let expected = if it.ordered {
            if multi {
                ol_multi
            } else {
                ol_single
            }
        } else if multi {
            ul_multi
        } else {
            ul_single
        };
        if it.spaces != expected {
            let msg = format!(
                "Spaces after list markers (Expected: {}; Actual: {})",
                expected,
                it.spaces
            );
            let s = doc.char_to_byte(it.line, it.content_start_char - it.spaces);
            let e = doc.char_to_byte(it.line, it.content_start_char);
            out.push(
                Issue::new("MD030", it.line + 1, it.content_start_char - it.spaces + 1, msg)
                    .with_fix(Fix::new(s, e, &" ".repeat(expected))),
            );
        }
    }
    out
}

pub fn md032(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let lazy = cfg.boolean("MD032", "allow-lazy-continuation", true);
    let _ = lazy;
    let items = list_items(doc);
    // group consecutive items into lists
    let mut i = 0usize;
    let n = doc.nlines();
    while i < items.len() {
        let start = items[i].line;
        let mut j = i + 1;
        while j < items.len() && items[j].line == items[j - 1].line + 1 {
            j += 1;
        }
        // check preceding blank line
        let mut blanks = 0usize;
        let mut k = start;
        while k > 0 && doc.is_blank(k - 1) {
            blanks += 1;
            k -= 1;
        }
        let at_start = k == 0;
        let prev_is_list_item = items.iter().any(|it| it.line + 1 == k && !doc.is_blank(k - 1));
        if blanks == 0 && !at_start {
            // previous line is not blank: check if it's a list item or lazy continuation
            let pl = doc.line_trimmed(start - 1);
            let is_marker_line = parse_marker(pl).is_some();
            let is_cont = {
                let ind = pl.len() - pl.trim_start().len();
                ind > 0 && !is_marker_line
            };
            if !is_marker_line && !is_cont {
                out.push(
                    Issue::new(
                        "MD032",
                        start + 1,
                        1,
                        "List should be preceded by blank line".to_string(),
                    )
                    .with_fix(Fix::new(doc.start(start), doc.start(start), "\n")),
                );
            }
        }
        // check following
        let last = items[j - 1].line;
        let mut m = last + 1;
        while m < n && doc.is_blank(m) {
            m += 1;
        }
        if m < n && m == last + 1 {
            // no blank line after: allowed (lazy continuation)
        }
        i = j;
    }
    out
}

pub fn md069(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        let first = match parse_marker(l) {
            Some(x) => x,
            None => continue,
        };
        // nested marker?
        let rest_start = first.5;
        let rest = &l[rest_start..];
        let second = parse_marker(rest);
        match second {
            Some((_, m2, false, _, _, _)) if first.1.chars().all(|c| c == '-' || c == '*' || c == '+') => {
                let msg = format!(
                    "Duplicate list marker '{} {}' - likely copy-paste error",
                    first.1,
                    m2
                );
                // fix: remove the first marker (and its following space)
                let indent_len = first.0;
                let s = doc.char_to_byte(i, indent_len);
                let e = doc.char_to_byte(i, first.5);
                out.push(
                    Issue::new("MD069", i + 1, indent_len + 1, msg)
                        .with_fix(Fix::new(s, e, "")),
                );
            }
            _ => {}
        }
    }
    out
}
