pub fn md051(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let style = cfg.string("MD051", "anchor-style", "github");
    let hs = doc.headings();
    let anchors: Vec<String> = hs
        .iter()
        .map(|h| crate::rules::link::slug(&h.text, &style))
        .collect();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::links_all(l) {
            if !m.url.starts_with('#') {
                continue;
            }
            let frag = &m.url[1..];
            if !anchors.iter().any(|a| a == frag) {
                let msg = format!(
                    "Link anchor '{}' does not exist in document headings",
                    m.url
                );
                let s = doc.char_to_byte(i, m.url_start_char);
                let e = doc.char_to_byte(i, m.url_start_char + m.url.chars().count());
                out.push(Issue::new("MD051", i + 1, m.url_start_char + 1, msg)
                    .with_fix_if(if !anchors.is_empty() {
                        Some(Fix::new(s, e, &format!("#{}", anchors[0])))
                    } else {
                        None
                    }));
            }
        }
    }
    out
}

pub fn slug(text: &str, style: &str) -> String {
    let mut out = String::new();
    let mut prev_dash = false;
    for c in text.chars() {
        if c.is_alphanumeric() {
            out.push(c);
            prev_dash = false;
        } else if c == '_' {
            if style == "kramdown" {
                continue;
            }
            out.push('_');
            prev_dash = false;
        } else if c.is_whitespace() || c == '-' || c == '.' {
            if !prev_dash {
                out.push('-');
                prev_dash = true;
            }
        } else {
            if style == "kramdown" {
                continue;
            }
            out.push(c);
            prev_dash = false;
        }
    }
    if style == "bitbucket" {
        out = format!("markdown-header-{}", out);
    }
    out.trim_matches('-').to_string()
}

pub fn md052(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
