    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::reference_uses(l) {
            if names
                .iter()
                .any(|n| n.eq_ignore_ascii_case(&m.name))
            {
                continue;
            }
            let msg = format!("Reference '{}' not found", m.name);
            out.push(Issue::new("MD052", i + 1, m.start_char + 1, msg));
        }
    }
    out
}

#[derive(Clone, Debug)]
pub struct RefDef {
    pub line: usize,
    pub name: String,
    pub url: String,
}

pub fn definitions(doc: &Doc) -> Vec<RefDef> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        if let Some(rest) = l.strip_prefix('[') {
            if let Some(p) = rest.find("]:") {
                let name = &rest[..p];
                if !name.is_empty() && !name.contains(char::is_whitespace) {
                    out.push(RefDef {
                        line: i,
                        name: name.to_string(),
                        url: rest[p + 2..].trim().to_string(),
                    });
                }
            }
        }
    }
    out
}

pub fn md053(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let ignored = cfg.strings("MD053", "ignored-definitions", &[]);
    let defs = definitions(doc);
    if defs.is_empty() {
        return out;
    }
    // collect used references
    let mut used: Vec<String> = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::reference_uses(l) {
            used.push(m.name.to_lowercase());
        }
        for m in crate::rules::inline::links_all(l) {
            if m.ref_name.is_some() {
                used.push(m.ref_name.unwrap().to_lowercase());
            }
        }
    }
    for d in &defs {
        if ignored.iter().any(|x| x.eq_ignore_ascii_case(&d.name)) {
            continue;
        }
        if !used.iter().any(|u| u == &d.name.to_lowercase()) {
            let msg = format!("Unused link/image reference: [{}]", d.name);
            let indent = doc.line_trimmed(d.line).len()
                - doc.line_trimmed(d.line).trim_start().len();
            let line_len = doc.line(d.line).len();
            out.push(
                Issue::new("MD053", d.line + 1, indent + 1, msg).with_fix(Fix::new(
                    doc.start(d.line),
                    doc.start(d.line) + line_len,
                    "",
                )),
            );
        }
    }
    out
}

pub fn md054(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let autolink = cfg.boolean("MD054", "autolink", true);
    let inline = cfg.boolean("MD054", "inline", true);
    let full = cfg.boolean("MD054", "full", true);
    let collapsed = cfg.boolean("MD054", "collapsed", true);
    let shortcut = cfg.boolean("MD054", "shortcut", true);
    let url_inline = cfg.boolean("MD054", "url-inline", true);
