pub fn slug(text: &str, style: &str) -> String {
    let mut out = String::new();
    let mut prev_dash = false;
    for c in text.chars() {
        if c.is_alphanumeric() {
            out.push(c);
            prev_dash = false;
        } else if c == '_' {
            if style == "kramdown" {
                continue;
            }
            out.push('_');
            prev_dash = false;
        } else if c.is_whitespace() || c == '-' || c == '.' {
            if !prev_dash {
                out.push('-');
                prev_dash = true;
            }
        } else {
            if style == "kramdown" {
                continue;
            }
            out.push(c);
            prev_dash = false;
        }
