pub fn definitions(doc: &Doc) -> Vec<RefDef> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        if let Some(rest) = l.strip_prefix('[') {
            if let Some(p) = rest.find("]:") {
                let name = &rest[..p];
                if !name.is_empty() && !name.contains(char::is_whitespace) {
                    out.push(RefDef {
                        line: i,
                        name: name.to_string(),
                        url: rest[p + 2..].trim().to_string(),
                    });
                }
            }
        }
    }
    out
}

pub fn md053(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let ignored = cfg.strings("MD053", "ignored-definitions", &[]);
    let defs = definitions(doc);
    if defs.is_empty() {
        return out;
    }
    // collect used references
    let mut used: Vec<String> = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::reference_uses(l) {
            used.push(m.name.to_lowercase());
        }
        for m in crate::rules::inline::links_all(l) {
            if m.ref_name.is_some() {
                used.push(m.ref_name.unwrap().to_lowercase());
            }
        }
    }
    for d in &defs {
        if ignored.iter().any(|x| x.eq_ignore_ascii_case(&d.name)) {
            continue;
        }
        if !used.iter().any(|u| u == &d.name.to_lowercase()) {
            let msg = format!("Unused link/image reference: [{}]", d.name);
            let indent = doc.line_trimmed(d.line).len()
                - doc.line_trimmed(d.line).trim_start().len();
            let line_len = doc.line(d.line).len();
            out.push(
                Issue::new("MD053", d.line + 1, indent + 1, msg).with_fix(Fix::new(
                    doc.start(d.line),
                    doc.start(d.line) + line_len,
                    "",
                )),
            );
        }
    }
    out
}

pub fn md054(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let autolink = cfg.boolean("MD054", "autolink", true);
    let inline = cfg.boolean("MD054", "inline", true);
    let full = cfg.boolean("MD054", "full", true);
    let collapsed = cfg.boolean("MD054", "collapsed", true);
    let shortcut = cfg.boolean("MD054", "shortcut", true);
    let url_inline = cfg.boolean("MD054", "url-inline", true);
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::links_all(l) {
            let bad = match m.kind {
                "inline" => !inline,
                "full" => !full,
                "collapsed" => !collapsed,
                "shortcut" => !shortcut,
                "autolink" => !autolink,
                "url-inline" => !url_inline,
                _ => false,
            };
            if bad {
                let msg = crate::rules::link::md054_message(m.kind);
                out.push(Issue::new("MD054", i + 1, m.start_char + 1, msg));
            }
        }
    }
    out
}

pub fn md054_message(kind: &str) -> String {
    match kind {
        "inline" => "Use of the inline link style is not allowed".to_string(),
        "full" => "Use of the full reference link style is not allowed".to_string(),
        "collapsed" => "Use of the collapsed reference link style is not allowed".to_string(),
        "shortcut" => "Use of the shortcut reference link style is not allowed".to_string(),
        "autolink" => "Use of the autolink style is not allowed".to_string(),
        "url-inline" => "Use of the URL inline link style is not allowed".to_string(),
        _ => String::new(),
    }
}

pub fn md057(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    let base = std::path::Path::new(&_ctx.file)
        .parent()
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| std::path::PathBuf::from("."));
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::links_all(l) {
            if m.url.is_empty() {
                continue;
            }
            if m.url.contains("://")
                || m.url.starts_with('#')
                || m.url.starts_with("mailto:")
                || m.url.starts_with('/')
            {
                continue;
            }
            if m.kind == "shortcut" || m.kind == "collapsed" || m.kind == "full" {
                continue;
            }
            let target = m.url.split('#').next().unwrap_or(&m.url);
            if target.is_empty() {
                continue;
            }
            if crate::rules::inline::is_url(target) {
                continue;
            }
            let p = base.join(target);
            let exists = if p.is_file() {
                true
            } else if target.ends_with(".html") || target.ends_with(".htm") {
                let alt = p.with_extension("md");
                alt.exists() || p.with_extension("htm").exists()
            } else {
                false
            };
            if !exists {
                let msg = format!("Relative link '{}' does not exist", target);
                let col = doc.line_trimmed(i).find(target).map(|p| p + 1).unwrap_or(1);
                out.push(Issue::new("MD057", i + 1, col, msg));
            }
        }
    }
    out
}

pub fn md059(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let prohibited = cfg.strings("MD059", "prohibited-texts", &["click here", "here", "link", "more"]);
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::links_all(l) {
            if m.is_image {
                continue;
            }
            let text = m.text.trim().to_lowercase();
            if prohibited.iter().any(|p| p.to_lowercase() == text) {
                let msg = "Link text should be descriptive".to_string();
                out.push(Issue::new("MD059", i + 1, m.start_char + 1, msg));
            }
        }
    }
    out
}

pub fn md062(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for m in crate::rules::inline::links_all(l) {
            if m.kind != "inline" && m.kind != "url-inline" {
                continue;
            }
            let url = &m.url;
            if url.trim_start() != *url || url.trim_end() != *url {
                let lead = url.starts_with(|c: char| c.is_whitespace());
                let trail = url.ends_with(|c: char| c.is_whitespace());
                let what = if m.is_image {
                    "Image destination"
                } else {
                    "Link destination"
                };
                let msg = if lead && trail {
                    format!("{} has leading and trailing whitespace", what)
                } else if trail {
                    format!("{} has trailing whitespace", what)
                } else {
                    format!("{} has leading whitespace", what)
                };
                let s = doc.char_to_byte(i, m.url_start_char);
                let e = doc.char_to_byte(i, m.url_start_char + url.chars().count());
                out.push(
                    Issue::new("MD062", i + 1, m.start_char + 1, msg)
                        .with_fix(Fix::new(s, e, url.trim())),
                );
            }
        }
    }
    out
}
