                        kind: "autolink",
                        is_image: false,
                        ref_name: None,
                    });
                    i = e + 1;
                    continue;
                }
                // url-inline style [text](<url>)
                i += 1;
                continue;
            }
            i += 1;
            continue;
        }
        if b[i] == '!' && i + 1 < b.len() && b[i + 1] == '[' {
            if let Some(li) = parse_link(&b, i + 1, true, &spans, &defs) {
                let end = li.end_char;
                out.push(li);
                i = end;
                continue;
            }
        }
        if b[i] == '[' {
            if let Some(li) = parse_link(&b, i, false, &spans, &defs) {
                let end = li.end_char;
                out.push(li);
                i = end;
                continue;
            }
        }
        i += 1;
    }
    out
}

fn ref_def_starts(l: &str) -> Vec<usize> {
    let mut out = Vec::new();
    let trimmed = l.trim_start();
    if trimmed.starts_with('[') {
        if let Some(p) = trimmed.find("]:") {
            let name = &trimmed[1..p];
            if !name.contains(char::is_whitespace) {
                out.push(l.len() - trimmed.len());
            }
        }
    }
    out
}

fn parse_link(
    b: &[char],
    start: usize,
    is_image: bool,
    spans: &[(usize, usize)],
    defs: &[usize],
) -> Option<LinkInfo> {
    let m = match_link(b, start)?;
    let (tb, close, url_start, url_end) = m;
    let text: String = b[tb + 1..close].iter().collect();
    if url_start == usize::MAX {
        // shortcut or collapsed or definition
        let after = b.get(close + 1).copied().unwrap_or(' ');
        if after == '[' {
            // collapsed [text][]
            let mut k = close + 2;
            let mut d = 1usize;
            let mut e = None;
            while k < b.len() {
                match b[k] {
                    '[' => d += 1,
                    ']' => {
                        d -= 1;
                        if d == 0 {
                            e = Some(k);
                            break;
                        }
                    }
                    _ => {}
                }
                k += 1;
            }
            let e = e?;
            return Some(LinkInfo {
                start_char: start,
                end_char: e + 1,
                text,
                url: String::new(),
                url_start_char: close + 2,
                kind: "collapsed",
                is_image,
                ref_name: Some(String::new()),
            });
        }
        // definition line?
        if defs.contains(&start) {
            return None;
        }
        // shortcut reference
        return Some(LinkInfo {
            start_char: start,
            end_char: close + 1,
            text,
            url: String::new(),
            url_start_char: start,
            kind: "shortcut",
            is_image,
            ref_name: Some(text.clone()),
        });
    }
    let url: String = b[url_start..url_end].iter().collect();
    // full reference [text][ref]
    if url_start == close + 2 && url_end < b.len() && b[url_end] == ']' && url_end > close + 2 {
        let refname: String = b[close + 2..url_end].iter().collect();
        return Some(LinkInfo {
            start_char: start,
            end_char: url_end + 1,
            text,
            url: String::new(),
            url_start_char: close + 2,
            kind: "full",
            is_image,
            ref_name: Some(refname),
        });
    }
    // inline
    let kind = if is_url(&url) && text == url {
        "url-inline"
    } else {
        "inline"
    };
    Some(LinkInfo {
        start_char: start,
        end_char: url_end + 1,
        text,
        url,
        url_start_char: url_start,
        kind,
        is_image,
        ref_name: None,
    })
}

pub fn links_with_bad_text(l: &str) -> Vec<LinkInfo> {
    links_all(l)
        .into_iter()
        .filter(|m| m.kind == "inline" && (m.text.starts_with(' ') || m.text.ends_with(' ')))
        .collect()
}

pub fn empty_links(l: &str) -> Vec<LinkInfo> {
    links_all(l)
        .into_iter()
        .filter(|m| m.kind == "inline" && !m.is_image && (m.text.trim().is_empty() || m.url.trim().is_empty()))
        .collect()
}

pub fn reference_uses(l: &str) -> Vec<LinkInfo> {
    links_all(l)
        .into_iter()
        .filter(|m| m.ref_name.is_some())
        .collect()
}

