        let mut cnt = [0usize; 2];
        for (_, _, _, c) in &segs {
            if *c == '*' {
                cnt[0] += 1;
            } else {
                cnt[1] += 1;
            }
        }
        if cnt[1] > cnt[0] {
            '_'
        } else {
            '*'
        }
    } else if style == "underscore" {
        '_'
