use crate::config::Config;
use crate::doc::Doc;
use crate::lint::Ctx;
use crate::rules::{Fix, Issue};

#[derive(Clone, Debug)]
pub struct Table {
    pub start_line: usize,
    pub end_line: usize,
    pub rows: Vec<(usize, usize, usize, Vec<String>, bool)>, // line, start, end, cells, has_pipes_both
}

pub fn tables(doc: &Doc) -> Vec<Table> {
    let skip = doc.non_text_lines();
    let mut out: Vec<Table> = Vec::new();
    let n = doc.nlines();
    let mut i = 0usize;
    while i < n {
        if skip[i] {
            i += 1;
            continue;
        }
        if !is_table_row(doc.line_trimmed(i)) {
            i += 1;
            continue;
        }
        // need a separator row next
        if i + 1 >= n || !is_table_sep(doc.line_trimmed(i + 1)) {
            i += 1;
            continue;
        }
        let start = i;
        let mut end = i + 1;
        let mut rows = Vec::new();
        while end < n && !skip[end] && is_table_row(doc.line_trimmed(end)) {
            let l = doc.line_trimmed(end);
            let cells = split_cells(l);
            let has_pipes_both =
                l.starts_with('|') && l.trim_end().ends_with('|');
            rows.push((end, 0, l.len(), cells, has_pipes_both));
            end += 1;
        }
        out.push(Table {
            start_line: start,
            end_line: end - 1,
            rows,
        });
        i = end;
    }
    out
}

fn is_table_row(l: &str) -> bool {
    let t = l.trim();
    if !t.contains('|') {
        return false;
    }
    if t.is_empty() {
        return false;
    }
    // must have at least one pipe not at the ends
    if !t.starts_with('|') && !t.ends_with('|') {
        return false;
    }
    true
}

fn is_table_sep(l: &str) -> bool {
    let t = l.trim();
    if t.is_empty() || !t.contains('|') {
        return false;
    }
    let cells: Vec<&str> = t.trim_matches('|').split('|').collect();
    if cells.is_empty() {
        return false;
    }
    cells.iter().all(|c| {
        let c = c.trim();
        !c.is_empty() && c.chars().all(|x| x == '-' || x == ':')
    })
}

fn split_cells(l: &str) -> Vec<String> {
    let t = l.trim();
    let inner = t.trim_start_matches('|').trim_end_matches('|');
    inner.split('|').map(|s| s.to_string()).collect()
}

pub fn md055(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let style = cfg.string("MD055", "style", "consistent");
    for t in tables(doc) {
        let expected = if style == "consistent" {
            let mut with = 0usize;
            let mut without = 0usize;
            for (_, _, _, _, both) in &t.rows {
                if *both {
                    with += 1;
                } else {
                    without += 1;
                }
            }
            if with >= without {
                true
            } else {
                false
            }
        } else {
            style == "leading_trailing"
        };
        let desc = if expected {
            "leading and trailing"
        } else {
            "no leading or trailing"
        };
        for (line, _, _, _, both) in &t.rows {
            if *both != expected {
                let msg = format!("Table pipe style should be {}", desc);
                let l = doc.line_trimmed(*line);
                let target: String = if expected { "|" } else { "" };
                let mut fixes: Vec<Fix> = Vec::new();
                let s = doc.start(*line);
                if expected {
                    fixes.push(Fix::new(s, s, "|"));
                    fixes.push(Fix::new(s + l.len(), s + l.len(), "|"));
                } else {
                    if l.starts_with('|') {
                        fixes.push(Fix::new(s, s + 1, ""));
                    }
                    if l.trim_end().ends_with('|') {
                        fixes.push(Fix::new(
                            s + l.len() - 1,
                            s + l.len(),
                            "",
                        ));
                    }
                }
                let _ = target;
                out.push(
                    Issue::new("MD055", line + 1, 1, msg).with_fixes(fixes),
                );
            }
        }
    }
    out
}

pub fn md056(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    for t in tables(doc) {
        if t.rows.is_empty() {
            continue;
        }
        let header_cols = t.rows[0].3.len();
        for (line, _, _, cells, _) in &t.rows {
            if cells.len() != header_cols {
                let msg = format!(
                    "Table row has {} cells, but expected {}",
                    cells.len(),
                    header_cols
                );
                let l = doc.line_trimmed(*line);
                if cells.len() < header_cols {
                    let s = doc.start(*line) + l.len();
                    let add = (header_cols - cells.len()) as usize;
                    let rep = " |".repeat(add);
                    out.push(
                        Issue::new("MD056", line + 1, l.len() + 1, msg)
                            .with_fix(Fix::new(s, s, &rep)),
                    );
                } else {
                    // remove extra cells
                    let mut idx = l.len();
                    let mut chars = l.chars().collect::<Vec<char>>();
                    let mut extra = cells.len() - header_cols;
                    let mut end = l.len();
                    let mut pos = chars.len();
                    let mut count = 0;
                    while pos > 0 {
                        if chars[pos - 1] == '|' {
                            count += 1;
                            if count > header_cols {
                                end = pos - 1;
                            }
                        }
                        pos -= 1;
                    }
                    let _ = extra;
                    let _ = idx;
                    let s = doc.start(*line) + end;
                    out.push(
                        Issue::new("MD056", line + 1, end + 1, msg)
                            .with_fix(Fix::new(s, s + (l.len() - end), "")),
                    );
                }
            }
        }
    }
    out
}

pub fn md058(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let min_before = cfg.i64("MD058", "minimum-before", 1) as usize;
    let min_after = cfg.i64("MD058", "minimum-after", 1) as usize;
    for t in tables(doc) {
        let mut blanks = 0usize;
        let mut j = t.start_line;
        while j > 0 && doc.is_blank(j - 1) {
            blanks += 1;
            j -= 1;
        }
        if blanks < min_before && t.start_line > 0 {
            let msg = if min_before == 1 {
                "Missing blank line before table".to_string()
            } else {
                format!("Missing {} blank lines before table", min_before)
            };
            out.push(
                Issue::new("MD058", t.start_line + 1, 1, msg).with_fix(Fix::new(
                    doc.start(t.start_line),
                    doc.start(t.start_line),
                    "\n",
                )),
            );
        }
        let mut blanks = 0usize;
        let mut j = t.end_line + 1;
        while j < doc.nlines() && doc.is_blank(j) {
            blanks += 1;
            j += 1;
        }
        if blanks < min_after && j < doc.nlines() {
            let msg = if min_after == 1 {
                "Missing blank line after table".to_string()
            } else {
                format!("Missing {} blank lines after table", min_after)
            };
            let at = doc.start(t.end_line + 1);
            out.push(
                Issue::new("MD058", t.end_line + 1, 1, msg)
                    .with_fix(Fix::new(at, at, "\n")),
            );
        }
    }
    out
}

pub fn md060(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    if !cfg.boolean("MD060", "enabled", false) {
        return out;
    }
    let style = cfg.string("MD060", "style", "any");
    if style == "any" {
        return out;
    }
    let max_width = cfg.i64("MD060", "max-width", 0) as usize;
    let header_align = cfg.string("MD060", "column-align-header", "auto");
    let body_align = cfg.string("MD060", "column-align-body", "auto");
    let align = cfg.string("MD060", "column-align", "auto");
    let loose = cfg.boolean("MD060", "loose-last-column", false);
    let _ = (max_width, header_align, body_align, align, loose);
    for t in tables(doc) {
        if t.rows.len() < 2 {
            continue;
        }
        let ncol = t.rows[0].3.len();
        let widths: Vec<usize> = (0..ncol)
            .map(|c| {
                t.rows
                    .iter()
                    .map(|r| r.3.get(c).map(|s| s.trim().chars().count()).unwrap_or(0))
                    .max()
                    .unwrap_or(0)
            })
            .collect();
        for (li, line, _, cells, _) in t.rows.iter().enumerate() {
            let l = doc.line_trimmed(*line);
            let _ = l;
            let mut rebuilt = String::from("|");
            for c in 0..ncol {
                let v = cells.get(c).map(|s| s.trim().to_string()).unwrap_or_default();
                let w = widths[c];
                let pad = w.saturating_sub(v.chars().count());
                rebuilt.push_str(&format!(" {}{} |", v, " ".repeat(pad)));
            }
            if rebuilt != l {
                let msg = "Table columns should be aligned".to_string();
                let s = doc.start(*line);
                let e = s + doc.line(*line).len();
                out.push(
                    Issue::new("MD060", line + 1, 1, msg)
                        .with_fix(Fix::new(s, e, &rebuilt)),
                );
            }
            let _ = li;
        }
    }
    out
}
