use crate::config::Config;
use crate::doc::Doc;
use crate::lint::Ctx;
use crate::rules::{Fix, Issue};

pub struct Fence {
    pub open_line: usize,
    pub close_line: usize,
    pub fence_char: u8,
    pub len: usize,
    pub lang: String,
    pub indent: usize,
}

pub fn fenced_blocks(doc: &Doc) -> Vec<Fence> {
    let skip = doc.non_text_lines();
    let mut out = Vec::new();
    let n = doc.nlines();
    let mut i = 0usize;
    while i < n {
        if skip[i] {
            i += 1;
            continue;
        }
        let l = doc.line_trimmed(i);
        let ind = l.len() - l.trim_start().len();
        let t = &l[ind..];
        if let Some((ch, len)) = crate::doc::fence_open(t) {
            let lang = t[len..].trim().to_string();
            // find close
            let mut j = i + 1;
            let mut close = None;
            while j < n {
                let l2 = doc.line_trimmed(j);
                let ind2 = l2.len() - l2.trim_start().len();
                let t2 = &l2[ind2..];
                if crate::doc::is_fence_close(t2, ch, len) {
                    close = Some(j);
                    break;
                }
                j += 1;
            }
            match close {
                Some(cl) => {
                    out.push(Fence {
                        open_line: i,
                        close_line: cl,
                        fence_char: ch,
                        len,
                        lang,
                        indent: ind,
                    });
                    i = cl + 1;
                }
                None => {
                    out.push(Fence {
                        open_line: i,
                        close_line: usize::MAX,
                        fence_char: ch,
                        len,
                        lang,
                        indent: ind,
                    });
                    i = n;
                }
            }
        } else {
            i += 1;
        }
    }
    out
}

pub fn md031(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let list_items = cfg.boolean("MD031", "list-items", true);
    for f in fenced_blocks(doc) {
        if f.open_line == usize::MAX {
            continue;
        }
        // before
        if f.open_line > 0 && !doc.is_blank(f.open_line - 1) {
            let prev = doc.line_trimmed(f.open_line - 1);
            let in_list = crate::rules::list::parse_marker(prev).is_some();
            let is_cont = {
                let ind = prev.len() - prev.trim_start().len();
                ind > 0 && crate::rules::list::parse_marker(prev).is_none()
            };
            if !(in_list && list_items) && !is_cont {
                out.push(
                    Issue::new(
                        "MD031",
                        f.open_line + 1,
                        1,
                        "No blank line before fenced code block".to_string(),
                    )
                    .with_fix(Fix::new(doc.start(f.open_line), doc.start(f.open_line), "\n")),
                );
            }
        }
        if f.close_line != usize::MAX {
            let n = doc.nlines();
            if f.close_line + 1 < n && !doc.is_blank(f.close_line + 1) {
                let next = doc.line_trimmed(f.close_line + 1);
                let ind = next.len() - next.trim_start().len();
                if !(ind > 0 && list_items) {
                    let at = doc.start(f.close_line) + doc.line(f.close_line).len();
                    out.push(
                        Issue::new(
                            "MD031",
                            f.close_line + 1,
                            1,
                            "No blank line after fenced code block".to_string(),
                        )
                        .with_fix(Fix::new(at, at, "\n")),
                    );
                }
            }
        }
    }
    out
}

pub fn md033(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let allowed = cfg.strings("MD033", "allowed-elements", &[]);
    let disallowed = cfg.strings("MD033", "disallowed-elements", &[]);
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for (s, e, tag, name, closing) in crate::rules::inline::html_tags(l) {
            let _ = (s, e);
            if tag.contains("<!--") {
                continue;
            }
            if allowed
                .iter()
                .any(|a| a.eq_ignore_ascii_case(&name))
            {
                continue;
            }
            if !disallowed.is_empty()
                && !disallowed
                    .iter()
                    .any(|a| a.eq_ignore_ascii_case(&name))
            {
                continue;
            }
            let msg = format!("Inline HTML found: <{}{}>", if closing { "/" } else { "" }, name);
            let col = s + 1;
            let fix = if cfg.boolean("MD033", "fix", false) {
                crate::rules::block::md033_fix(l, s, e, &name)
            } else {
                None
            };
            let mut iss = Issue::new("MD033", i + 1, col, msg);
            if let Some((fs, fe, rep)) = fix {
                iss = iss.with_fix(Fix::new(
                    doc.char_to_byte(i, fs),
                    doc.char_to_byte(i, fe),
                    &rep,
                ));
            }
            out.push(iss);
        }
    }
    out
}

fn md033_fix(l: &str, s: usize, e: usize, name: &str) -> Option<(usize, usize, String)> {
    let lower = name.to_lowercase();
    match lower.as_str() {
        "b" | "strong" => {
            let inner = l[e..].to_string();
            let close = format!("</{}>", name);
            if let Some(p) = inner.find(&close) {
                let end = e + p + close.len();
                return Some((s, end, format!("**{}**", inner[..p].trim())));
            }
            None
        }
        "i" | "em" => {
            let inner = l[e..].to_string();
            let close = format!("</{}>", name);
            if let Some(p) = inner.find(&close) {
                let end = e + p + close.len();
                return Some((s, end, format!("*{}*", inner[..p].trim())));
            }
            None
        }
        "br" => Some((s, e, "  ".to_string())),
        _ => None,
    }
}

pub fn md040(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let allowed = cfg.strings("MD040", "allowed-languages", &[]);
    let disallowed = cfg.strings("MD040", "disallowed-languages", &[]);
    let unknown_action = cfg.string("MD040", "unknown-language-action", "ignore");
    let style = cfg.string("MD040", "style", "disabled");
    let _ = style;
    for f in fenced_blocks(doc) {
        let fence_str: String = std::iter::repeat(f.fence_char as char).take(f.len).collect();
        if f.lang.is_empty() {
            let msg = format!("Code block ({}) missing language", fence_str);
            let at = doc.char_to_byte(f.open_line, f.indent + f.len);
            out.push(
                Issue::new("MD040", f.open_line + 1, f.indent + 1, msg)
                    .with_fix(Fix::new(at, at, "text")),
            );
            continue;
        }
        let canon = crate::rules::block::canonical_language(&f.lang);
        if !allowed.is_empty() {
            match canon {
                Some(c) => {
                    if !allowed
                        .iter()
                        .any(|a| a.eq_ignore_ascii_case(&c))
                    {
                        let msg = format!(
                            "Code block language '{}' is not allowed",
                            f.lang
                        );
                        out.push(Issue::new("MD040", f.open_line + 1, f.indent + 1, msg));
                    }
                }
                None => {}
            }
        } else if !disallowed.is_empty() {
            if let Some(c) = canon {
                if disallowed.iter().any(|a| a.eq_ignore_ascii_case(&c)) {
                    let msg = format!(
                        "Code block language '{}' is disallowed",
                        f.lang
                    );
                    out.push(Issue::new("MD040", f.open_line + 1, f.indent + 1, msg));
                }
            }
        }
        if canon.is_none() && unknown_action != "ignore" {
            let msg = format!(
                "Unknown code block language '{}'",
                f.lang
            );
            out.push(Issue::new("MD040", f.open_line + 1, f.indent + 1, msg));
        }
    }
    out
}

pub fn canonical_language(l: &str) -> Option<String> {
    let map: &[(&str, &str)] = &[
        ("py", "Python"),
        ("python", "Python"),
        ("py3", "Python"),
        ("sh", "Shell"),
        ("shell", "Shell"),
        ("bash", "Shell"),
        ("zsh", "Shell"),
        ("console", "Shell"),
        ("js", "JavaScript"),
        ("javascript", "JavaScript"),
        ("node", "JavaScript"),
        ("ts", "TypeScript"),
        ("typescript", "TypeScript"),
        ("json", "JSON"),
        ("yaml", "YAML"),
        ("yml", "YAML"),
        ("toml", "TOML"),
        ("rust", "Rust"),
        ("rs", "Rust"),
        ("go", "Go"),
        ("golang", "Go"),
        ("c", "C"),
        ("cpp", "C++"),
        ("c++", "C++"),
        ("java", "Java"),
        ("ruby", "Ruby"),
        ("rb", "Ruby"),
        ("md", "Markdown"),
        ("markdown", "Markdown"),
        ("html", "HTML"),
        ("css", "CSS"),
        ("sql", "SQL"),
        ("text", "Text"),
        ("txt", "Text"),
        ("diff", "Diff"),
        ("makefile", "Makefile"),
        ("dockerfile", "Dockerfile"),
