        }
        let l = doc.line_trimmed(i);
        let ind = l.len() - l.trim_start().len();
        let t = &l[ind..];
        if let Some((ch, len)) = crate::doc::fence_open(t) {
            let lang = t[len..].trim().to_lowercase();
            if lang.is_empty() || lang == "markdown" || lang == "md" {
                // find inner fence-like lines
                let mut j = i + 1;
                let mut closed = false;
                while j < n {
                    let l2 = doc.line_trimmed(j);
                    let ind2 = l2.len() - l2.trim_start().len();
                    let t2 = &l2[ind2..];
                    if crate::doc::is_fence_close(t2, ch, len) {
                        closed = true;
                        break;
                    }
                    if let Some((ch2, len2)) = crate::doc::fence_open(t2) {
                        if ch2 == ch && len2 >= len {
                            let msg = format!(
                                "Nested {} at line {} closes block prematurely \u{2014} use {} for outer fence",
                                std::iter::repeat(ch as char).take(len2).collect::<String>(),
                                j + 1,
                                std::iter::repeat(ch as char).take(len2 + 1).collect::<String>(),
                            );
                            out.push(Issue::new("MD070", i + 1, ind + 1, msg));
                            break;
                        }
                    }
                    j += 1;
                }
                let _ = closed;
                i = j + 1;
                continue;
            }
        }
        i += 1;
    }
    out
}
