                let t2 = &l2[ind2..];
                if crate::doc::is_fence_close(t2, ch, len) {
                    close = Some(j);
                    break;
                }
                j += 1;
            }
            match close {
                Some(cl) => {
                    out.push(Fence {
                        open_line: i,
                        close_line: cl,
                        fence_char: ch,
                        len,
                        lang,
                        indent: ind,
                    });
                    i = cl + 1;
                }
                None => {
                    out.push(Fence {
                        open_line: i,
                        close_line: usize::MAX,
                        fence_char: ch,
                        len,
                        lang,
                        indent: ind,
                    });
                    i = n;
                }
            }
        } else {
            i += 1;
        }
    }
