        if f.open_line > 0 && !doc.is_blank(f.open_line - 1) {
            let prev = doc.line_trimmed(f.open_line - 1);
            let in_list = crate::rules::list::parse_marker(prev).is_some();
            let is_cont = {
                let ind = prev.len() - prev.trim_start().len();
