pub fn md033(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let allowed = cfg.strings("MD033", "allowed-elements", &[]);
    let disallowed = cfg.strings("MD033", "disallowed-elements", &[]);
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        for (s, e, tag, name, closing) in crate::rules::inline::html_tags(l) {
            let _ = (s, e);
            if tag.contains("<!--") {
                continue;
            }
            if allowed
                .iter()
                .any(|a| a.eq_ignore_ascii_case(&name))
            {
                continue;
            }
            if !disallowed.is_empty()
                && !disallowed
                    .iter()
                    .any(|a| a.eq_ignore_ascii_case(&name))
            {
                continue;
            }
            let msg = format!("Inline HTML found: <{}{}>", if closing { "/" } else { "" }, name);
            let col = s + 1;
            let fix = if cfg.boolean("MD033", "fix", false) {
                crate::rules::block::md033_fix(l, s, e, &name)
            } else {
                None
            };
            let mut iss = Issue::new("MD033", i + 1, col, msg);
            if let Some((fs, fe, rep)) = fix {
                iss = iss.with_fix(Fix::new(
                    doc.char_to_byte(i, fs),
                    doc.char_to_byte(i, fe),
                    &rep,
                ));
            }
            out.push(iss);
        }
    }
    out
}

fn md033_fix(l: &str, s: usize, e: usize, name: &str) -> Option<(usize, usize, String)> {
    let lower = name.to_lowercase();
    match lower.as_str() {
        "b" | "strong" => {
            let inner = l[e..].to_string();
            let close = format!("</{}>", name);
            if let Some(p) = inner.find(&close) {
                let end = e + p + close.len();
                return Some((s, end, format!("**{}**", inner[..p].trim())));
            }
            None
        }
        "i" | "em" => {
            let inner = l[e..].to_string();
            let close = format!("</{}>", name);
            if let Some(p) = inner.find(&close) {
                let end = e + p + close.len();
                return Some((s, end, format!("*{}*", inner[..p].trim())));
            }
            None
        }
        "br" => Some((s, e, "  ".to_string())),
        _ => None,
    }
}

pub fn md040(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let allowed = cfg.strings("MD040", "allowed-languages", &[]);
    let disallowed = cfg.strings("MD040", "disallowed-languages", &[]);
    let unknown_action = cfg.string("MD040", "unknown-language-action", "ignore");
    let style = cfg.string("MD040", "style", "disabled");
    let _ = style;
    for f in fenced_blocks(doc) {
        let fence_str: String = std::iter::repeat(f.fence_char as char).take(f.len).collect();
        if f.lang.is_empty() {
            let msg = format!("Code block ({}) missing language", fence_str);
            let at = doc.char_to_byte(f.open_line, f.indent + f.len);
            out.push(
                Issue::new("MD040", f.open_line + 1, f.indent + 1, msg)
                    .with_fix(Fix::new(at, at, "text")),
            );
            continue;
        }
        let canon = crate::rules::block::canonical_language(&f.lang);
        if !allowed.is_empty() {
            match canon {
                Some(c) => {
                    if !allowed
                        .iter()
                        .any(|a| a.eq_ignore_ascii_case(&c))
                    {
                        let msg = format!(
                            "Code block language '{}' is not allowed",
                            f.lang
                        );
                        out.push(Issue::new("MD040", f.open_line + 1, f.indent + 1, msg));
                    }
                }
                None => {}
            }
        } else if !disallowed.is_empty() {
            if let Some(c) = canon {
                if disallowed.iter().any(|a| a.eq_ignore_ascii_case(&c)) {
                    let msg = format!(
                        "Code block language '{}' is disallowed",
                        f.lang
                    );
                    out.push(Issue::new("MD040", f.open_line + 1, f.indent + 1, msg));
                }
            }
        }
        if canon.is_none() && unknown_action != "ignore" {
            let msg = format!(
                "Unknown code block language '{}'",
                f.lang
            );
            out.push(Issue::new("MD040", f.open_line + 1, f.indent + 1, msg));
        }
    }
    out
}

pub fn canonical_language(l: &str) -> Option<String> {
    let map: &[(&str, &str)] = &[
        ("py", "Python"),
        ("python", "Python"),
        ("py3", "Python"),
        ("sh", "Shell"),
        ("shell", "Shell"),
        ("bash", "Shell"),
        ("zsh", "Shell"),
        ("console", "Shell"),
        ("js", "JavaScript"),
        ("javascript", "JavaScript"),
        ("node", "JavaScript"),
        ("ts", "TypeScript"),
        ("typescript", "TypeScript"),
        ("json", "JSON"),
        ("yaml", "YAML"),
        ("yml", "YAML"),
        ("toml", "TOML"),
        ("rust", "Rust"),
        ("rs", "Rust"),
        ("go", "Go"),
        ("golang", "Go"),
        ("c", "C"),
        ("cpp", "C++"),
        ("c++", "C++"),
        ("java", "Java"),
        ("ruby", "Ruby"),
        ("rb", "Ruby"),
        ("md", "Markdown"),
        ("markdown", "Markdown"),
        ("html", "HTML"),
        ("css", "CSS"),
        ("sql", "SQL"),
        ("text", "Text"),
        ("txt", "Text"),
        ("diff", "Diff"),
        ("makefile", "Makefile"),
        ("dockerfile", "Dockerfile"),
        ("xml", "XML"),
    ];
    let lower = l.to_lowercase();
    for (k, v) in map {
        if *k == lower {
            return Some(v.to_string());
        }
    }
    None
}

pub fn md046(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let style = cfg.string("MD046", "style", "consistent");
    let skip = doc.non_text_lines();
    let indented = doc.indented_code_lines();
    let mut has_indented = false;
    let mut has_fenced = false;
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        if crate::doc::fence_open(doc.line_trimmed(i)).is_some() {
            has_fenced = true;
        } else if indented[i] {
            has_indented = true;
        }
    }
    let target = if style == "consistent" {
        if has_fenced {
            "fenced"
        } else if has_indented {
            "indented"
        } else {
            "fenced"
        }
    } else {
        style.as_str()
    };
    if target == "indented" {
        for f in fenced_blocks(doc) {
            let msg = format!("Use indented code blocks");
            let l = doc.line_trimmed(f.open_line);
            out.push(
                Issue::new("MD046", f.open_line + 1, f.indent + 1, msg).with_fix(Fix::new(
                    doc.start(f.open_line),
                    doc.start(f.open_line) + l.len(),
                    &format!("    {}", &l[f.indent..]),
                )),
            );
            if f.close_line != usize::MAX {
                let l2 = doc.line_trimmed(f.close_line);
                out.push(
                    Issue::new("MD046", f.close_line + 1, f.indent + 1, msg).with_fix(
                        Fix::new(
                            doc.start(f.close_line),
                            doc.start(f.close_line) + l2.len(),
                            &format!("    {}", &l2[f.indent..]),
                        ),
                    ),
                );
            }
        }
        // unmatched fence
        for f in fenced_blocks(doc) {
            if f.close_line == usize::MAX {
                let msg = format!(
                    "Code block '{}' should be closed before starting new one at line {}",
                    std::iter::repeat(f.fence_char as char).take(f.len).collect::<String>(),
                    doc.nlines() + 1
                );
                out.push(Issue::new("MD046", f.open_line + 1, 1, msg));
            }
        }
        return out;
    }
    // target fenced
    let indented = doc.indented_code_lines();
    let mut i = 0usize;
    let n = doc.nlines();
    while i < n {
        if skip[i] || !indented[i] {
            i += 1;
            continue;
        }
        let mut j = i;
        while j < n && indented[j] {
            j += 1;
        }
        let msg = "Use fenced code blocks".to_string();
        out.push(
            Issue::new("MD046", i + 1, 1, msg).with_fix(Fix::new(
                doc.start(i),
                doc.start(i),
                "```\n",
            )),
        );
        let end_at = doc.start(j - 1) + doc.line(j - 1).len();
        out.push(
            Issue::new("MD046", j, 1, msg).with_fix(Fix::new(end_at, end_at, "\n```")),
        );
        i = j;
    }
    // unclosed fence
    for f in fenced_blocks(doc) {
        if f.close_line == usize::MAX {
            let msg = format!(
                "Code block opened with '{}' but never closed",
                std::iter::repeat(f.fence_char as char).take(f.len).collect::<String>()
            );
            out.push(Issue::new("MD046", f.open_line + 1, 1, msg));
        }
    }
    // fence opened then another fence before closing
    let fences = fenced_blocks(doc);
    for k in 1..fences.len() {
        let prev = &fences[k - 1];
        let cur = &fences[k];
        if prev.close_line != usize::MAX && cur.open_line <= prev.close_line {
            // nested/overlapping
        }
    }
    let _ = &fences;
    out
}

pub fn md048(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let style = cfg.string("MD048", "style", "consistent");
    let fences = fenced_blocks(doc);
    if fences.is_empty() {
        return out;
    }
    let expected = if style == "consistent" {
        let mut back = 0usize;
        let mut tilde = 0usize;
        for f in &fences {
            if f.fence_char == b'`' {
                back += 1;
            } else {
                tilde += 1;
            }
        }
        if tilde > back {
            b'~'
        } else {
            b'`'
        }
    } else if style == "tilde" {
        b'~'
    } else {
        b'`'
    };
    let exp_str: String = std::iter::repeat(expected as char).take(3).collect();
    for f in &fences {
        if f.fence_char != expected {
            let msg = format!("Code fence style: use {} instead of {}", exp_str,
                std::iter::repeat(f.fence_char as char).take(3).collect::<String>());
            // fix open fence
            let l = doc.line_trimmed(f.open_line);
            let rest = &l[f.indent + f.len..];
            let newl = format!("{}{}{}", exp_str, rest, "");
            out.push(
                Issue::new("MD048", f.open_line + 1, f.indent + 1, msg.clone()).with_fix(
                    Fix::new(
                        doc.start(f.open_line) + f.indent,
                        doc.start(f.open_line) + f.indent + f.len,
                        &exp_str,
                    ),
                ),
            );
            if f.close_line != usize::MAX {
                out.push(
                    Issue::new("MD048", f.close_line + 1, f.indent + 1, msg).with_fix(
                        Fix::new(
                            doc.start(f.close_line) + f.indent,
                            doc.start(f.close_line) + f.indent + f.len,
                            &exp_str,
                        ),
                    ),
                );
            }
            let _ = newl;
        }
    }
    out
}

