#[derive(Clone, Copy, Debug)]
pub struct EmphSeg {
    pub start_char: usize,
    pub end_char: usize,
    pub ch: char,
    pub len: usize,
    pub text: String,
}

/// All emphasis segments (strong and normal) on a line.
pub fn emphasis_all(l: &str) -> Vec<EmphSeg> {
    let b: Vec<char> = l.chars().collect();
    let spans = code_spans(l);
    let in_code = |i: usize| spans.iter().any(|c| i >= c.start_char && i < c.end_char);
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < b.len() {
        if in_code(i) {
            i += 1;
            continue;
        }
        let c = b[i];
        if c == '\\' {
            i += 2;
            continue;
        }
        if c != '*' && c != '_' {
            i += 1;
            continue;
        }
        let mut n = 0;
        while i + n < b.len() && b[i + n] == c {
            n += 1;
        }
        if n > 3 {
            i += n;
            continue;
        }
        let ticks = if n == 3 { 1 } else { n };
        let mut j = i + n;
        let mut close = None;
        while j < b.len() {
            if in_code(j) {
                j += 1;
                continue;
            }
            if b[j] == '\\' {
                j += 2;
                continue;
            }
            if b[j] == c {
                let mut m = 0;
                while j + m < b.len() && b[j + m] == c {
                    m += 1;
                }
                if m >= ticks {
                    close = Some(j);
                    break;
                }
                j += m;
                continue;
            }
            j += 1;
        }
        if let Some(j) = close {
            let e = j + ticks;
            out.push(EmphSeg {
                start_char: i,
                end_char: e,
                ch: c,
                len: ticks,
                text: b[i..e].iter().collect(),
            });
            i = e;
        } else {
            i += n.max(1);
        }
    }
    out
}
