pub type HtmlTag = (usize, usize, String, String, bool);

pub fn html_tags(l: &str) -> Vec<HtmlTag> {
    let chars: Vec<char> = l.chars().collect();
    let spans = code_spans(l);
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < chars.len() {
        if spans.iter().any(|c| c.start_char == i) {
            i = spans.iter().find(|c| c.start_char == i).unwrap().end_char;
            continue;
        }
        if chars[i] == '<' {
            if chars
                .iter()
                .skip(i)
                .take(4)
                .collect::<String>()
                == "<!--"
            {
                if let Some(e) = (i + 4..chars.len()).find(|&j| {
                    chars.iter().skip(j).take(3).collect::<String>() == "-->"
                }) {
                    out.push((i, e + 3, "<!-- -->".to_string(), "!--".to_string(), false));
                    i = e + 3;
                    continue;
                }
                out.push((i, chars.len(), "<!--".to_string(), "!--".to_string(), false));
                break;
            }
            if let Some(e) = (i + 1..chars.len()).find(|&j| chars[j] == '>') {
                let inner: String = chars[i + 1..e].iter().collect();
                if is_html_tag(&inner) {
                    let (closing, name) = if let Some(rest) = inner.strip_prefix('/') {
                        (true, rest.to_string())
                    } else {
                        (false, inner.clone())
                    };
                    let name = name
                        .split(|c: char| c.is_whitespace())
                        .next()
                        .unwrap_or("")
                        .to_string();
                    out.push((i, e + 1, format!("<{}>", inner), name, closing));
                    i = e + 1;
                    continue;
                }
            }
        }
        i += 1;
    }
    out
}
