use crate::config::Config;
use crate::doc::Doc;
use crate::lint::Ctx;
use crate::rules::Issue;

#[derive(Clone, Debug)]
pub struct FootRef {
    pub line: usize,
    pub name: String,
    pub is_def: bool,
    pub col: usize,
    pub start_char: usize,
    pub content: String,
}

pub fn footnotes(doc: &Doc) -> Vec<FootRef> {
    let skip = doc.non_text_lines();
    let mut out = Vec::new();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        // definition at start of line
        if let Some(rest) = l.strip_prefix("[^") {
            if let Some(p) = rest.find("]:") {
                let name = &rest[..p];
                if !name.is_empty() {
                    out.push(FootRef {
                        line: i,
                        name: name.to_string(),
                        is_def: true,
                        col: 1,
                        start_char: 0,
                        content: rest[p + 2..].trim().to_string(),
                    });
                    continue;
                }
            }
        }
        // references
        let chars: Vec<char> = l.chars().collect();
        let mut j = 0usize;
        while j + 2 < chars.len() {
            if chars[j] == '[' && chars[j + 1] == '^' {
                if let Some(e) = (j + 2..chars.len()).find(|&k| chars[k] == ']') {
                    let name: String = chars[j + 2..e].iter().collect();
                    // is it a definition?
                    if e + 1 < chars.len() && chars[e + 1] == ':' {
                        j = e + 1;
                        continue;
                    }
                    if !name.is_empty() {
                        out.push(FootRef {
                            line: i,
                            name,
                            is_def: false,
                            col: j + 1,
                            start_char: j,
                            content: String::new(),
                        });
                    }
                    j = e + 1;
                    continue;
                }
            }
            j += 1;
        }
    }
    out
}

