pub fn md067(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let fns = footnotes(doc);
    let defs: Vec<&FootRef> = fns.iter().filter(|f| f.is_def).collect();
    let uses: Vec<&FootRef> = fns.iter().filter(|f| !f.is_def).collect();
    // order of definitions must follow order of first reference
    let mut order: Vec<String> = Vec::new();
    for u in &uses {
        if !order.contains(&u.name) {
            order.push(u.name.clone());
        }
    }
    let mut seen: Vec<String> = Vec::new();
    for d in &defs {
        let expected = order.get(seen.len()).cloned();
        match expected {
            Some(e) => {
                if d.name != e {
                    out.push(Issue::new(
                        "MD067",
                        d.line + 1,
                        d.col,
                        format!(
                            "Footnote definition '[^{}]' is out of order; expected '[^{}]' next (based on reference order)",
                            d.name,
                            e
                        ),
                    ));
                }
                seen.push(d.name.clone());
            }
            None => {}
        }
    }
    out
}

