use crate::config::Config;
use crate::doc::Doc;
use crate::lint::Ctx;
use crate::rules::{Fix, Issue};

pub fn frontmatter(doc: &Doc) -> Option<(usize, usize)> {
    let n = doc.nlines();
    if n == 0 || doc.line_trimmed(0) != "---" {
        return None;
    }
    let mut j = 1;
    while j < n {
        let l = doc.line_trimmed(j);
        if l == "---" || l == "..." {
            return Some((0, j));
        }
        j += 1;
    }
    None
}

pub fn md071(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    if let Some((_, end)) = frontmatter(doc) {
        if end + 1 < doc.nlines() && !doc.is_blank(end + 1) {
            out.push(
                Issue::new(
                    "MD071",
                    end + 1,
                    1,
                    "Missing blank line after frontmatter".to_string(),
                )
                .with_fix(Fix::new(doc.start(end + 1), doc.start(end + 1), "\n")),
            );
        }
    }
    out
}

pub fn md072(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    if !cfg.boolean("MD072", "enabled", false) {
        return out;
    }
    let fm = match frontmatter(doc) {
        Some(f) => f,
        None => return out,
    };
    let custom = cfg.strings("MD072", "key-order", &[]);
    let mut keys: Vec<(String, usize)> = Vec::new();
    for i in fm.0 + 1..fm.1 {
        let l = doc.line_trimmed(i);
        if let Some((k, _)) = l.split_once(':') {
            keys.push((k.trim().to_string(), i));
        }
    }
    if keys.len() < 2 {
        return out;
    }
    let rank = |k: &str| -> usize {
        match custom.iter().position(|x| x == k) {
            Some(p) => p,
            None => custom.len() + 1000,
        }
    };
    let mut sorted = keys.clone();
    sorted.sort_by(|a, b| {
        let ra = rank(&a.0);
        let rb = rank(&b.0);
        if ra != rb {
            ra.cmp(&rb)
        } else {
            a.0.to_lowercase().cmp(&b.0.to_lowercase())
        }
    });
    for i in 0..keys.len() {
        if keys[i].0 != sorted[i].0 {
            let msg = format!(
                "YAML frontmatter keys are not sorted alphabetically: '{}' should come before '{}'",
                sorted[i].0,
                keys[i].0
            );
            out.push(Issue::new("MD072", keys[i].1 + 1, 1, msg));
            break;
        }
    }
    out
}

pub fn md073(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    if !cfg.boolean("MD073", "enabled", false) {
        return out;
    }
    let min_l = cfg.i64("MD073", "min-level", 2) as usize;
    let max_l = cfg.i64("MD073", "max-level", 4) as usize;
    let enforce = cfg.boolean("MD073", "enforce-order", true);
    let indent = cfg.i64("MD073", "indent", cfg.i64("MD007", "indent", 2)) as usize;
