use crate::config::Config;
use crate::doc::Doc;
use crate::lint::Ctx;
use crate::rules::{Fix, Issue};

pub fn frontmatter(doc: &Doc) -> Option<(usize, usize)> {
    let n = doc.nlines();
    if n == 0 || doc.line_trimmed(0) != "---" {
        return None;
    }
    let mut j = 1;
    while j < n {
        let l = doc.line_trimmed(j);
        if l == "---" || l == "..." {
            return Some((0, j));
        }
        j += 1;
    }
    None
}

pub fn md071(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    if let Some((_, end)) = frontmatter(doc) {
        if end + 1 < doc.nlines() && !doc.is_blank(end + 1) {
            out.push(
                Issue::new(
                    "MD071",
                    end + 1,
                    1,
                    "Missing blank line after frontmatter".to_string(),
                )
                .with_fix(Fix::new(doc.start(end + 1), doc.start(end + 1), "\n")),
            );
        }
    }
    out
}

pub fn md072(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    if !cfg.boolean("MD072", "enabled", false) {
        return out;
    }
    let fm = match frontmatter(doc) {
        Some(f) => f,
        None => return out,
    };
    let custom = cfg.strings("MD072", "key-order", &[]);
    let mut keys: Vec<(String, usize)> = Vec::new();
    for i in fm.0 + 1..fm.1 {
        let l = doc.line_trimmed(i);
        if let Some((k, _)) = l.split_once(':') {
            keys.push((k.trim().to_string(), i));
        }
    }
    if keys.len() < 2 {
        return out;
    }
    let rank = |k: &str| -> usize {
        match custom.iter().position(|x| x == k) {
            Some(p) => p,
            None => custom.len() + 1000,
        }
    };
    let mut sorted = keys.clone();
    sorted.sort_by(|a, b| {
        let ra = rank(&a.0);
        let rb = rank(&b.0);
        if ra != rb {
            ra.cmp(&rb)
        } else {
            a.0.to_lowercase().cmp(&b.0.to_lowercase())
        }
    });
    for i in 0..keys.len() {
        if keys[i].0 != sorted[i].0 {
            let msg = format!(
                "YAML frontmatter keys are not sorted alphabetically: '{}' should come before '{}'",
                sorted[i].0,
                keys[i].0
            );
            out.push(Issue::new("MD072", keys[i].1 + 1, 1, msg));
            break;
        }
    }
    out
}

pub fn md073(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    if !cfg.boolean("MD073", "enabled", false) {
        return out;
    }
    let min_l = cfg.i64("MD073", "min-level", 2) as usize;
    let max_l = cfg.i64("MD073", "max-level", 4) as usize;
    let enforce = cfg.boolean("MD073", "enforce-order", true);
    let indent = cfg.i64("MD073", "indent", cfg.i64("MD007", "indent", 2)) as usize;
    let _ = enforce;
    // find TOC region
    let n = doc.nlines();
    let mut toc: Option<(usize, usize, bool)> = None; // (start, end, marker_based)
    for i in 0..n {
        let l = doc.line_trimmed(i);
        let t = l.trim();
        if t.to_lowercase().contains("<!--") && t.to_lowercase().contains("toc") {
            // marker start
            let mut j = i + 1;
            let mut end = None;
            while j < n {
                let l2 = doc.line_trimmed(j);
                let t2 = l2.trim().to_lowercase();
                if t2.contains("<!--") && (t2.contains("tocstop") || t2.contains("/toc")) {
                    end = Some(j);
                    break;
                }
                j += 1;
            }
            if let Some(e) = end {
                toc = Some((i, e, true));
            }
            break;
        }
        if let Some(h) = doc.parse_heading(i) {
            let t = h.text.to_lowercase();
            if t == "table of contents" || t == "contents" || t == "toc" {
                let mut j = i + 1;
                let mut end = j;
                while j < n {
                    if doc.parse_heading(j).is_some() {
                        break;
                    }
                    end = j;
                    j += 1;
                }
                toc = Some((i, end, false));
                break;
            }
        }
    }
    let (ts, te, marker) = match toc {
        Some(t) => t,
        None => return out,
    };
    // headings after the TOC
    let hs: Vec<&crate::doc::Heading> = doc
        .headings()
        .iter()
        .filter(|h| h.line > te && h.level >= min_l && h.level <= max_l)
        .collect();
    // TOC entries
    let mut entries: Vec<(usize, String)> = Vec::new();
    for i in ts + 1..te {
        let l = doc.line_trimmed(i);
        if l.trim().is_empty() {
            continue;
        }
        for m in crate::rules::inline::links_all(l) {
            if m.url.starts_with('#') {
                entries.push((i, m.text.clone()));
            }
        }
    }
    let expected: Vec<String> = hs.iter().map(|h| h.text.clone()).collect();
    // missing
    for (k, h) in hs.iter().enumerate() {
        if !entries.iter().any(|(_, t)| *t == h.text) {
            let indent = " ".repeat((h.level - min_l) * indent);
            let msg = format!(
                "Missing TOC entry for heading '{}' (expected: '{}')",
                h.text,
                format!("{}- [{}](#{})", indent, h.text, crate::rules::link::slug(&h.text, "github"))
            );
            out.push(Issue::new("MD073", te + 1, 1, msg));
            let _ = k;
        }
    }
    // stale
    for (li, t) in &entries {
        if !expected.iter().any(|x| x == t) {
            let msg = format!("TOC entry '{}' does not match any heading", t);
            out.push(Issue::new("MD073", li + 1, 1, msg));
        }
    }
    // mismatched text but matching anchor
    for (li, t) in &entries {
        if expected.iter().any(|x| crate::rules::link::slug(x, "github") == crate::rules::link::slug(t, "github")) && !expected.iter().any(|x| x == t) {
            let msg = format!(
                "TOC entry text '{}' does not match heading '{}'",
                t,
                expected
                    .iter()
                    .find(|x| crate::rules::link::slug(x, "github") == crate::rules::link::slug(t, "github"))
                    .unwrap()
            );
            out.push(Issue::new("MD073", li + 1, 1, msg));
        }
    }
    let _ = marker;
    out
}
