{"command": "cd /workspace && cat > src/lint.rs <<'RSEOF'
use std::path::{Path, PathBuf};

pub struct Ctx {
    pub file: PathBuf,
    pub rel_path: String,
}

impl Ctx {
    pub fn new(file: PathBuf, rel_path: String) -> Ctx {
        Ctx { file, rel_path }
    }
}

pub const EXTENSIONS: &[&str] = &[
    "md", "markdown", "mdx", "mkd", "mkdn", "mdown", "mdwn", "qmd", "rmd",
];

pub fn is_markdown(p: &Path) -> bool {
    match p.extension().and_then(|e| e.to_str()) {
        Some(e) => EXTENSIONS.contains(&e.to_lowercase().as_str()),
        None => false,
    }
}

/// Collect files to lint.
pub fn collect_files(
    paths: &[String],
    excludes: &[crate::utils::Glob],
    includes: &[crate::utils::Glob],
    respect_gitignore: bool,
    force_exclude: bool,
) -> Result<Vec<PathBuf>, String> {
    let mut out: Vec<PathBuf> = Vec::new();
    let mut explicit: Vec<PathBuf> = Vec::new();
    for p in paths {
        let pb = PathBuf::from(p);
        if p == "-" {
            continue;
        }
        if pb.is_dir() {
            walk(&pb, excludes, includes, respect_gitignore, &mut out)?;
        } else if pb.is_file() {
            if !is_markdown(&pb) {
                continue;
            }
            if !force_exclude {
                explicit.push(pb);
            } else {
                let s = pb.to_string_lossy().replace('\\', "/");
                if excludes.iter().any(|g| g.matches(&s)) {
                    continue;
                }
                if !includes.is_empty() && !includes.iter().any(|g| g.matches(&s)) {
                    continue;
                }
                explicit.push(pb);
            }
        } else {
            return Err(format!("File not found: {}", p));
        }
    }
    let mut all: Vec<PathBuf> = Vec::new();
    all.extend(explicit);
    all.extend(out);
    // canonicalise + dedupe
