use crate::rules::{Issue, R};

pub struct FileResult {
    pub path: String,
    pub issues: Vec<Issue>,
    pub fixed: usize,
}

pub fn summary_lines(
    results: &[FileResult],
    total_files: usize,
    elapsed_ms: usize,
    fix_mode: bool,
    colored: bool,
) -> Vec<String> {
    let total_issues: usize = results.iter().map(|r| r.issues.len()).sum();
    let files_with = results.iter().filter(|r| !r.issues.is_empty()).count();
    let mut out = Vec::new();
    if total_issues == 0 {
        let plural = if total_files == 1 { "file" } else { "files" };
        out.push(format!(
            "Success: No issues found in {} {}",
            total_files, plural
        ));
    } else if fix_mode {
        let fixed: usize = results.iter().map(|r| r.fixed).sum();
        let plural = if fixed == 1 { "issue" } else { "issues" };
        let fp = if files_with == 1 { "file" } else { "files" };
        out.push(format!(
            "Fixed: Fixed {}/{} {} in {} {}",
            fixed,
            total_issues,
            plural,
            files_with,
            fp
        ));
    } else {
        let plural = if total_issues == 1 { "issue" } else { "issues" };
        let fp = if files_with == 1 { "file" } else { "files" };
        out.push(format!(
            "Issues: Found {} {} in {}/{} {}",
            total_issues,
            plural,
            files_with,
            total_files,
            fp
        ));
