use crate::rules::Fix;

/// Apply non-overlapping fixes, processing from the highest offset first.
/// Returns the new text and the number of applied fixes.
pub fn apply(text: &str, fixes: &[Fix]) -> (String, usize) {
    let mut sorted: Vec<&Fix> = fixes.iter().collect();
    sorted.sort_by_key(|f| std::cmp::Reverse((f.start, f.end)));
    let bytes = text.as_bytes();
    let mut applied: Vec<(usize, usize)> = Vec::new();
    let mut out: Vec<(usize, usize, &str)> = Vec::new();
    for f in sorted {
        if f.start > bytes.len() || f.end > bytes.len() || f.start > f.end {
            continue;
        }
        // check text stability: the replaced region must not have been touched
        if applied.iter().any(|(a, b)| f.start < *b && f.end > *a) {
            continue;
        }
        applied.push((f.start, f.end));
        out.push((f.start, f.end, &f.replacement));
    }
    let mut result = text.to_string();
    for (s, e, rep) in out {
        result.replace_range(s..e, rep);
    }
    (result, applied.len())
}
