pub fn summary_lines(
    results: &[FileResult],
    total_files: usize,
    elapsed_ms: usize,
    fix_mode: bool,
    colored: bool,
) -> Vec<String> {
    let total_issues: usize = results.iter().map(|r| r.issues.len()).sum();
    let files_with = results.iter().filter(|r| !r.issues.is_empty()).count();
    let mut out = Vec::new();
    if total_issues == 0 {
        let plural = if total_files == 1 { "file" } else { "files" };
        out.push(format!(
            "Success: No issues found in {} {}",
            total_files, plural
        ));
    } else if fix_mode {
        let fixed: usize = results.iter().map(|r| r.fixed).sum();
        let plural = if fixed == 1 { "issue" } else { "issues" };
        let fp = if files_with == 1 { "file" } else { "files" };
        out.push(format!(
            "Fixed: Fixed {}/{} {} in {} {}",
            fixed,
            total_issues,
            plural,
            files_with,
            fp
        ));
    } else {
        let plural = if total_issues == 1 { "issue" } else { "issues" };
        let fp = if files_with == 1 { "file" } else { "files" };
        out.push(format!(
            "Issues: Found {} {} in {}/{} {}",
            total_issues,
            plural,
            files_with,
            total_files,
            fp
        ));
    }
    if !out.is_empty() {
        out[0] = format!("{}({}ms)", out[0], elapsed_ms);
        if colored {
            // timings are dimmed
        }
    }
    if total_issues > 0 && !fix_mode {
        let fixable: usize = results
            .iter()
            .flat_map(|r| r.issues.iter())
            .filter(|i| i.fix.is_some())
            .count();
        let plural = if total_issues == 1 { "issue" } else { "issues" };
        out.push(format!(
            "Run `rumdl fmt` to automatically fix {} of the {} {}",
            fixable,
            total_issues,
            plural
        ));
    }
    out
}

pub fn text_lines(results: &[FileResult], colors: bool, show_fix: bool) -> Vec<String> {
    let mut out = Vec::new();
    for r in results {
        for i in &r.issues {
            let marker = if show_fix {
                if i.fix.is_some() {
                    " [fixed]"
                } else {
                    ""
                }
            } else if i.fix.is_some() {
                " [*]"
            } else {
                ""
            };
            let line = format!(
                "{}:{}:{}: [{}] {}{}",
                r.path, i.line, i.column, i.code, i.message, marker
            );
            if colors {
                let sev = crate::output::color_for(&line);
                out.push(sev);
            } else {
                out.push(line);
            }
        }
    }
    out
}

fn color_for(line: &str) -> String {
    // error-severity rules are red, warnings yellow, info blue
    let code = crate::output::code_of(line);
    let sev = crate::rules::severity_of(code);
    match sev {
        "error" => format!("\x1b[31m{}\x1b[0m", line),
        "info" => format!("\x1b[34m{}\x1b[0m", line),
        _ => format!("\x1b[33m{}\x1b[0m", line),
    }
}

fn code_of(line: &str) -> &str {
    if let Some(p) = line.find("[MD") {
        let rest = &line[p + 1..];
        match rest.find(']') {
            Some(e) => &rest[..e],
            None => "",
        }
    } else {
        ""
    }
}

pub fn statistics(results: &[FileResult], rules: &[&R]) -> Vec<String> {
    let mut counts: Vec<(&str, usize, usize)> = Vec::new();
    for r in results {
        for i in &r.issues {
            let fixable = if i.fix.is_some() { 1 } else { 0 };
            match counts.iter_mut().find(|(c, _, _)| *c == i.code) {
                Some((_, n, f)) => {
                    *n += 1;
                    *f += fixable;
                }
                None => counts.push((i.code, 1, fixable)),
            }
        }
    }
    let total: usize = counts.iter().map(|(_, n, _)| n).sum();
    let total_fix: usize = counts.iter().map(|(_, _, f)| f).sum();
    let mut out = Vec::new();
    if total == 0 {
        return out;
    }
    counts.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    out.push(String::new());
    out.push("Rule Violation Statistics:".to_string());
    out.push(format!("{:<9}{:<13}{:<9}{}", "Rule", "Violations", "Fixable", "Percentage"));
    out.push("-".repeat(50));
    for (code, n, f) in &counts {
        let pct = (*n as f64 / total as f64) * 100.0;
        let fixable_str = if *f == 0 { "-".to_string() } else { f.to_string() };
        out.push(format!(
            "{:<9}{:<13}{:<9}{:.1}%",
            code,
            n.to_string(),
            fixable_str,
            pct
        ));
    }
    out.push("-".repeat(50));
    let fpct = if total_fix == 0 {
        "-".to_string()
    } else {
        format!("{:.1}%", 100.0)
    };
    let _ = rules;
    out.push(format!(
        "{:<9}{:<13}{:<9}{}",
        "Total",
        total.to_string(),
        if total_fix == 0 { "-".to_string() } else { total_fix.to_string() },
        fpct
    ));
    out
}

// ---------- JSON formats ----------

pub fn to_json(results: &[FileResult]) -> String {
    let mut v = serde_json::Map::new();
    let mut files = Vec::new();
    for r in results {
        for i in &r.issues {
            let mut o = serde_json::Map::new();
            o.insert("file".into(), serde_json!(r.path));
            o.insert("line".into(), serde_json!(i.line as u64));
            o.insert("column".into(), serde_json!(i.column as u64));
            o.insert("rule".into(), serde_json!(i.code));
            o.insert("message".into(), serde_json!(i.message));
            o.insert("severity".into(), serde_json!(crate::rules::severity_of(i.code)));
            o.insert("fixable".into(), serde_json!(i.fix.is_some()));
            if let Some(f) = &i.fix {
                let mut range = serde_json::Map::new();
                range.insert("start".into(), serde_json!(f.start as u64));
                range.insert("end".into(), serde_json!(f.end as u64));
                let mut fx = serde_json::Map::new();
                fx.insert("range".into(), serde_json::Value::Object(range));
                fx.insert("replacement".into(), serde_json!(f.replacement));
                o.insert("fix".into(), serde_json::Value::Object(fx));
            }
            files.push(serde_json::Value::Object(o));
        }
    }
    v.insert("files".into(), serde_json!(files));
    let mut sum = serde_json::Map::new();
    sum.insert("files_checked".into(), serde_json!(results.len() as u64));
    let total: usize = results.iter().map(|r| r.issues.len()).sum();
    sum.insert("issues_found".into(), serde_json!(total as u64));
    v.insert("summary".into(), serde_json::Value::Object(sum));
    serde_json::to_string_pretty(&serde_json::Value::Object(v)).unwrap_or_default()
}

// ---------- config display ----------

pub fn config_text(cfg: &Config, only_defaults: bool, no_defaults: bool, colors: bool) -> String {
    let mut entries: Vec<(String, String, String)> = Vec::new();
    // global
    let g = &cfg.global;
    let mut gvals: Vec<(String, String, bool)> = vec![
        ("enable".into(), crate::utils::fmt_str_list(&g.enable), true),
        ("disable".into(), crate::utils::fmt_str_list(&g.disable), true),
        ("exclude".into(), crate::utils::fmt_str_list(&g.exclude), true),
        ("include".into(), crate::utils::fmt_str_list(&g.include), true),
        ("respect_gitignore".into(), g.respect_gitignore.to_string(), true),
        ("flavor".into(), g.flavor.pascal().to_string(), true),
        ("line_length".into(), g.line_length.to_string(), false),
        ("force_exclude".into(), g.force_exclude.to_string(), false),
        ("cache".into(), g.cache.to_string(), false),
        ("output_format".into(), format!("\"{}\"", g.output_format), false),
        ("cache_dir".into(), format!("\"{}\"", g.cache_dir), false),
        ("fixable".into(), crate::utils::fmt_str_list(&g.fixable), false),
        ("unfixable".into(), crate::utils::fmt_str_list(&g.unfixable), false),
    ];
    for (k, v, always) in gvals.drain(..) {
        let provided = crate::utils::global_provided(cfg, &k);
        if no_defaults && !provided {
            continue;
        }
        if only_defaults && provided {
            continue;
        }
        if !always && !provided && !(only_defaults) {
            continue;
        }
        if !always && !provided {
            continue;
        }
        let src = if provided {
            cfg.source.label()
        } else {
            ConfigSource::Default.label()
        };
        entries.push(("[global]".into(), format!("{} = {}", k, v), src.to_string()));
    }
    // per-file-ignores
    if !only_defaults || true {
        let provided = !g.per_file_ignores.is_empty();
        if provided && !only_defaults {
            for (pat, rules) in &g.per_file_ignores {
                entries.push((
                    "[per-file-ignores]".into(),
                    format!("\"{}\" = {}", pat, crate::utils::fmt_str_list(rules)),
                    cfg.source.label().to_string(),
                ));
            }
        }
    }
    // rules
    for r in crate::rules::ALL {
        let keys = crate::config::known_keys(r.code);
        if keys.is_empty() {
            continue;
        }
        let mut section: Vec<(String, String, String)> = Vec::new();
        for k in keys {
            let provided = cfg.get(r.code, k).is_some();
            if no_defaults && !provided {
                continue;
            }
            if only_defaults && provided {
                continue;
            }
            let val = match cfg.get(r.code, k) {
                Some(v) => {
                    if matches!(v, toml::Value::Table(_)) {
                        None
                    } else {
                        Some(crate::utils::fmt_toml(v))
                    }
                }
                None => crate::config::default_value(r.code, k)
                    .map(|v| crate::utils::fmt_toml(&v)),
            };
            if let Some(val) = val {
                let src = if provided {
                    cfg.source.label()
                } else {
                    ConfigSource::Default.label()
                };
                section.push((format!("[{}]", r.code), format!("{} = {}", k, val), src.to_string()));
            }
        }
        if !section.is_empty() {
            entries.extend(section);
        }
    }
    // pad
    let maxlen = entries
        .iter()
        .map(|(s, k, _)| if s.starts_with('[') { s.chars().count() } else { k.chars().count() })
        .max()
        .unwrap_or(0)
        + 1;
    let mut out = String::new();
    let mut last_section = String::new();
    for (sec, kv, src) in entries {
        if sec != last_section {
            if !last_section.is_empty() {
                out.push('\n');
            }
            out.push_str(&format!("{:<w$}\n", sec, w = maxlen));
            last_section = sec.clone();
        }
        let label = if colors {
            crate::utils::dim_str(&src)
        } else {
            src.to_string()
        };
        out.push_str(&format!("{:<w$}{}\n", kv, label, w = maxlen));
    }
    out
}
