use crate::config::{Config, ConfigSource};
use crate::rules::{Issue, R};

pub struct FileResult {
    pub path: String,
    pub issues: Vec<Issue>,
    pub fixed: usize,
}

pub fn summary_lines(
    results: &[FileResult],
    total_files: usize,
    elapsed_ms: usize,
    fix_mode: bool,
    plain: bool,
) -> Vec<String> {
    let total_issues: usize = results.iter().map(|r| r.issues.len()).sum();
    let files_with = results.iter().filter(|r| !r.issues.is_empty()).count();
    let mut out = Vec::new();
    if total_issues == 0 {
        let plural = if total_files == 1 { "file" } else { "files" };
        let s = format!("Success: No issues found in {} {}", total_files, plural);
        if plain {
            out.push(format!("\x1b[1;32mSuccess:\x1b[0m No issues found in {} {} ({}ms)", total_files, plural, elapsed_ms));
        } else {
            out.push(format!("{}({}ms)", s, elapsed_ms));
        }
    } else if fix_mode {
        let fixed: usize = results.iter().map(|r| r.fixed).sum();
        let plural = if total_issues == 1 { "issue" } else { "issues" };
        let fp = if files_with == 1 { "file" } else { "files" };
        out.push(format!(
            "Fixed: Fixed {}/{} {} in {} {} ({}ms)",
            fixed,
            total_issues,
            plural,
            files_with,
            fp,
            elapsed_ms
        ));
    } else {
        let plural = if total_issues == 1 { "issue" } else { "issues" };
        let fp = if files_with == 1 { "file" } else { "files" };
        let s = format!(
            "Issues: Found {} {} in {}/{} {}",
            total_issues, plural, files_with, total_files, fp
        );
        if plain {
            out.push(format!("\x1b[33mIssues:\x1b[0m {} ({}ms)", &s["Issues:".len()..], elapsed_ms));
        } else {
            out.push(format!("{}({}ms)", s, elapsed_ms));
        }
    }
    if total_issues > 0 && !fix_mode {
        let fixable: usize = results
            .iter()
            .flat_map(|r| r.issues.iter())
            .filter(|i| i.fix.is_some())
            .count();
        let plural = if total_issues == 1 { "issue" } else { "issues" };
        out.push(format!(
            "Run `rumdl fmt` to automatically fix {} of the {} {}",
            fixable, total_issues, plural
        ));
    }
    out
}

pub fn text_lines(results: &[FileResult], colors: bool, show_fix: bool) -> Vec<String> {
    let mut out = Vec::new();
    for r in results {
        for i in &r.issues {
            let marker = if show_fix {
                if i.fix.is_some() {
                    " [fixed]"
                } else {
                    ""
                }
            } else if i.fix.is_some() {
                " [*]"
            } else {
                ""
            };
            if colors {
                out.push(format!(
                    "\x1b[4;34m{}\x1b[0m:\x1b[36m{}\x1b[0m:\x1b[36m{}\x1b[0m: \x1b[33m[{}]\x1b[0m {}\x1b[32m{}\x1b[0m",
                    r.path, i.line, i.column, i.code, i.message, marker
                ));
            } else {
                out.push(format!(
                    "{}:{}:{}: [{}] {}{}",
                    r.path, i.line, i.column, i.code, i.message, marker
                ));
            }
        }
    }
    out
}

pub fn grouped_lines(results: &[FileResult], show_fix: bool) -> Vec<String> {
    let mut out = Vec::new();
    for r in results {
        out.push(format!("{}:", r.path));
        // group by rule
        let mut codes: Vec<&str> = Vec::new();
        for i in &r.issues {
            if !codes.contains(&i.code) {
                codes.push(i.code);
            }
        }
        for c in codes {
            out.push(format!("  {}:", c));
            for i in r.issues.iter().filter(|i| i.code == c) {
                let extra = if show_fix && i.fix.is_some() {
                    " (fixable)"
                } else if i.fix.is_some() {
                    " (fixable)"
                } else {
                    ""
                };
                out.push(format!("    {}:{} {}{}", i.line, i.column, i.message, extra));
            }
        }
    }
    out
}

pub fn statistics(results: &[FileResult]) -> Vec<String> {
    let mut counts: Vec<(&str, usize, usize)> = Vec::new();
    for r in results {
        for i in &r.issues {
            let fixable = if i.fix.is_some() { 1 } else { 0 };
            match counts.iter_mut().find(|(c, _, _)| *c == i.code) {
                Some((_, n, f)) => {
                    *n += 1;
                    *f += fixable;
                }
                None => counts.push((i.code, 1, fixable)),
            }
        }
    }
    let total: usize = counts.iter().map(|(_, n, _)| n).sum();
    let total_fix: usize = counts.iter().map(|(_, _, f)| f).sum();
    let mut out = Vec::new();
    if total == 0 {
        return out;
    }
    counts.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    out.push(String::new());
    out.push("Rule Violation Statistics:".to_string());
    out.push(format!(
        "{:<9}{:<13}{:<9}{}",
        "Rule", "Violations", "Fixable", "Percentage"
    ));
    out.push("-".repeat(50));
    for (code, n, f) in &counts {
        let pct = (*n as f64 / total as f64) * 100.0;
        let fixable_str = if *f == 0 { "-".to_string() } else { f.to_string() };
        out.push(format!(
            "{:<9}{:<13}{:<9}{:.1}%",
            code,
            n.to_string(),
            fixable_str,
            pct
        ));
    }
    out.push("-".repeat(50));
    out.push(format!(
        "{:<9}{:<13}{:<9}{}",
        "Total",
        total.to_string(),
        if total_fix == 0 {
            "-".to_string()
        } else {
            total_fix.to_string()
        },
        "100.0%"
    ));
    out
}

// ---------- JSON formats ----------

pub fn to_json(results: &[FileResult]) -> serde_json::Value {
    let mut files = Vec::new();
    for r in results {
        for i in &r.issues {
            let mut o = serde_json::Map::new();
            o.insert("file".into(), serde_json::json!(r.path));
            o.insert("line".into(), serde_json::json!(i.line as u64));
            o.insert("column".into(), serde_json::json!(i.column as u64));
            o.insert("rule".into(), serde_json::json!(i.code));
            o.insert("message".into(), serde_json::json!(i.message));
            o.insert(
                "severity".into(),
                serde_json::json!(crate::rules::severity_of(i.code)),
            );
            o.insert("fixable".into(), serde_json::json!(i.fix.is_some()));
            if let Some(f) = &i.fix {
                let mut fx = serde_json::Map::new();
                fx.insert(
                    "range".into(),
                    serde_json::json!({"start": f.start as u64, "end": f.end as u64}),
                );
                fx.insert("replacement".into(), serde_json::json!(f.replacement));
                o.insert("fix".into(), serde_json::Value::Object(fx));
            }
            files.push(serde_json::Value::Object(o));
        }
    }
    let total: usize = results.iter().map(|r| r.issues.len()).sum();
    serde_json::json!([files])
        .map(|_| serde_json::Value::Null)
        .unwrap_or(serde_json::Value::Null);
    let mut files_wrapped = serde_json::Map::new();
    files_wrapped.insert("files".into(), serde_json::Value::Array(files));
    files_wrapped.insert(
        "summary".into(),
        serde_json::json!({
            "files_checked": results.len() as u64,
            "issues_found": total as u64
        }),
    );
    serde_json::Value::Object(files_wrapped)
}

pub fn to_json_lines(results: &[FileResult]) -> String {
