pub fn to_github(results: &[FileResult]) -> Vec<String> {
    let mut out = Vec::new();
    for r in results {
        for i in &r.issues {
            let end_col = i.column + i.message.chars().count();
            out.push(format!(
                "::warning file={},line={},col={},endLine={},endColumn={},title={}::{}",
                r.path, i.line, i.column, i.line, end_col, i.code, i.message
            ));
        }
    }
    out
}

pub fn to_azure(results: &[FileResult]) -> Vec<String> {
    let mut out = Vec::new();
    for r in results {
        for i in &r.issues {
            out.push(format!(
                "##vso[task.logissue type=warning;sourcepath={};linenumber={};columnnumber={};code={}]{}",
                r.path, i.line, i.column, i.code, i.message
            ));
        }
    }
    out
}

pub fn to_pylint(results: &[FileResult]) -> Vec<String> {
    let mut out = Vec::new();
    for r in results {
        for i in &r.issues {
            out.push(format!(
                "{}:{}:{}: [C{}] {}",
                r.path, i.line, i.column, i.code, i.message
            ));
        }
    }
    out
}

pub fn to_gitlab(results: &[FileResult]) -> serde_json::Value {
    let mut arr = Vec::new();
    for r in results {
        for i in &r.issues {
            arr.push(serde_json::json!({
                "description": i.message,
                "check_name": i.code,
                "fingerprint": format!("{}-{}-{}-{}", r.path, i.line, i.column, i.code),
                "severity": "minor",
                "location": {
                    "path": r.path,
                    "lines": { "begin": i.line as u64 }
                }
            }));
        }
    }
    serde_json::Value::Array(arr)
}

pub fn to_sarif(results: &[FileResult], rules: &[&R]) -> serde_json::Value {
    let mut used: Vec<&str> = Vec::new();
    for r in results {
        for i in &r.issues {
            if !used.contains(&i.code) {
                used.push(i.code);
            }
        }
    }
    used.sort();
    let mut rule_objs = Vec::new();
    for code in &used {
        rule_objs.push(serde_json::json!({
            "id": code,
            "name": code,
            "shortDescription": { "text": format!("Markdown rule {}", code) },
            "fullDescription": { "text": format!("Markdown linting rule {}", code) }
        }));
    }
    let _ = rules;
    let mut res = Vec::new();
    for r in results {
        for i in &r.issues {
            let sev = match crate::rules::severity_of(i.code) {
                "error" => "error",
                _ => "warning",
            };
            res.push(serde_json::json!({
                "ruleId": i.code,
                "level": sev,
                "message": { "text": i.message },
                "locations": [ {
                    "physicalLocation": {
                        "artifactLocation": { "uri": r.path },
                        "region": {
                            "startLine": i.line as u64,
                            "startColumn": i.column as u64,
                            "endLine": i.line as u64,
                            "endColumn": (i.column + i.message.chars().count()) as u64
                        }
                    }
                } ]
            }));
        }
    }
    serde_json::json!({
        "$schema": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
        "version": "2.1.0",
        "runs": [ {
            "tool": { "driver": {
                "name": "rumdl",
                "version": crate::config::VERSION,
                "informationUri": "https://github.com/rvben/rumdl",
                "rules": rule_objs
            } },
            "results": res
        } ]
    })
}

pub fn to_junit(results: &[FileResult]) -> String {
    let total_files = results.len();
    let total_issues: usize = results.iter().map(|r| r.issues.len()).sum();
    let mut out = String::new();
    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    out.push_str(&format!(
        "<testsuites name=\"rumdl\" tests=\"{}\" failures=\"{}\" errors=\"0\" time=\"{:.3}\">\n",
        total_files,
        total_issues,
        crate::utils::last_ms() as f64 / 1000.0
    ));
    for r in results {
        let n = r.issues.len();
        out.push_str(&format!(
            "  <testsuite name=\"{}\" tests=\"{}\" failures=\"{}\" errors=\"0\" time=\"0.000\">\n",
            r.path,
            if n == 0 { 1 } else { 1 },
            n
        ));
        out.push_str(&format!(
            "    <testcase name=\"Lint {}\" classname=\"rumdl\" time=\"0.000\">\n",
            r.path
        ));
        for i in &r.issues {
            let msg = crate::utils::xml_escape(&i.message);
            out.push_str(&format!(
                "      <failure type=\"{}\" message=\"{}\">{} at line {}, column {}</failure>\n",
                i.code, msg, msg, i.line, i.column
            ));
        }
        out.push_str("    </testcase>\n");
        out.push_str("  </testsuite>\n");
    }
    out.push_str("</testsuites>\n");
    out
}

// ---------- config display ----------

pub fn config_text(cfg: &Config, only_defaults: bool, no_defaults: bool, colors: bool) -> String {
    let mut entries: Vec<(String, String, String)> = Vec::new();
    let g = &cfg.global;
    let has_config = cfg.path.is_some();
    let canonical: Vec<(&str, String)> = vec![
        ("enable", crate::utils::fmt_str_list(&g.enable)),
        ("disable", crate::utils::fmt_str_list(&g.disable)),
        ("exclude", crate::utils::fmt_str_list(&g.exclude)),
        ("include", crate::utils::fmt_str_list(&g.include)),
        ("respect_gitignore", g.respect_gitignore.to_string()),
        ("flavor", g.flavor.pascal().to_string()),
    ];
    let extras: Vec<(&str, String)> = vec![
        ("line_length", g.line_length.to_string()),
        ("force_exclude", g.force_exclude.to_string()),
        ("cache", g.cache.to_string()),
        ("output_format", format!("\"{}\"", g.output_format)),
        ("cache_dir", format!("\"{}\"", g.cache_dir)),
        ("fixable", crate::utils::fmt_str_list(&g.fixable)),
        ("unfixable", crate::utils::fmt_str_list(&g.unfixable)),
    ];
    if no_defaults {
        for (k, v) in canonical.iter().chain(extras.iter()) {
            if crate::utils::global_provided(cfg, k) {
                entries.push((
                    "[global]".into(),
                    format!("{} = {}", k, v),
                    cfg.source.label().to_string(),
                ));
            }
        }
        for (pat, rules) in &g.per_file_ignores {
            entries.push((
                "[per-file-ignores]".into(),
                format!("\"{}\" = {}", pat, crate::utils::fmt_str_list(rules)),
                cfg.source.label().to_string(),
            ));
        }
        for r in crate::rules::ALL {
            for k in crate::config::known_keys(r.code) {
                if let Some(v) = cfg.get(r.code, k) {
                    if matches!(v, toml::Value::Table(_)) {
                        continue;
                    }
                    entries.push((
                        format!("[{}]", r.code),
                        format!("{} = {}", k, crate::utils::fmt_toml(v)),
                        cfg.source.label().to_string(),
                    ));
                }
            }
        }
    } else if only_defaults {
        for (k, v) in &canonical {
            entries.push((
                "[global]".into(),
                format!("{} = {}", k, v),
                ConfigSource::Default.label().to_string(),
            ));
        }
        for r in crate::rules::ALL {
            for k in crate::config::known_keys(r.code) {
                let val = match crate::config::default_value(r.code, k) {
                    Some(v) => crate::utils::fmt_toml(&v),
                    None => continue,
                };
                entries.push((
                    format!("[{}]", r.code),
                    format!("{} = {}", k, val),
                    ConfigSource::Default.label().to_string(),
                ));
            }
        }
    } else if !has_config {
        for (k, v) in &canonical {
            entries.push((
                "[global]".into(),
                format!("{} = {}", k, v),
                ConfigSource::Default.label().to_string(),
            ));
        }
        for r in crate::rules::ALL {
            for k in crate::config::known_keys(r.code) {
                let val = match crate::config::default_value(r.code, k) {
                    Some(v) => crate::utils::fmt_toml(&v),
                    None => continue,
                };
                entries.push((
                    format!("[{}]", r.code),
                    format!("{} = {}", k, val),
                    ConfigSource::Default.label().to_string(),
                ));
            }
        }
    } else {
        for (k, v) in &canonical {
            let provided = crate::utils::global_provided(cfg, k);
            let src = if provided {
                cfg.source.label()
            } else {
                ConfigSource::Default.label()
            };
            entries.push(("[global]".into(), format!("{} = {}", k, v), src.to_string()));
        }
        for (k, v) in &extras {
            if crate::utils::global_provided(cfg, k) {
                entries.push((
                    "[global]".into(),
                    format!("{} = {}", k, v),
                    cfg.source.label().to_string(),
                ));
            }
        }
        if !g.per_file_ignores.is_empty() {
            for (pat, rules) in &g.per_file_ignores {
                entries.push((
                    "[per-file-ignores]".into(),
                    format!("\"{}\" = {}", pat, crate::utils::fmt_str_list(rules)),
                    cfg.source.label().to_string(),
                ));
            }
        }
        for r in crate::rules::ALL {
            let keys = crate::config::known_keys(r.code);
            if keys.is_empty() {
                continue;
            }
            let provided: Vec<&str> = keys
                .iter()
                .filter(|k| crate::utils::rule_provided(cfg, r.code, k))
                .copied()
                .collect();
            if provided.is_empty() {
                continue;
            }
            for k in provided {
                if let Some(v) = cfg.get(r.code, k) {
                    if matches!(v, toml::Value::Table(_)) {
                        continue;
                    }
                    entries.push((
                        format!("[{}]", r.code),
                        format!("{} = {}", k, crate::utils::fmt_toml(v)),
                        cfg.source.label().to_string(),
                    ));
                }
            }
        }
    }
    let maxlen = entries
        .iter()
        .map(|(s, k, _)| s.chars().count().max(k.chars().count()))
        .max()
        .unwrap_or(0)
        + 1;
    let mut out = String::new();
    let mut last_section = String::new();
    for (sec, kv, src) in entries {
        if sec != last_section {
            if !last_section.is_empty() {
                out.push('\n');
            }
            out.push_str(&format!("{:<w$}\n", sec, w = maxlen));
            last_section = sec.clone();
        }
        let label = if colors {
            crate::utils::dim_str(&src)
        } else {
            src.to_string()
        };
        out.push_str(&format!("{:<w$}{}\n", kv, label, w = maxlen));
    }
    out
}
