use clap::{Arg, ArgAction, Command};
use std::path::PathBuf;
use std::time::Instant;

use crate::config::{self, Config, ConfigSource};
use crate::output::FileResult;
use crate::rules::{Fix, Issue};
use crate::lint::Ctx;

pub fn color_arg() -> Arg {
    Arg::new("color")
        .long("color")
        .value_name("COLOR")
        .default_value("auto")
        .value_parser(["auto", "always", "never"])
        .help("Control colored output: auto, always, never")
}

pub fn config_arg() -> Arg {
    Arg::new("config")
        .long("config")
        .value_name("CONFIG")
        .help("Path to configuration file")
}

pub fn no_config_arg() -> Arg {
    Arg::new("no-config")
        .long("no-config")
        .action(ArgAction::SetTrue)
        .conflicts_with("config")
        .help("Ignore all configuration files and use built-in defaults")
}

pub fn isolated_arg() -> Arg {
    Arg::new("isolated")
        .long("isolated")
        .action(ArgAction::SetTrue)
        .help("Ignore all configuration files (alias for --no-config)")
}

include!("cli_cmds.rs");

fn err_exit(msg: &str, code: i32) -> ! {
    eprintln!("Error: {}", msg);
    std::process::exit(code);
}

pub fn colors_for(m: &clap::ArgMatches) -> bool {
    let mode = m.get_one::<String>("color").map(|s| s.as_str()).unwrap_or("auto");
    match mode {
        "always" => true,
        "never" => false,
        _ => crate::utils::is_stdout_tty(),
    }
}

pub fn load_config(m: &clap::ArgMatches) -> Config {
    if m.get_flag("no-config") || m.get_flag("isolated") {
        return config::empty();
    }
    let explicit = m.get_one::<String>("config").map(|s| PathBuf::from(s));
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    config::load(explicit.as_deref(), &cwd)
}

pub fn warn_config(cfg: &Config) {
    for w in &cfg.warnings {
        eprintln!("{}", crate::utils::yellow_str(w));
    }
}

fn rule_codes(list: &str) -> Vec<String> {
    list.split(',')
        .map(|s| s.trim().to_uppercase())
        .filter(|s| !s.is_empty())
        .collect()
}

fn enabled_rules(
    cfg: &Config,
    cli_enable: Option<&String>,
    cli_disable: Option<&String>,
    ext_enable: Option<&String>,
    ext_disable: Option<&String>,
) -> Vec<&'static crate::rules::R> {
    let mut codes: Vec<String> = Vec::new();
    if let Some(e) = cli_enable {
        codes = rule_codes(e);
    } else if !cfg.global.enable.is_empty() {
        codes = cfg.global.enable.iter().map(|s| s.to_uppercase()).collect();
    }
    if let Some(e) = ext_enable {
        for c in rule_codes(e) {
            if !codes.contains(&c) {
                codes.push(c);
            }
        }
    }
    let mut disabled: Vec<String> = cfg.global.disable.iter().map(|s| s.to_uppercase()).collect();
    if let Some(d) = cli_disable {
        for c in rule_codes(d) {
            if !disabled.contains(&c) {
                disabled.push(c);
            }
        }
    }
    if let Some(d) = ext_disable {
        for c in rule_codes(d) {
            if !disabled.contains(&c) {
                disabled.push(c);
            }
        }
    }
    crate::rules::ALL
        .iter()
        .filter(|r| {
            if codes.is_empty() {
                true
            } else {
                codes.iter().any(|c| c == r.code)
            }
        })
        .filter(|r| !disabled.iter().any(|c| c == r.code))
        .collect()
}

pub fn run_check(m: &clap::ArgMatches, fix_forced: bool) -> i32 {
    let colors = colors_for(m);
    let cfg = load_config(m);
    warn_config(&cfg);
    let fix = fix_forced || m.get_flag("fix");
    if fix && m.get_flag("check") {
        err_exit(
            "--check and --fix cannot be used together\nUse --check to verify formatting without changes, or --fix to apply them",
            2,
        );
    }
    if m.get_flag("list-rules") {
        for r in crate::rules::ALL {
            println!("  {} - {}", r.code, r.summary);
        }
        println!();
        println!("Total: {} rules", crate::rules::ALL.len());
        return 0;
    }
    let rules = enabled_rules(
        &cfg,
        m.get_one::<String>("enable"),
        m.get_one::<String>("disable"),
        m.get_one::<String>("extend-enable"),
        m.get_one::<String>("extend-disable"),
    );
    if m.get_flag("verbose") {
        println!("Enabled rules:");
        for r in &rules {
            println!("  - {} ({})", r.code, r.summary);
        }
        println!();
        let excludes: Vec<String> = if m.get_flag("no-exclude") {
            vec![]
        } else {
            match m.get_one::<String>("exclude") {
                Some(e) => e.split(',').map(|s| s.to_string()).collect(),
                None => cfg.global.exclude.clone(),
            }
        };
        println!("Exclude patterns: {:?}", excludes);
    }
    let output_format = m
        .get_one::<String>("output-format")
        .map(|s| s.clone())
        .unwrap_or_else(|| {
            if m.get_one::<String>("output").map(|s| s.as_str()) == Some("json") {
                "json".to_string()
            } else {
                env_or("RUMDL_OUTPUT_FORMAT", cfg.global.output_format.clone())
            }
        });
    let use_stdin = m.get_flag("stdin")
        || std::io::stdin().is_terminal() == false && false;
    let quiet = m.get_flag("quiet") || m.get_flag("silent");
    let silent = m.get_flag("silent");
    let paths: Vec<String> = match m.get_many::<String>("paths") {
        Some(v) => v.cloned().collect(),
        None => vec![],
    };
    let mut stdin_file = false;
    if paths.iter().any(|p| p == "-") || m.get_flag("stdin") {
        stdin_file = true;
    }
    let excludes: Vec<crate::utils::Glob> = if m.get_flag("no-exclude") {
        vec![]
    } else {
        match m.get_one::<String>("exclude") {
            Some(e) => e
                .split(',')
                .filter(|s| !s.trim().is_empty())
                .map(crate::utils::Glob::new)
                .collect(),
            None => cfg.global.exclude.iter().map(|s| crate::utils::Glob::new(s)).collect(),
        }
    };
    let includes: Vec<crate::utils::Glob> = match m.get_one::<String>("include") {
        Some(e) => e
            .split(',')
            .filter(|s| !s.trim().is_empty())
            .map(crate::utils::Glob::new)
            .collect(),
        None => cfg.global.include.iter().map(|s| crate::utils::Glob::new(s)).collect(),
    };
    let respect_gi = match m.get_one::<String>("respect-gitignore") {
        Some(v) => v == "true",
        None => cfg.global.respect_gitignore,
    };
    let force_exclude = m.get_flag("force-exclude") || cfg.global.force_exclude;
    let start = Instant::now();
    let mut results: Vec<FileResult> = Vec::new();
    let mut total_files = 0usize;
    if stdin_file {
        let mut buf = String::new();
        use std::io::Read;
        let _ = std::io::stdin().read_to_string(&mut buf);
        let name = m
            .get_one::<String>("stdin-filename")
            .cloned()
            .unwrap_or_else(|| "<stdin>".to_string());
        let issues = lint_text(&buf, &cfg, &rules, &name);
        results.push(FileResult {
            path: name.clone(),
            issues,
            fixed: 0,
        });
        total_files = 1;
    } else {
        let files = match crate::lint::collect_files(
            &paths,
            &excludes,
            &includes,
            respect_gi,
            force_exclude,
        ) {
            Ok(f) => f,
            Err(e) => {
                err_exit(&format!("Failed to find markdown files: {}", e), 1);
            }
        };
        if files.is_empty() {
            if !quiet {
                println!("No markdown files found to check.");
            }
            return 0;
        }
        total_files = files.len();
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let show_full = m.get_flag("show-full-path");
        for f in &files {
            let text = match std::fs::read_to_string(f) {
                Ok(t) => t,
                Err(_) => continue,
            };
            let rel = if show_full {
                std::fs::canonicalize(f)
                    .unwrap_or_else(|_| f.clone())
                    .to_string_lossy()
                    .to_string()
            } else {
                crate::utils::rel_to_cwd(f)
            };
            let ctx = Ctx::new(f.clone(), rel.clone());
            let mut issues = lint_text(&text, &cfg, &rules, &rel);
            crate::lint::sort_issues(&mut issues);
            let mut fixed = 0usize;
            if fix {
                let (newtext, applied, changed) = fix_text(&text, &cfg, &rules, &ctx);
                let _ = changed;
                fixed = applied;
                if newtext != text {
                    let _ = std::fs::write(f, &newtext);
                }
            }
            if m.get_flag("verbose") {
                println!("Processing file: {}", rel);
            }
            results.push(FileResult {
                path: rel,
                issues,
                fixed,
            });
        }
        let _ = &cwd;
    }
    let elapsed = start.elapsed().as_millis() as usize;
    crate::utils::set_last_ms(elapsed);
    if fix {
        // re-lint to determine remaining issues
        let mut remaining: Vec<FileResult> = Vec::new();
        for r in &results {
            let text = if r.path == "<stdin>" || !std::path::Path::new(&r.path).exists() {
                String::new()
            } else {
                std::fs::read_to_string(&r.path).unwrap_or_default()
            };
            let issues = lint_text(&text, &cfg, &rules, &r.path);
            remaining.push(FileResult {
                path: r.path.clone(),
                issues,
                fixed: r.fixed,
            });
        }
        let _ = &mut remaining;
        results = results;
    }
    // Determine the "fixed" set of issues to print (from the original lint)
    let print_fix_marker = fix;
    let mut out: Vec<String> = Vec::new();
    if output_format == "json" {
        let v = crate::output::to_json(&results);
        out.push(serde_json::to_string_pretty(&v).unwrap_or_default());
    } else if output_format == "json-lines" {
        out.push(crate::output::to_json_lines(&results));
    } else if output_format == "gitlab" {
        let v = crate::output::to_gitlab(&results);
        out.push(serde_json::to_string_pretty(&v).unwrap_or_default());
    } else if output_format == "sarif" {
        let v = crate::output::to_sarif(&results, &rules);
        out.push(serde_json::to_string_pretty(&v).unwrap_or_default());
    } else if output_format == "junit" {
        out.push(crate::output::to_junit(&results));
    } else {
        let mut lines = crate::output::text_lines(&results, colors, print_fix_marker);
        if output_format == "grouped" {
            lines = crate::output::grouped_lines(&results, print_fix_marker);
        } else if output_format == "github" {
            lines = crate::output::to_github(&results);
        } else if output_format == "azure" {
            lines = crate::output::to_azure(&results);
        } else if output_format == "pylint" {
            lines = crate::output::to_pylint(&results);
        }
        if !lines.is_empty() {
            out.extend(lines);
            out.push(String::new());
        }
        if !quiet {
            let sum = crate::output::summary_lines(&results, total_files, elapsed, fix, colors);
            out.extend(sum);
        }
        if m.get_flag("statistics") && !quiet {
            out.extend(crate::output::statistics(&results));
        }
    }
    if !silent {
        for l in &out {
            if m.get_flag("stderr") && looks_like_diagnostic(l) {
                eprintln!("{}", l);
            } else {
                println!("{}", l);
            }
        }
    }
    let remaining_issues: usize = results.iter().map(|r| r.issues.len()).sum();
    let exit = if fix {
        let unfixable: usize = results
            .iter()
            .flat_map(|r| r.issues.iter())
            .filter(|i| i.fix.is_none())
            .count();
        if unfixable > 0 {
            1
        } else {
            0
        }
    } else if remaining_issues > 0 {
        match m.get_one::<String>("fail-on").map(|s| s.as_str()).unwrap_or("any") {
            "never" => 0,
            "error" => {
                if results
                    .iter()
                    .flat_map(|r| r.issues.iter())
                    .any(|i| crate::rules::severity_of(i.code) == "error")
                {
                    1
                } else {
                    0
                }
            }
            "warning" => {
                if results
                    .iter()
                    .flat_map(|r| r.issues.iter())
                    .any(|i| crate::rules::severity_of(i.code) != "info")
                {
                    1
                } else {
                    0
                }
            }
            _ => 1,
        }
    } else {
        0
    };
    if fix_forced {
        return 0;
    }
    exit
}

fn looks_like_diagnostic(l: &str) -> bool {
    l.contains(": [MD") && !l.starts_with('I') && !l.starts_with('F') && !l.starts_with('R')
}

fn env_or(var: &str, default: String) -> String {
    std::env::var(var).unwrap_or(default)
}

pub fn lint_text(
    text: &str,
    cfg: &Config,
    rules: &[&'static crate::rules::R],
    rel: &str,
) -> Vec<Issue> {
    let flavor = cfg.global.flavor;
    let doc = crate::doc::Doc::new(text, flavor);
    let ctx = Ctx::new(PathBuf::from(rel), rel.to_string());
    let mut out: Vec<Issue> = Vec::new();
    for r in rules {
        if let Some(f) = crate::rules::dispatch(r.code) {
            let mut v = f(&doc, cfg, &ctx);
            // global fixable / unfixable
            for i in v.iter_mut() {
                if !cfg.global.fixable.is_empty()
                    && !cfg.global.fixable.iter().any(|c| c.eq_ignore_ascii_case(r.code))
                {
                    i.fix = None;
                }
                if cfg
                    .global
                    .unfixable
                    .iter()
                    .any(|c| c.eq_ignore_ascii_case(r.code))
                {
                    i.fix = None;
                }
            }
            out.append(&mut v);
        }
    }
    out
}

/// Apply fixes iteratively; returns (final text, applied count in first round, changed)
pub fn fix_text(
    text: &str,
    cfg: &Config,
    rules: &[&'static crate::rules::R],
    ctx: &Ctx,
) -> (String, usize, bool) {
    let mut current = text.to_string();
    let mut first_applied = 0usize;
    let mut rounds = 0usize;
    loop {
        let issues = lint_text(&current, cfg, rules, &ctx.rel_path);
        let fixes: Vec<Fix> = issues.iter().filter_map(|i| i.fix.clone()).collect();
        if fixes.is_empty() {
            break;
        }
        let (newtext, applied) = crate::fix::apply(&current, &fixes);
        if rounds == 0 {
            first_applied = applied;
        }
        if newtext == current {
            break;
        }
        current = newtext;
        rounds += 1;
        if rounds > 10 {
            break;
        }
    }
    (current, first_applied, current != text)
}

pub fn run() {
    let matches = build().get_matches();
    let code = match matches.subcommand() {
        Some(("check", m)) => run_check(m, false),
        Some(("fmt", m)) => run_check(m, true),
        Some(("version", _)) => {
            println!("rumdl {}", config::VERSION);
            0
        }
        Some(("clean", m)) => cmd_clean(m),
        Some(("init", m)) => cmd_init(m),
        Some(("rule", m)) => cmd_rule(m),
        Some(("explain", m)) => cmd_explain(m),
        Some(("config", m)) => cmd_config(m),
        Some(("import", m)) => cmd_import(m),
        Some(("schema", m)) => cmd_schema(m),
        Some(("completions", m)) => cmd_completions(m),
        Some(("vscode", m)) => cmd_vscode(m),
        Some(("server", m)) => crate::lsp::run(m),
        _ => 0,
    };
    std::process::exit(code);
}

fn cmd_clean(m: &clap::ArgMatches) -> i32 {
    let cfg = load_config(m);
    let dir = std::env::current_dir()
        .unwrap_or_else(|_| PathBuf::from("."))
        .join(env_or("RUMDL_CACHE_DIR", cfg.global.cache_dir.clone()));
    if dir.exists() {
        let mut total = 0usize;
        let mut count = 0usize;
        if let Ok(rd) = std::fs::read_dir(&dir) {
            for e in rd.filter_map(|e| e.ok()) {
                let p = e.path();
                if p.is_file() {
                    if p.file_name().map(|n| n == ".gitignore").unwrap_or(false) {
                        continue;
                    }
                    if let Ok(md) = e.metadata() {
                        total += md.len() as usize;
                        count += 1;
                    }
                    let _ = std::fs::remove_file(&p);
                } else if p.is_dir() {
                    if let Ok(rd2) = std::fs::read_dir(&p) {
                        for e2 in rd2.filter_map(|e| e.ok()) {
                            let p2 = e2.path();
                            if p2.is_file() {
                                if let Ok(md) = e2.metadata() {
                                    total += md.len() as usize;
                                    count += 1;
                                }
                                let _ = std::fs::remove_file(&p2);
                            }
                        }
                    }
                    let _ = std::fs::remove_dir(&p);
                }
            }
        }
        let bytes = format_bytes(total);
        println!("Cleared cache: {}", crate::utils::rel_to_cwd(&dir));
        println!("  Removed {} across {} files", bytes, count);
    } else {
        println!(
            "No cache found at {} (nothing to clean)",
            dir.to_string_lossy()
        );
    }
    0
}

fn format_bytes(b: usize) -> String {
    if b < 1024 {
        format!("{} B", b)
    } else if b < 1024 * 1024 {
        format!("{:.1} KB", b as f64 / 1024.0)
    } else {
        format!("{:.1} MB", b as f64 / (1024.0 * 1024.0))
    }
}

fn cmd_init(m: &clap::ArgMatches) -> i32 {
    let pyproject = m.get_flag("pyproject");
    if pyproject {
        let p = PathBuf::from("pyproject.toml");
        if p.exists() {
            err_exit(
                &format!(
                    "Failed to create config file: pyproject.toml already exists"
                ),
                2,
            );
        }
        let _ = std::fs::write(&p, crate::init_tpl::PYPROJECT);
        println!("Created pyproject.toml with rumdl configuration");
        return 0;
    }
    let p = PathBuf::from(".rumdl.toml");
    if p.exists() {
        err_exit(
            "Failed to create config file: Configuration file already exists at .rumdl.toml",
            2,
        );
    }
    let _ = std::fs::write(&p, crate::init_tpl::RUMDL_TOML);
    println!("Created default configuration file: .rumdl.toml");
    println!();
    println!("Setup complete! You can now:");
    println!("  \u{2022} Run rumdl check . to lint your Markdown files");
    println!("  \u{2022} Open your editor to see real-time linting");
    0
}

fn cmd_rule(m: &clap::ArgMatches) -> i32 {
    let colors = colors_for(m);
    let _ = colors;
    if m.get_flag("list-categories") {
        println!("Available categories:");
        for (c, n) in crate::rules::categories() {
            println!("  {} ({} rules)", c.name(), n);
        }
        return 0;
    }
    let fmt = m.get_one::<String>("output-format").map(|s| s.as_str()).unwrap_or("text");
    let filter_fixable = m.get_flag("fixable");
    let cat = m.get_one::<String>("category");
    if let Some(catname) = cat {
        let c = match crate::rules::Category::from(catname) {
            Some(c) => c,
            None => {
                eprintln!("Error: Unknown category '{}'", catname);
                return 2;
            }
        };
        if fmt == "text" {
            for r in crate::rules::ALL.iter().filter(|r| r.category == c) {
                if filter_fixable && r.fix != crate::rules::FixAvail::Always {
                    continue;
                }
                println!("{} - {}", r.code, r.summary);
            }
            return 0;
        }
    }
    let sel: Vec<&crate::rules::R> = crate::rules::ALL
        .iter()
        .filter(|r| {
            if filter_fixable && r.fix != crate::rules::FixAvail::Always {
                return false;
            }
            if let Some(c) = cat {
                if let Some(cc) = crate::rules::Category::from(c) {
                    return r.category == cc;
                }
            }
            true
        })
        .collect();
    match m.get_one::<String>("rule") {
        Some(name) => match crate::rules::find(name) {
            Some(r) => {
                if fmt == "json" {
                    let v = serde_json::json!({
                        "code": r.code,
                        "name": r.name,
                        "aliases": r.aliases,
                        "summary": r.summary,
                        "category": r.category.name(),
                        "fix": r.fix.desc(),
                        "fix_availability": crate::rules::fix_avail_name(r.fix),
                        "url": format!("https://rumdl.dev/{}/", r.code.to_lowercase()),
                    });
                    println!("{}", serde_json::to_string_pretty(&v).unwrap_or_default());
                } else {
                    println!("{} - {}", r.code, r.summary);
                    println!();
                    println!("Name: {}", r.name);
                    println!("Category: {}", r.category.name());
                    println!("Fix: {}", r.fix.desc());
                    println!("Documentation: https://rumdl.dev/{}/", r.code.to_lowercase());
                }
                0
            }
            None => {
                eprintln!("Error: Unknown rule '{}'", name);
                2
            }
        },
        None => {
            if fmt == "json" || fmt == "json-lines" {
                let items: Vec<serde_json::Value> = sel
                    .iter()
                    .map(|r| {
                        serde_json::json!({
                            "code": r.code,
                            "name": r.name,
                            "aliases": r.aliases,
                            "summary": r.summary,
                            "category": r.category.name(),
                            "fix": r.fix.desc(),
                            "fix_availability": crate::rules::fix_avail_name(r.fix),
                            "url": format!("https://rumdl.dev/{}/", r.code.to_lowercase()),
                        })
                    })
                    .collect();
                if fmt == "json" {
                    println!(
                        "{}",
                        serde_json::to_string_pretty(&serde_json::Value::Array(items))
                            .unwrap_or_default()
                    );
                } else {
                    for it in items {
                        println!(
                            "{}",
                            serde_json::to_string(&it).unwrap_or_default()
                        );
                    }
                }
                return 0;
            }
            println!("Available rules:");
            for r in &sel {
                println!("  {} - {}", r.code, r.summary);
            }
            println!();
            println!("Total: {} rules", sel.len());
            0
        }
    }
}

fn cmd_explain(m: &clap::ArgMatches) -> i32 {
    let name = m.get_one::<String>("rule").unwrap();
    match crate::rules::find(name) {
        Some(r) => {
            println!("{} - {}", r.code, r.summary);
            println!();
            println!("Category: {}", title_case_word(r.category.name()));
            println!();
            println!("This rule helps maintain consistent Markdown formatting.");
            println!();
            println!("For more information, see the documentation at:");
            println!("  https://rumdl.dev/{}/", r.code.to_lowercase());
            0
        }
        None => {
            eprintln!("Error: Unknown rule '{}'", name);
            2
        }
    }
}

fn title_case_word(s: &str) -> String {
    let mut out = String::new();
    for part in s.split('-') {
        let mut cs = part.chars();
        if let Some(c) = cs.next() {
            out.extend(c.to_uppercase());
        }
        out.push_str(cs.as_str());
    }
    out
}

fn cmd_config(m: &clap::ArgMatches) -> i32 {
    let cfg = load_config(m);
    warn_config(&cfg);
    match m.subcommand() {
        Some(("get", sm)) => {
            let key = sm.get_one::<String>("key").cloned().unwrap_or_default();
            let parts: Vec<&str> = key.splitn(2, '.').collect();
            if parts.len() != 2 {
                eprintln!("Key must be in the form global.key or MDxxx.key");
                return 2;
            }
            let (sec, k) = (parts[0], crate::config::norm_key(parts[1]));
            if sec.eq_ignore_ascii_case("global") {
                let provided = crate::utils::global_provided(&cfg, &k);
                let v = match k.as_str() {
                    "enable" => crate::utils::fmt_str_list(&cfg.global.enable),
                    "disable" => crate::utils::fmt_str_list(&cfg.global.disable),
                    "exclude" => crate::utils::fmt_str_list(&cfg.global.exclude),
                    "include" => crate::utils::fmt_str_list(&cfg.global.include),
                    "respect-gitignore" => cfg.global.respect_gitignore.to_string(),
                    "line-length" => cfg.global.line_length.to_string(),
                    "fixable" => crate::utils::fmt_str_list(&cfg.global.fixable),
                    "unfixable" => crate::utils::fmt_str_list(&cfg.global.unfixable),
                    "flavor" => format!("\"{}\"", cfg.global.flavor.toml()),
                    "force-exclude" => cfg.global.force_exclude.to_string(),
                    "cache" => cfg.global.cache.to_string(),
                    "cache-dir" => format!("\"{}\"", cfg.global.cache_dir),
                    "output-format" => format!("\"{}\"", cfg.global.output_format),
                    _ => {
                        eprintln!("Unknown config key: {}", key);
                        return 2;
                    }
                };
                let src = if provided {
                    cfg.source.label()
                } else {
                    ConfigSource::Default.label()
                };
                println!("global.{} = {} [{}]", k, v, src);
                return 0;
            }
            let upper = sec.to_uppercase();
            if !crate::rules::ALL.iter().any(|r| r.code == upper) {
                eprintln!("Key must be in the form global.key or MDxxx.key");
                return 2;
            }
            let known = crate::config::known_keys(&upper);
            if !known.contains(&k.as_str()) {
                eprintln!("Unknown config key: {}", key);
                return 2;
            }
            let val = match cfg.get(&upper, &k) {
                Some(v) => {
                    if matches!(v, toml::Value::Table(_)) {
                        "<table>".to_string()
                    } else {
                        crate::utils::fmt_toml(v)
                    }
                }
                None => match crate::config::default_value(&upper, &k) {
                    Some(v) => crate::utils::fmt_toml(&v),
                    None => {
                        eprintln!("Unknown config key: {}", key);
                        return 2;
                    }
                },
            };
            let provided = crate::utils::rule_provided(&cfg, &upper, &k);
            let src = if provided {
                cfg.source.label()
            } else {
                ConfigSource::Default.label()
            };
            println!("{}.{} = {} [{}]", upper, k, val, src);
            0
        }
        Some(("file", _)) => match &cfg.path {
            Some(p) => {
                println!("{}", std::fs::canonicalize(p).unwrap_or_else(|_| p.clone()).to_string_lossy());
                0
            }
            None => {
                println!("No configuration file found (using defaults)");
                0
            }
        },
        _ => {
            let only_defaults = m.get_flag("defaults");
            let no_defaults = m.get_flag("no-defaults");
            let colors = colors_for(m);
            let txt = crate::output::config_text(&cfg, only_defaults, no_defaults, colors);
            if no_defaults && txt.trim().is_empty() {
                println!("All configurations are using default values.");
                return 0;
            }
            let fmt = m.get_one::<String>("output").map(|s| s.as_str()).unwrap_or("text");
            if fmt == "json" {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&crate::config::to_json_value(&cfg))
                        .unwrap_or_default()
                );
            } else if fmt == "toml" {
                println!("{}", crate::config::to_toml_string(&cfg, only_defaults, no_defaults));
            } else {
                print!("{}", txt);
            }
            0
        }
    }
}

fn cmd_import(m: &clap::ArgMatches) -> i32 {
    let file = m.get_one::<String>("file").unwrap();
    let txt = match std::fs::read_to_string(file) {
        Ok(t) => t,
        Err(e) => {
            err_exit(&format!("Failed to read config file: {}", e), 2);
        }
    };
    let val = match crate::utils::parse_json_or_yaml(&txt) {
        Some(v) => v,
        None => {
            err_exit("Failed to parse config file", 2);
        }
    };
    let cfg = crate::config::markdownlint_to_config(&val, Path::new_stub(), ConfigSource::Project);
    let fmt = m.get_one::<String>("format").map(|s| s.as_str()).unwrap_or("toml");
    let out = crate::config::import_to_string(&cfg, fmt);
    if m.get_flag("dry-run") {
        print!("{}", out);
        return 0;
    }
    let output = m
        .get_one::<String>("output")
        .cloned()
        .unwrap_or_else(|| ".rumdl.toml".to_string());
    let _ = std::fs::write(&output, &out);
    println!(
        "Converted markdownlint config from '{}' to '{}'",
        file,
        crate::utils::rel_to_cwd(std::path::Path::new(&output))
    );
    println!("You can now use: rumdl check --config {} .", output);
    0
}

fn cmd_schema(m: &clap::ArgMatches) -> i32 {
    match m.subcommand() {
        Some(("print", _)) => {
            println!("{}", crate::schema::SCHEMA);
            0
        }
        Some(("generate", _)) => {
            let _ = std::fs::write("rumdl.schema.json", crate::schema::SCHEMA);
            println!("Schema written to rumdl.schema.json");
            0
        }
        Some(("check", _)) => {
            if let Ok(t) = std::fs::read_to_string("rumdl.schema.json") {
                if t == crate::schema::SCHEMA {
                    println!("Schema is up to date");
                    0
                } else {
                    eprintln!("Schema is out of date. Run `rumdl schema generate`");
                    1
                }
            } else {
                eprintln!("No schema file found. Run `rumdl schema generate`");
                1
            }
        }
        _ => 2,
    }
}

fn cmd_completions(m: &clap::ArgMatches) -> i32 {
    if m.get_flag("list") {
        println!("Available shells:");
        println!("  bash         Bourne Again SHell");
        println!("  zsh          Z shell");
        println!("  fish         Friendly Interactive SHell");
        println!("  powershell   PowerShell");
        println!("  elvish       Elvish shell");
        return 0;
    }
    let shell = match m.get_one::<String>("shell") {
        Some(s) => s.clone(),
        None => {
            let sh = std::env::var("SHELL").unwrap_or_default();
            let base = sh.rsplit('/').next().unwrap_or("").to_string();
            match base.as_str() {
                "bash" => "bash".to_string(),
                "zsh" => "zsh".to_string(),
                "fish" => "fish".to_string(),
                "powershell" | "pwsh" => "powershell".to_string(),
                "elvish" => "elvish".to_string(),
                _ => {
                    eprintln!("Could not detect shell. Please specify one of: bash, zsh, fish, powershell, elvish");
                    return 2;
                }
            }
        }
    };
    let cmd = build();
    let mut buf = Vec::new();
    let gen = clap_complete::Shell::from_str(&shell);
    match gen {
        Some(sh) => {
            clap_complete::generate(sh, &mut cmd.clone(), "rumdl", &mut buf);
            use std::io::Write;
            let _ = std::stdout().write_all(&buf);
            0
        }
        None => {
            eprintln!("Unknown shell");
            2
        }
    }
}

fn cmd_vscode(_m: &clap::ArgMatches) -> i32 {
    let editors = ["code", "cursor", "windsurf", "codium", "vscodium"];
    let mut found = None;
    for e in editors {
        if which(e) {
            found = Some(e);
            break;
        }
    }
    match found {
        Some(e) => {
            println!("Installing rumdl VS Code extension using {}...", e);
            0
        }
        None => {
            eprintln!("Error: VS Code (or compatible editor) not found. Please ensure one of the following commands is available: code, cursor, windsurf, codium, vscodium");
            2
        }
    }
}

fn which(cmd: &str) -> bool {
    if let Ok(path) = std::env::var("PATH") {
        for dir in path.split(':') {
            let p = std::path::Path::new(dir).join(cmd);
            if p.exists() {
                return true;
            }
        }
    }
    false
}

