fn rule_codes(list: &str) -> Vec<String> {
    list.split(',')
        .map(|s| s.trim().to_uppercase())
        .filter(|s| !s.is_empty())
        .collect()
}

fn enabled_rules(
    cfg: &Config,
    cli_enable: Option<&String>,
    cli_disable: Option<&String>,
    ext_enable: Option<&String>,
    ext_disable: Option<&String>,
) -> Vec<&'static crate::rules::R> {
    let mut codes: Vec<String> = Vec::new();
    if let Some(e) = cli_enable {
        codes = rule_codes(e);
    } else if !cfg.global.enable.is_empty() {
        codes = cfg.global.enable.iter().map(|s| s.to_uppercase()).collect();
    }
    if let Some(e) = ext_enable {
        for c in rule_codes(e) {
            if !codes.contains(&c) {
                codes.push(c);
            }
        }
    }
    let mut disabled: Vec<String> = cfg.global.disable.iter().map(|s| s.to_uppercase()).collect();
    if let Some(d) = cli_disable {
        for c in rule_codes(d) {
            if !disabled.contains(&c) {
                disabled.push(c);
            }
        }
    }
    if let Some(d) = ext_disable {
        for c in rule_codes(d) {
            if !disabled.contains(&c) {
                disabled.push(c);
            }
        }
    }
    crate::rules::ALL
        .iter()
        .filter(|r| {
            if codes.is_empty() {
                true
            } else {
                codes.iter().any(|c| c == r.code)
            }
        })
        .filter(|r| !disabled.iter().any(|c| c == r.code))
        .collect()
}

