                path: r.path.clone(),
                issues,
                fixed: r.fixed,
            });
        }
        let _ = &mut remaining;
        results = results;
    }
    // Determine the "fixed" set of issues to print (from the original lint)
    let print_fix_marker = fix;
    let mut out: Vec<String> = Vec::new();
    if output_format == "json" {
        let v = crate::output::to_json(&results);
        out.push(serde_json::to_string_pretty(&v).unwrap_or_default());
    } else if output_format == "json-lines" {
        out.push(crate::output::to_json_lines(&results));
    } else if output_format == "gitlab" {
        let v = crate::output::to_gitlab(&results);
        out.push(serde_json::to_string_pretty(&v).unwrap_or_default());
    } else if output_format == "sarif" {
        let v = crate::output::to_sarif(&results, &rules);
        out.push(serde_json::to_string_pretty(&v).unwrap_or_default());
    } else if output_format == "junit" {
        out.push(crate::output::to_junit(&results));
    } else {
        let mut lines = crate::output::text_lines(&results, colors, print_fix_marker);
        if output_format == "grouped" {
            lines = crate::output::grouped_lines(&results, print_fix_marker);
        } else if output_format == "github" {
            lines = crate::output::to_github(&results);
        } else if output_format == "azure" {
            lines = crate::output::to_azure(&results);
        } else if output_format == "pylint" {
            lines = crate::output::to_pylint(&results);
        }
        if !lines.is_empty() {
            out.extend(lines);
            out.push(String::new());
        }
        if !quiet {
            let sum = crate::output::summary_lines(&results, total_files, elapsed, fix, colors);
            out.extend(sum);
        }
        if m.get_flag("statistics") && !quiet {
            out.extend(crate::output::statistics(&results));
        }
    }
    if !silent {
        for l in &out {
            if m.get_flag("stderr") && looks_like_diagnostic(l) {
                eprintln!("{}", l);
            } else {
                println!("{}", l);
            }
        }
    }
    let remaining_issues: usize = results.iter().map(|r| r.issues.len()).sum();
    let exit = if fix {
        let unfixable: usize = results
            .iter()
            .flat_map(|r| r.issues.iter())
            .filter(|i| i.fix.is_none())
            .count();
        if unfixable > 0 {
            1
        } else {
            0
        }
    } else if remaining_issues > 0 {
        match m.get_one::<String>("fail-on").map(|s| s.as_str()).unwrap_or("any") {
            "never" => 0,
            "error" => {
                if results
                    .iter()
                    .flat_map(|r| r.issues.iter())
                    .any(|i| crate::rules::severity_of(i.code) == "error")
                {
                    1
                } else {
                    0
                }
            }
            "warning" => {
                if results
                    .iter()
                    .flat_map(|r| r.issues.iter())
                    .any(|i| crate::rules::severity_of(i.code) != "info")
                {
                    1
                } else {
                    0
                }
            }
            _ => 1,
        }
    } else {
        0
    };
    if fix_forced {
        return 0;
    }
    exit
}

fn looks_like_diagnostic(l: &str) -> bool {
    l.contains(": [MD") && !l.starts_with('I') && !l.starts_with('F') && !l.starts_with('R')
}

fn env_or(var: &str, default: String) -> String {
    std::env::var(var).unwrap_or(default)
}

pub fn lint_text(
    text: &str,
    cfg: &Config,
    rules: &[&'static crate::rules::R],
    rel: &str,
) -> Vec<Issue> {
    let flavor = cfg.global.flavor;
    let doc = crate::doc::Doc::new(text, flavor);
    let ctx = Ctx::new(PathBuf::from(rel), rel.to_string());
    let mut out: Vec<Issue> = Vec::new();
    for r in rules {
        if let Some(f) = crate::rules::dispatch(r.code) {
            let mut v = f(&doc, cfg, &ctx);
            // global fixable / unfixable
            for i in v.iter_mut() {
                if !cfg.global.fixable.is_empty()
                    && !cfg.global.fixable.iter().any(|c| c.eq_ignore_ascii_case(r.code))
                {
                    i.fix = None;
                }
                if cfg
                    .global
                    .unfixable
                    .iter()
                    .any(|c| c.eq_ignore_ascii_case(r.code))
                {
                    i.fix = None;
                }
            }
            out.append(&mut v);
        }
    }
    out
}

/// Apply fixes iteratively; returns (final text, applied count in first round, changed)
pub fn fix_text(
    text: &str,
    cfg: &Config,
    rules: &[&'static crate::rules::R],
    ctx: &Ctx,
) -> (String, usize, bool) {
    let mut current = text.to_string();
    let mut first_applied = 0usize;
    let mut rounds = 0usize;
    loop {
        let issues = lint_text(&current, cfg, rules, &ctx.rel_path);
        let fixes: Vec<Fix> = issues.iter().filter_map(|i| i.fix.clone()).collect();
        if fixes.is_empty() {
            break;
        }
        let (newtext, applied) = crate::fix::apply(&current, &fixes);
        if rounds == 0 {
            first_applied = applied;
        }
        if newtext == current {
            break;
        }
        current = newtext;
        rounds += 1;
        if rounds > 10 {
            break;
        }
    }
    (current, first_applied, current != text)
}

pub fn run() {
    let matches = build().get_matches();
    let code = match matches.subcommand() {
        Some(("check", m)) => run_check(m, false),
        Some(("fmt", m)) => run_check(m, true),
        Some(("version", _)) => {
            println!("rumdl {}", config::VERSION);
            0
        }
        Some(("clean", m)) => cmd_clean(m),
        Some(("init", m)) => cmd_init(m),
        Some(("rule", m)) => cmd_rule(m),
        Some(("explain", m)) => cmd_explain(m),
        Some(("config", m)) => cmd_config(m),
        Some(("import", m)) => cmd_import(m),
        Some(("schema", m)) => cmd_schema(m),
        Some(("completions", m)) => cmd_completions(m),
        Some(("vscode", m)) => cmd_vscode(m),
        Some(("server", m)) => crate::lsp::run(m),
        _ => 0,
    };
    std::process::exit(code);
}

fn cmd_clean(m: &clap::ArgMatches) -> i32 {
    let cfg = load_config(m);
    let dir = std::env::current_dir()
        .unwrap_or_else(|_| PathBuf::from("."))
        .join(env_or("RUMDL_CACHE_DIR", cfg.global.cache_dir.clone()));
    if dir.exists() {
        let mut total = 0usize;
        let mut count = 0usize;
        if let Ok(rd) = std::fs::read_dir(&dir) {
            for e in rd.filter_map(|e| e.ok()) {
                let p = e.path();
                if p.is_file() {
                    if p.file_name().map(|n| n == ".gitignore").unwrap_or(false) {
                        continue;
                    }
                    if let Ok(md) = e.metadata() {
                        total += md.len() as usize;
                        count += 1;
                    }
                    let _ = std::fs::remove_file(&p);
                } else if p.is_dir() {
                    if let Ok(rd2) = std::fs::read_dir(&p) {
                        for e2 in rd2.filter_map(|e| e.ok()) {
                            let p2 = e2.path();
                            if p2.is_file() {
                                if let Ok(md) = e2.metadata() {
                                    total += md.len() as usize;
                                    count += 1;
                                }
                                let _ = std::fs::remove_file(&p2);
                            }
                        }
                    }
                    let _ = std::fs::remove_dir(&p);
                }
            }
        }
        let bytes = format_bytes(total);
        println!("Cleared cache: {}", crate::utils::rel_to_cwd(&dir));
        println!("  Removed {} across {} files", bytes, count);
    } else {
        println!(
            "No cache found at {} (nothing to clean)",
            dir.to_string_lossy()
        );
    }
    0
}

fn format_bytes(b: usize) -> String {
    if b < 1024 {
        format!("{} B", b)
    } else if b < 1024 * 1024 {
        format!("{:.1} KB", b as f64 / 1024.0)
    } else {
        format!("{:.1} MB", b as f64 / (1024.0 * 1024.0))
    }
}

fn cmd_init(m: &clap::ArgMatches) -> i32 {
    let pyproject = m.get_flag("pyproject");
    if pyproject {
        let p = PathBuf::from("pyproject.toml");
        if p.exists() {
            err_exit(
                &format!(
                    "Failed to create config file: pyproject.toml already exists"
                ),
                2,
            );
        }
        let _ = std::fs::write(&p, crate::init_tpl::PYPROJECT);
        println!("Created pyproject.toml with rumdl configuration");
        return 0;
    }
    let p = PathBuf::from(".rumdl.toml");
    if p.exists() {
        err_exit(
            "Failed to create config file: Configuration file already exists at .rumdl.toml",
            2,
        );
    }
    let _ = std::fs::write(&p, crate::init_tpl::RUMDL_TOML);
    println!("Created default configuration file: .rumdl.toml");
    println!();
    println!("Setup complete! You can now:");
    println!("  \u{2022} Run rumdl check . to lint your Markdown files");
    println!("  \u{2022} Open your editor to see real-time linting");
    0
}

fn cmd_rule(m: &clap::ArgMatches) -> i32 {
    let colors = colors_for(m);
    let _ = colors;
    if m.get_flag("list-categories") {
        println!("Available categories:");
        for (c, n) in crate::rules::categories() {
            println!("  {} ({} rules)", c.name(), n);
        }
        return 0;
    }
    let fmt = m.get_one::<String>("output-format").map(|s| s.as_str()).unwrap_or("text");
    let filter_fixable = m.get_flag("fixable");
    let cat = m.get_one::<String>("category");
    if let Some(catname) = cat {
        let c = match crate::rules::Category::from(catname) {
            Some(c) => c,
            None => {
                eprintln!("Error: Unknown category '{}'", catname);
                return 2;
            }
        };
        if fmt == "text" {
            for r in crate::rules::ALL.iter().filter(|r| r.category == c) {
                if filter_fixable && r.fix != crate::rules::FixAvail::Always {
                    continue;
                }
                println!("{} - {}", r.code, r.summary);
            }
            return 0;
        }
    }
    let sel: Vec<&crate::rules::R> = crate::rules::ALL
        .iter()
        .filter(|r| {
            if filter_fixable && r.fix != crate::rules::FixAvail::Always {
                return false;
            }
            if let Some(c) = cat {
                if let Some(cc) = crate::rules::Category::from(c) {
                    return r.category == cc;
                }
            }
            true
        })
        .collect();
    match m.get_one::<String>("rule") {
        Some(name) => match crate::rules::find(name) {
            Some(r) => {
                if fmt == "json" {
                    let v = serde_json::json!({
                        "code": r.code,
                        "name": r.name,
                        "aliases": r.aliases,
                        "summary": r.summary,
                        "category": r.category.name(),
                        "fix": r.fix.desc(),
                        "fix_availability": crate::rules::fix_avail_name(r.fix),
                        "url": format!("https://rumdl.dev/{}/", r.code.to_lowercase()),
                    });
                    println!("{}", serde_json::to_string_pretty(&v).unwrap_or_default());
                } else {
                    println!("{} - {}", r.code, r.summary);
                    println!();
                    println!("Name: {}", r.name);
                    println!("Category: {}", r.category.name());
                    println!("Fix: {}", r.fix.desc());
                    println!("Documentation: https://rumdl.dev/{}/", r.code.to_lowercase());
                }
                0
            }
            None => {
                eprintln!("Error: Unknown rule '{}'", name);
                2
            }
        },
        None => {
            if fmt == "json" || fmt == "json-lines" {
                let items: Vec<serde_json::Value> = sel
                    .iter()
                    .map(|r| {
                        serde_json::json!({
                            "code": r.code,
                            "name": r.name,
                            "aliases": r.aliases,
                            "summary": r.summary,
                            "category": r.category.name(),
                            "fix": r.fix.desc(),
                            "fix_availability": crate::rules::fix_avail_name(r.fix),
                            "url": format!("https://rumdl.dev/{}/", r.code.to_lowercase()),
                        })
                    })
                    .collect();
                if fmt == "json" {
                    println!(
                        "{}",
                        serde_json::to_string_pretty(&serde_json::Value::Array(items))
                            .unwrap_or_default()
                    );
                } else {
                    for it in items {
                        println!(
                            "{}",
                            serde_json::to_string(&it).unwrap_or_default()
                        );
                    }
                }
                return 0;
            }
            println!("Available rules:");
            for r in &sel {
                println!("  {} - {}", r.code, r.summary);
            }
            println!();
            println!("Total: {} rules", sel.len());
            0
        }
    }
}

fn cmd_explain(m: &clap::ArgMatches) -> i32 {
