fn title_case_word(s: &str) -> String {
    let mut out = String::new();
    for part in s.split('-') {
        let mut cs = part.chars();
        if let Some(c) = cs.next() {
            out.extend(c.to_uppercase());
        }
        out.push_str(cs.as_str());
    }
    out
}

fn cmd_config(m: &clap::ArgMatches) -> i32 {
    let cfg = load_config(m);
    warn_config(&cfg);
    match m.subcommand() {
        Some(("get", sm)) => {
            let key = sm.get_one::<String>("key").cloned().unwrap_or_default();
            let parts: Vec<&str> = key.splitn(2, '.').collect();
            if parts.len() != 2 {
                eprintln!("Key must be in the form global.key or MDxxx.key");
                return 2;
            }
            let (sec, k) = (parts[0], crate::config::norm_key(parts[1]));
            if sec.eq_ignore_ascii_case("global") {
                let provided = crate::utils::global_provided(&cfg, &k);
                let v = match k.as_str() {
                    "enable" => crate::utils::fmt_str_list(&cfg.global.enable),
                    "disable" => crate::utils::fmt_str_list(&cfg.global.disable),
                    "exclude" => crate::utils::fmt_str_list(&cfg.global.exclude),
                    "include" => crate::utils::fmt_str_list(&cfg.global.include),
                    "respect-gitignore" => cfg.global.respect_gitignore.to_string(),
                    "line-length" => cfg.global.line_length.to_string(),
                    "fixable" => crate::utils::fmt_str_list(&cfg.global.fixable),
                    "unfixable" => crate::utils::fmt_str_list(&cfg.global.unfixable),
                    "flavor" => format!("\"{}\"", cfg.global.flavor.toml()),
                    "force-exclude" => cfg.global.force_exclude.to_string(),
                    "cache" => cfg.global.cache.to_string(),
                    "cache-dir" => format!("\"{}\"", cfg.global.cache_dir),
                    "output-format" => format!("\"{}\"", cfg.global.output_format),
                    _ => {
                        eprintln!("Unknown config key: {}", key);
                        return 2;
                    }
                };
                let src = if provided {
                    cfg.source.label()
                } else {
                    ConfigSource::Default.label()
                };
                println!("global.{} = {} [{}]", k, v, src);
                return 0;
            }
            let upper = sec.to_uppercase();
            if !crate::rules::ALL.iter().any(|r| r.code == upper) {
                eprintln!("Key must be in the form global.key or MDxxx.key");
                return 2;
            }
            let known = crate::config::known_keys(&upper);
            if !known.contains(&k.as_str()) {
                eprintln!("Unknown config key: {}", key);
                return 2;
            }
            let val = match cfg.get(&upper, &k) {
                Some(v) => {
                    if matches!(v, toml::Value::Table(_)) {
                        "<table>".to_string()
                    } else {
                        crate::utils::fmt_toml(v)
                    }
                }
                None => match crate::config::default_value(&upper, &k) {
                    Some(v) => crate::utils::fmt_toml(&v),
                    None => {
                        eprintln!("Unknown config key: {}", key);
                        return 2;
                    }
                },
            };
            let provided = crate::utils::rule_provided(&cfg, &upper, &k);
            let src = if provided {
                cfg.source.label()
            } else {
                ConfigSource::Default.label()
            };
            println!("{}.{} = {} [{}]", upper, k, val, src);
            0
        }
        Some(("file", _)) => match &cfg.path {
            Some(p) => {
                println!("{}", std::fs::canonicalize(p).unwrap_or_else(|_| p.clone()).to_string_lossy());
                0
            }
            None => {
                println!("No configuration file found (using defaults)");
                0
            }
        },
        _ => {
            let only_defaults = m.get_flag("defaults");
            let no_defaults = m.get_flag("no-defaults");
            let colors = colors_for(m);
            let txt = crate::output::config_text(&cfg, only_defaults, no_defaults, colors);
            if no_defaults && txt.trim().is_empty() {
                println!("All configurations are using default values.");
                return 0;
            }
            let fmt = m.get_one::<String>("output").map(|s| s.as_str()).unwrap_or("text");
            if fmt == "json" {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&crate::config::to_json_value(&cfg))
                        .unwrap_or_default()
                );
            } else if fmt == "toml" {
                println!("{}", crate::config::to_toml_string(&cfg, only_defaults, no_defaults));
            } else {
                print!("{}", txt);
            }
            0
        }
    }
}

fn cmd_import(m: &clap::ArgMatches) -> i32 {
    let file = m.get_one::<String>("file").unwrap();
    let txt = match std::fs::read_to_string(file) {
        Ok(t) => t,
        Err(e) => {
            err_exit(&format!("Failed to read config file: {}", e), 2);
        }
    };
    let val = match crate::utils::parse_json_or_yaml(&txt) {
        Some(v) => v,
        None => {
            err_exit("Failed to parse config file", 2);
        }
    };
    let cfg = crate::config::markdownlint_to_config(&val, Path::new_stub(), ConfigSource::Project);
    let fmt = m.get_one::<String>("format").map(|s| s.as_str()).unwrap_or("toml");
    let out = crate::config::import_to_string(&cfg, fmt);
    if m.get_flag("dry-run") {
        print!("{}", out);
        return 0;
    }
    let output = m
        .get_one::<String>("output")
        .cloned()
        .unwrap_or_else(|| ".rumdl.toml".to_string());
    let _ = std::fs::write(&output, &out);
    println!(
        "Converted markdownlint config from '{}' to '{}'",
        file,
        crate::utils::rel_to_cwd(std::path::Path::new(&output))
    );
    println!("You can now use: rumdl check --config {} .", output);
    0
}

