fn cmd_completions(m: &clap::ArgMatches) -> i32 {
    if m.get_flag("list") {
        println!("Available shells:");
        println!("  bash         Bourne Again SHell");
        println!("  zsh          Z shell");
        println!("  fish         Friendly Interactive SHell");
        println!("  powershell   PowerShell");
        println!("  elvish       Elvish shell");
        return 0;
    }
    let shell = match m.get_one::<String>("shell") {
        Some(s) => s.clone(),
        None => {
            let sh = std::env::var("SHELL").unwrap_or_default();
            let base = sh.rsplit('/').next().unwrap_or("").to_string();
            match base.as_str() {
                "bash" => "bash".to_string(),
                "zsh" => "zsh".to_string(),
                "fish" => "fish".to_string(),
                "powershell" | "pwsh" => "powershell".to_string(),
                "elvish" => "elvish".to_string(),
                _ => {
                    eprintln!("Could not detect shell. Please specify one of: bash, zsh, fish, powershell, elvish");
                    return 2;
                }
            }
        }
    };
    let cmd = build();
    let mut buf = Vec::new();
    let gen = clap_complete::Shell::from_str(&shell);
    match gen {
        Some(sh) => {
            clap_complete::generate(sh, &mut cmd.clone(), "rumdl", &mut buf);
            use std::io::Write;
            let _ = std::stdout().write_all(&buf);
            0
        }
        None => {
            eprintln!("Unknown shell");
            2
        }
    }
}

fn cmd_vscode(_m: &clap::ArgMatches) -> i32 {
