    let mut stdin = std::io::stdin();
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let mut initialized = false;
    let mut pending: Vec<serde_json::Value> = Vec::new();
    loop {
        let msg = match read_message(&mut stdin as &mut dyn Read) {
            Some(m) => m,
            None => break,
        };
        let v: serde_json::Value = match serde_json::from_str(&msg) {
            Ok(v) => v,
            Err(_) => {
                send(&mut out, &err(serde_json::json!(null), -32700, "Parse error"));
                continue;
            }
        };
        let method = v.get("method").and_then(|m| m.as_str()).unwrap_or("").to_string();
        let id = v.get("id").cloned().unwrap_or(serde_json::Value::Null);
        if method == "exit" {
            for p in pending.drain(..) {
                send(&mut out, &err(p, -32800, "Canceled"));
            }
            break;
        }
        if v.get("method").is_some() && v.get("id").is_none() {
            // notification
            if method == "initialized" {
                // send start log, register capabilities, index workspace
                send(&mut out, &serde_json::json!({
                    "jsonrpc":"2.0","method":"window/logMessage",
                    "params":{"type":3,"message":format!("rumdl v{} Language Server started", crate::config::VERSION)}
                }));
                send(&mut out, &serde_json::json!({
                    "jsonrpc":"2.0","method":"client/registerCapability",
                    "params":{"registrations":[{"id":"markdown-watcher","method":"workspace/didChangeWatchedFiles",
                      "registerOptions":{"watchers":[
                        {"globPattern":"**/*.md","kind":7},
                        {"globPattern":"**/*.markdown","kind":7},
                        {"globPattern":"**/*.mdx","kind":7},
                        {"globPattern":"**/*.mkd","kind":7},
                        {"globPattern":"**/*.mkdn","kind":7},
                        {"globPattern":"**/*.mdown","kind":7},
                        {"globPattern":"**/*.mdwn","kind":7},
                        {"globPattern":"**/*.qmd","kind":7},
                        {"globPattern":"**/*.rmd","kind":7}
                      ]}}]}
                }));
                // index progress
                send(&mut out, &serde_json::json!({
                    "jsonrpc":"2.0","method":"window/workDoneProgress/create",
                    "params":{"token":"rumdl-index"},"id":serde_json::json!(1)
                }));
                pending.push(serde_json::json!(1));
                let files = crate::lint::collect_files(&[String::from(".")], &[], &[], true, false).unwrap_or_default();
                send(&mut out, &serde_json::json!({
                    "jsonrpc":"2.0","method":"$/progress",
                    "params":{"token":"rumdl-index","value":{"kind":"begin","title":"Indexing workspace","cancellable":false,
                      "message":format!("Scanning {} markdown files...", files.len()),"percentage":0}}
                }));
                send(&mut out, &serde_json::json!({
                    "jsonrpc":"2.0","method":"$/progress",
                    "params":{"token":"rumdl-index","value":{"kind":"report","cancellable":false,
                      "message":format!("Indexed {}/{} files", files.len(), files.len()),"percentage":100}}
                }));
                send(&mut out, &serde_json::json!({
                    "jsonrpc":"2.0","method":"$/progress",
                    "params":{"token":"rumdl-index","value":{"kind":"end","message":"Indexing complete"}}
                }));
            }
            continue;
        }
        if !initialized && method != "initialize" {
            send(&mut out, &err(id, -32002, "Server not initialized"));
            continue;
        }
        match method.as_str() {
            "initialize" => {
                let params = v.get("params").cloned().unwrap_or(serde_json::Value::Null);
                if params.get("capabilities").is_none() {
                    let msg = match serde_json::from_str::<serde_json::Value>(
                        &serde_json::to_string(&params).unwrap_or_default(),
                    ) {
                        Ok(_) => "missing field `capabilities`".to_string(),
                        Err(e) => {
                            let s = e.to_string();
                            let s = s.split(" at line").next().unwrap_or(&s).to_string();
                            s
                        }
                    };
                    send(&mut out, &err(id, -32602, &msg));
                    continue;
                }
                send(&mut out, &serde_json::json!({
                    "jsonrpc":"2.0","result":{
                        "capabilities":{
                            "textDocumentSync":{"openClose":true,"change":1,"willSave":false,"willSaveWaitUntil":true,
                              "save":{"includeText":false}},
                            "completionProvider":{"resolveProvider":false,"triggerCharacters":["`"]},
                            "codeActionProvider":{"codeActionKinds":["quickfix","source.fixAll","source.fixAll.rumdl"]},
                            "documentFormattingProvider":true,
                            "documentRangeFormattingProvider":true,
                            "workspace":{"workspaceFolders":{"supported":true,"changeNotifications":true}},
                            "diagnosticProvider":{"identifier":"rumdl","interFileDependencies":true,"workspaceDiagnostics":false}
                        },
                        "serverInfo":{"name":"rumdl","version":crate::config::VERSION}
                    },"id":id
                }));
                initialized = true;
            }
            "textDocument/formatting" | "textDocument/rangeFormatting" => {
                let uri = v.pointer("/params/textDocument/uri").and_then(|u| u.as_str()).unwrap_or("");
                let text = crate::lsp::proto::text_of(uri);
                let flavor = crate::config::Flavor::Standard;
                let doc = crate::doc::Doc::new(&text, flavor);
                let cfg = crate::config::empty();
                let rules = crate::rules::ALL.to_vec();
                let ctx = crate::lint::Ctx::new(std::path::PathBuf::from(uri), String::new());
                let (newtext, _, _) = crate::cli::fix_text(&text, &cfg, &rules, &ctx);
                let lines = text.matches('\n').count() as u64 + 1;
                let newlines = newtext.matches('\n').count() as u64 + 1;
                let _ = &doc;
                send(&mut out, &serde_json::json!({
                    "jsonrpc":"2.0","result":[{"range":{"start":{"line":0,"character":0},
                      "end":{"line":lines,"character":0}},"newText":newtext}],"id":id
                }));
                let _ = newlines;
            }
            "textDocument/diagnostic" => {
                let uri = v.pointer("/params/textDocument/uri").and_then(|u| u.as_str()).unwrap_or("");
                let text = crate::lsp::proto::text_of(uri);
                let items = crate::lsp::proto::diagnose(&text, uri);
                send(&mut out, &serde_json::json!({
                    "jsonrpc":"2.0","result":{"kind":"full","items":items},"id":id
                }));
            }
            "textDocument/codeAction" => {
                send(&mut out, &err(id, -32602, "missing field `range`"));
            }
            "textDocument/completion" => {
                send(&mut out, &serde_json::json!({"jsonrpc":"2.0","result":null,"id":id}));
            }
            "workspace/executeCommand" => {
                send(&mut out, &serde_json::json!({"jsonrpc":"2.0","result":null,"id":id}));
            }
            "shutdown" => {
                let params = v.get("params").cloned().unwrap_or(serde_json::Value::Null);
                if !params.is_null() {
                    send(&mut out, &err(id, -32602, &format!("Unexpected params: {}", serde_json::to_string(&params).unwrap_or_default())));
                } else {
                    send(&mut out, &serde_json::json!({"jsonrpc":"2.0","result":null,"id":id}));
                }
            }
            _ => {
                send(&mut out, &err(id, -32601, "Method not found"));
            }
        }
    }
    0
}

pub fn diagnose(text: &str, uri: &str) -> serde_json::Value {
    let cfg = crate::config::empty();
    let rules = crate::rules::ALL.to_vec();
    let mut issues = crate::cli::lint_text(text, &cfg, &rules, uri);
    crate::lint::sort_issues(&mut issues);
    let mut items = Vec::new();
    for i in issues {
        let sev = match crate::rules::severity_of(i.code) {
            "error" => 1,
            "warning" => 2,
            _ => 3,
        };
        items.push(serde_json::json!({
            "range":{"start":{"line":(i.line-1) as u64,"character":(i.column-1) as u64},
                     "end":{"line":(i.line-1) as u64,"character":(i.column-1) as u64}},
            "severity": sev,
            "code": i.code,
            "codeDescription": {"href": format!("https://rumdl.dev/{}/", i.code.to_lowercase())},
            "source": "rumdl",
            "message": i.message
        }));
    }
    serde_json::Value::Array(items)
}

thread_local! {
    static OPEN_DOCS: std::cell::RefCell<Vec<(String, String)>> = std::cell::RefCell::new(Vec::new());
}

pub fn text_of(uri: &str) -> String {
    OPEN_DOCS.with(|d| {
        d.borrow()
            .iter()
            .find(|(u, _)| u == uri)
            .map(|(_, t)| t.clone())
            .unwrap_or_else(|| std::fs::read_to_string(uri.trim_start_matches("file://")).unwrap_or_default())
    })
}

pub fn open_doc(uri: &str, text: &str) {
    OPEN_DOCS.with(|d| {
        let mut b = d.borrow_mut();
        if let Some(e) = b.iter_mut().find(|(u, _)| u == uri) {
            e.1 = text.to_string();
        } else {
            b.push((uri.to_string(), text.to_string()));
        }
    });
}
