/// JSON representation used by `config --output json`
pub fn to_json_value(cfg: &Config) -> serde_json::Value {
    let g = &cfg.global;
    let mut json = serde_json::json!({
        "global": {
            "enable": g.enable,
            "disable": g.disable,
            "exclude": g.exclude,
            "include": g.include,
            "respect-gitignore": g.respect_gitignore,
            "line-length": g.line_length as i64,
            "fixable": g.fixable,
            "unfixable": g.unfixable,
            "flavor": g.flavor.toml(),
            "force-exclude": g.force_exclude,
            "cache": g.cache
        },
        "per-file-ignores": {},
        "per-file-flavor": {},
        "code-block-tools": {
            "enabled": false,
            "normalize-language": "linguist",
            "on-error": "fail",
            "on-missing-language-definition": "ignore",
            "on-missing-tool-binary": "ignore",
            "timeout": 30000,
            "languages": {},
            "language-aliases": {},
            "tools": {}
        }
    });
    let obj = json.as_object_mut().unwrap();
    let mut pfi = serde_json::Map::new();
    for (k, v) in &g.per_file_ignores {
        pfi.insert(k.clone(), serde_json::json!(v));
