fn read_message(reader: &mut dyn Read) -> Option<String> {
    let mut header = Vec::new();
    let mut buf = [0u8; 1];
    loop {
        match reader.read(&mut buf) {
            Ok(0) => return None,
            Ok(_) => {
                header.push(buf[0]);
                if header.ends_with(b"\r\n\r\n") {
