                }
                if header.len() > 8192 {
                    return None;
                }
            }
            Err(_) => return None,
        }
    }
    let s = String::from_utf8_lossy(&header).to_string();
    let mut len = None;
    for line in s.split("\r\n") {
        let line = line.trim();
        if let Some(v) = line.strip_prefix("Content-Length:") {
