use std::io::{Read, Write};

pub fn serve() -> i32 {
    serve_stdio()
}

fn read_message(reader: &mut dyn Read) -> Option<String> {
    let mut header = Vec::new();
    let mut buf = [0u8; 1];
    loop {
        match reader.read(&mut buf) {
            Ok(0) => return None,
            Ok(_) => {
                header.push(buf[0]);
                if header.ends_with(b"\r\n\r\n") {
                    break;
                }
                if header.len() > 8192 {
                    return None;
                }
            }
            Err(_) => return None,
        }
    }
    let s = String::from_utf8_lossy(&header).to_string();
    let mut len = None;
    for line in s.split("\r\n") {
        let line = line.trim();
        if let Some(v) = line.strip_prefix("Content-Length:") {
            len = v.trim().parse::<usize>().ok();
        }
    }
    let len = len?;
    let mut body = vec![0u8; len];
    let mut got = 0;
    while got < len {
        match reader.read(&mut body[got..]) {
            Ok(0) => return None,
            Ok(n) => got += n,
            Err(_) => return None,
        }
    }
    Some(String::from_utf8_lossy(&body).to_string())
}

fn send(out: &mut dyn Write, v: &serde_json::Value) {
    let body = serde_json::to_string(v).unwrap_or_default();
    let _ = write!(out, "Content-Length: {}\r\n\r\n{}", body.len(), body);
    let _ = out.flush();
}

fn err(id: serde_json::Value, code: i64, msg: &str) -> serde_json::Value {
    serde_json::json!({"jsonrpc":"2.0","error":{"code":code,"message":msg},"id":id})
}

thread_local! {
    static OPEN_DOCS: std::cell::RefCell<Vec<(String, String)>> = std::cell::RefCell::new(Vec::new());
}

pub fn text_of(uri: &str) -> String {
    OPEN_DOCS.with(|d| {
        d.borrow()
            .iter()
            .find(|(u, _)| u == uri)
            .map(|(_, t)| t.clone())
            .unwrap_or_else(|| {
                std::fs::read_to_string(uri.trim_start_matches("file://")).unwrap_or_default()
            })
    })
}

pub fn open_doc(uri: &str, text: &str) {
    OPEN_DOCS.with(|d| {
        let mut b = d.borrow_mut();
        if let Some(e) = b.iter_mut().find(|(u, _)| u == uri) {
            e.1 = text.to_string();
        } else {
            b.push((uri.to_string(), text.to_string()));
        }
    });
}

