    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let l = doc.line_trimmed(i);
        let h = match doc.parse_heading(i) {
            Some(h) => h,
            None => continue,
        };
        if h.spaces_start <= 1 {
            continue;
        }
        let hashes = &l[..h.level];
        let msg = format!("Multiple spaces ({}) after {} in heading", h.spaces_start, hashes);
        let s = doc.char_to_byte(i, h.level + 1);
        let e = doc.char_to_byte(i, h.content_start_char);
        out.push(Issue::new("MD019", i + 1, h.level + 1, msg).with_fix(Fix::new(s, e, " ")));
    }
    out
}

pub fn heading_replacement(doc: &Doc, i: usize, h: &crate::doc::Heading) -> String {
    let hashes = "#".repeat(h.level);
    let text = h.text.clone();
    if h.closed {
        format!("{} {} {}", hashes, text, hashes)
    } else {
        format!("{} {}", hashes, text)
    }
}

pub fn md020(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let h = match doc.parse_heading(i) {
            Some(h) => h,
            None => continue,
        };
        if !h.closed {
            continue;
        }
        let l = doc.line_trimmed(i);
        let hashes = &l[..h.level];
        if h.spaces_start == 0 {
            let msg = "Missing space after # at start of closed heading".to_string();
            let rep = heading_replacement(doc, i, &h);
            out.push(
                Issue::new("MD020", i + 1, h.level + 1, msg).with_fix(Fix::new(
                    doc.start(i),
                    doc.start(i) + l.len(),
                    &rep,
                )),
            );
            continue;
        }
        // end: need a space before closing hashes
        let e = h.content_end_char;
        if e > 0 {
            let prev = l.as_bytes()[e - 1];
            if prev != b' ' {
                let run = &l[e..];
                let msg = format!("Missing space before {} at end of closed heading", run);
                let rep = heading_replacement(doc, i, &h);
                out.push(
                    Issue::new("MD020", i + 1, e, msg).with_fix(Fix::new(
                        doc.start(i),
                        doc.start(i) + l.len(),
                        &rep,
                    )),
                );
            }
        }
    }
    out
}

pub fn md021(doc: &Doc, _cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let skip = doc.non_text_lines();
    for i in 0..doc.nlines() {
        if skip[i] {
            continue;
        }
        let h = match doc.parse_heading(i) {
            Some(h) => h,
            None => continue,
        };
        if !h.closed {
            continue;
        }
        if h.spaces_start == 0 || h.spaces_end == 0 {
            continue;
        }
        if h.spaces_start <= 1 && h.spaces_end <= 1 {
            continue;
        }
        let l = doc.line_trimmed(i);
        let hashes = &l[..h.level];
        let close_hashes = &l[h.content_end_char..];
        let msg = if h.spaces_start > 1 && h.spaces_end > 1 {
            format!(
                "Multiple spaces ({} at start, {} at end) inside hashes on closed heading (with {} at start and end)",
                h.spaces_start, h.spaces_end, hashes
            )
        } else if h.spaces_start > 1 {
            format!(
                "Multiple spaces ({}) after {} at start of closed heading",
                h.spaces_start, hashes
            )
        } else {
            format!(
                "Multiple spaces ({}) before {} at end of closed heading",
                h.spaces_end, close_hashes
            )
        };
        let rep = heading_replacement(doc, i, &h);
        out.push(
            Issue::new("MD021", i + 1, 1, msg).with_fix(Fix::new(
                doc.start(i),
                doc.start(i) + l.len(),
                &rep,
            )),
        );
    }
    out
}

