    /// Looser heading parse: accepts `#`+text without a space after the hashes.
    pub fn parse_heading_loose(&self, i: usize) -> Option<Heading> {
        let l = self.line_trimmed(i);
        let bytes = l.as_bytes();
        if bytes.is_empty() || bytes[0] != b'#' {
            return None;
        }
        let mut k = 0usize;
        while k < bytes.len() && bytes[k] == b'#' {
            k += 1;
        }
        if k > 6 {
            k = 6;
        }
