                content_start_char: k,
                content_end_char: k,
                text: String::new(),
                closed: false,
                hashes_start: 0,
                raw_indent: 0,
                spaces_start: 0,
                spaces_end: 0,
            });
        }
        let mut c = k;
        while c < bytes.len() && bytes[c] == b' ' {
            c += 1;
        }
        let content_start_char = c;
        let content_str = &l[c..];
        let mut closed = false;
        let mut end_hashes_start = content_start_char + content_str.len();
        let mut spaces_end = 0usize;
        if !content_str.is_empty() && content_str.as_bytes()[content_str.len() - 1] == b'#' {
            let mut e = content_str.len();
            while e > 0 && content_str.as_bytes()[e - 1] == b'#' {
