            let core = &content_str[..last_ns];
            if e > 0 && !core.is_empty() && (c - k > 0 || spaces_end > 0 || core.contains(' ')) {
                closed = true;
                end_hashes_start = c + e;
            }
        }
        let text = if closed {
            content_str[..content_str.len() - (end_hashes_start - c)]
                .trim_end()
                .to_string()
        } else {
            content_str.to_string()
        };
        Some(Heading {
            line: i,
            level: k,
            content_start_char: c,
            content_end_char: end_hashes_start,
            text,
            closed,
            hashes_start: 0,
            raw_indent: l.len() - l.trim_start().len(),
            spaces_start: c - k,
            spaces_end,
        })
    }

    pub fn headings_loose(&self) -> Vec<Heading> {
        let skip = self.non_text_lines();
        let mut out = Vec::new();
        for i in 0..self.nlines() {
            if skip[i] {
                continue;
            }
            if let Some(h) = self.parse_heading_loose(i) {
                out.push(h);
            }
        }
        out
    }
}
