#[derive(Clone, Debug)]
pub struct AnyHeading {
    pub line: usize,
    pub level: usize,
    pub text: String,
    pub content_start_char: usize,
    pub content_end_char: usize,
    pub spaces_end: usize,
    pub spaces_start: usize,
    pub setext: bool,
    pub end_line: usize,
}

impl Doc {
    /// All headings including setext-style ones.
    pub fn headings_all(&self) -> Vec<AnyHeading> {
        let skip = self.non_text_lines();
        let mut out: Vec<AnyHeading> = Vec::new();
        let mut i = 0usize;
        while i < self.nlines() {
            if skip[i] {
                i += 1;
                continue;
            }
            if let Some(h) = self.parse_heading(i) {
                out.push(AnyHeading {
                    line: i,
                    level: h.level,
                    text: h.text.clone(),
                    content_start_char: h.content_start_char,
                    content_end_char: h.content_end_char,
                    spaces_end: h.spaces_end,
                    spaces_start: h.spaces_start,
                    setext: false,
                    end_line: i,
                });
                i += 1;
                continue;
            }
            if let Some((l, ch)) = self.setext_heading(i) {
                let text = self.line_trimmed(l).to_string();
                out.push(AnyHeading {
                    line: l,
                    level: 1,
                    text,
                    content_start_char: 0,
                    content_end_char: 0,
                    spaces_end: 0,
                    spaces_start: 0,
                    setext: true,
                    end_line: i,
                });
                i += 1;
                let _ = ch;
                continue;
            }
            i += 1;
        }
        out
    }
}
