new = '''pub fn fenced_blocks(doc: &Doc) -> Vec<Fence> {
    let mut out = Vec::new();
    let n = doc.nlines();
    let mut i = 0usize;
    while i < n {
        let l = doc.line_trimmed(i);
        let ind = l.len() - l.trim_start().len();
        let t = &l[ind..];
        if let Some((ch, len)) = crate::doc::fence_open(t) {
            let lang = t[len..].trim().to_string();
            let mut j = i + 1;
            let mut close = None;
            while j < n {
                let l2 = doc.line_trimmed(j);
                let ind2 = l2.len() - l2.trim_start().len();
                let t2 = &l2[ind2..];
                if crate::doc::is_fence_close(t2, ch, len) {
                    close = Some(j);
                    break;
                }
                j += 1;
            }
            match close {
                Some(cl) => {
                    out.push(Fence {
                        open_line: i,
                        close_line: cl,
                        fence_char: ch,
                        len,
                        lang,
                        indent: ind,
                    });
                    i = cl + 1;
                }
                None => {
                    out.push(Fence {
                        open_line: i,
                        close_line: usize::MAX,
                        fence_char: ch,
                        len,
                        lang,
                        indent: ind,
                    });
                    i = n;
                }
            }
        } else {
            i += 1;
        }
    }
    out
}

