new = '''pub fn md055(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let style = cfg.string("MD055", "style", "consistent");
    for t in tables(doc) {
        let mut styles: Vec<&str> = Vec::new();
        for (line, _, _, _, _) in &t.rows {
            let l = doc.line_trimmed(*line);
            let lead = l.starts_with('|');
            let trail = l.trim_end().ends_with('|');
            styles.push(match (lead, trail) {
                (true, true) => "both",
                (false, false) => "none",
                (true, false) => "leading",
                (false, true) => "trailing",
            });
        }
        let desc = |s: &str| -> &'static str {
            match s {
                "both" => "leading and trailing",
                "none" => "no leading or trailing",
                "leading" => "leading only",
                _ => "trailing only",
            }
        };
        let expected: &str = if style == "consistent" {
            let mut counts: Vec<(&str, usize)> = Vec::new();
            for s in &styles {
                match counts.iter_mut().find(|(k, _)| k == s) {
                    Some((_, c)) => *c += 1,
                    None => counts.push((s, 1)),
                }
            }
            let maxc = counts.iter().map(|(_, c)| *c).max().unwrap_or(0);
            counts
                .into_iter()
                .find(|(_, c)| *c == maxc)
                .map(|(k, _)| k)
                .unwrap_or("both")
        } else {
            match style.as_str() {
                "leading_trailing" => "both",
                "no_leading_or_trailing" => "none",
                "leading_only" => "leading",
                "trailing_only" => "trailing",
                _ => "both",
            }
        };
        for (idx, (line, _, _, _, _)) in t.rows.iter().enumerate() {
            if styles[idx] != expected {
                let msg = format!("Table pipe style should be {}", desc(expected));
                let l = doc.line_trimmed(*line);
                let s = doc.start(*line);
                let mut fixes: Vec<Fix> = Vec::new();
                if expected == "both" {
                    if !l.starts_with('|') {
                        fixes.push(Fix::new(s, s, "|"));
                    }
                    if !l.trim_end().ends_with('|') {
                        fixes.push(Fix::new(s + l.len(), s + l.len(), "|"));
                    }
                } else if expected == "none" {
                    if l.starts_with('|') {
                        fixes.push(Fix::new(s, s + 1, ""));
                    }
                    if l.trim_end().ends_with('|') {
                        fixes.push(Fix::new(s + l.len() - 1, s + l.len(), ""));
                    }
                } else if expected == "leading" {
                    if !l.starts_with('|') {
                        fixes.push(Fix::new(s, s, "|"));
                    }
                    if l.trim_end().ends_with('|') {
                        fixes.push(Fix::new(s + l.len() - 1, s + l.len(), ""));
                    }
                } else {
                    if l.starts_with('|') {
                        fixes.push(Fix::new(s, s + 1, ""));
                    }
                    if !l.trim_end().ends_with('|') {
                        fixes.push(Fix::new(s + l.len(), s + l.len(), "|"));
                    }
                }
                out.push(Issue::new("MD055", line + 1, 1, msg).with_fixes(fixes));
            }
        }
    }
    out
}

