                let s = doc.char_to_byte(it.line, 0);
                let e = doc.char_to_byte(it.line, it.indent);
                let rep = if spaces_needed > it.indent {
                    " ".repeat(spaces_needed)
                } else {
                    String::new()
                };
                out.push(
                    Issue::new("MD005", it.line + 1, 1, msg).with_fix(Fix::new(s, e, &rep)),
