#[derive(Clone, Debug)]
pub struct Heading {
    pub line: usize,
    pub level: usize,
    pub content_start_char: usize,
    pub content_end_char: usize,
    pub text: String,
    pub closed: bool,
    pub raw_indent: usize,
    pub spaces_start: usize,
    pub spaces_end: usize,
}

impl Heading {
    pub fn content_col(&self) -> usize {
        self.content_start_char + 1
    }
}

#[derive(Clone, Debug)]
pub struct AnyHeading {
    pub line: usize,
    pub level: usize,
    pub text: String,
    pub content_start_char: usize,
    pub content_end_char: usize,
    pub spaces_end: usize,
    pub spaces_start: usize,
    pub setext: bool,
    pub end_line: usize,
}

impl Doc {
    /// All headings including setext-style ones.
    pub fn headings_all(&self) -> Vec<AnyHeading> {
        let skip = self.non_text_lines();
        let mut out: Vec<AnyHeading> = Vec::new();
        let mut i = 0usize;
        while i < self.nlines() {
            if skip[i] {
                i += 1;
                continue;
            }
            if let Some(h) = self.parse_heading(i) {
                out.push(AnyHeading {
                    line: i,
                    level: h.level,
                    text: h.text.clone(),
                    content_start_char: h.content_start_char,
                    content_end_char: h.content_end_char,
                    spaces_end: h.spaces_end,
                    spaces_start: h.spaces_start,
                    setext: false,
                    end_line: i,
                });
                i += 1;
                continue;
            }
            if let Some((l, ch)) = self.setext_heading(i) {
                if ch != b'=' {
                    i += 1;
                    continue;
                }
                let text = self.line_trimmed(l).to_string();
                out.push(AnyHeading {
                    line: l,
                    level: 1,
                    text,
                    content_start_char: 0,
                    content_end_char: 0,
                    spaces_end: 0,
                    spaces_start: 0,
                    setext: true,
                    end_line: i,
                });
                i += 1;
                continue;
            }
            i += 1;
        }
        out
    }
}

pub fn fence_open(l: &str) -> Option<(u8, usize)> {
    let b = l.as_bytes();
    if b.is_empty() {
        return None;
    }
    let ch = b[0];
    if ch != b'`' && ch != b'~' {
        return None;
    }
    let mut n = 0;
    while n < b.len() && b[n] == ch {
        n += 1;
    }
    if n < 3 {
        return None;
    }
    if l[n..].contains(ch as char) {
        return None;
    }
    Some((ch, n))
}

pub fn is_fence_close(l: &str, ch: u8, len: usize) -> bool {
    let b = l.as_bytes();
    if b.len() < len {
        return false;
    }
    for i in 0..len {
        if b[i] != ch {
            return false;
        }
    }
    b[len..].iter().all(|&c| c == b' ' || c == b'\t')
}
