pub fn fence_open(l: &str) -> Option<(u8, usize)> {
    let b = l.as_bytes();
    if b.is_empty() {
        return None;
    }
    let ch = b[0];
    if ch != b'`' && ch != b'~' {
        return None;
    }
    let mut n = 0;
    while n < b.len() && b[n] == ch {
        n += 1;
    }
    if n < 3 {
        return None;
    }
    if l[n..].contains(ch as char) {
        return None;
    }
    Some((ch, n))
}

pub fn is_fence_close(l: &str, ch: u8, len: usize) -> bool {
    let b = l.as_bytes();
    if b.len() < len {
        return false;
    }
    for i in 0..len {
        if b[i] != ch {
            return false;
        }
    }
    b[len..].iter().all(|&c| c == b' ' || c == b'\t')
}
