new = '''pub fn to_toml_string(cfg: &Config, only_defaults: bool, no_defaults: bool) -> String {
    use toml::Value;
    let mut root = toml::map::Map::new();
    let g = &cfg.global;
    let mut gt = toml::map::Map::new();
    let ins = |m: &mut toml::map::Map, k: &str, v: Value| {
        m.insert(k.to_string(), v);
    };
    ins(&mut gt, "enable", Value::Array(g.enable.iter().map(|s| Value::String(s.clone())).collect()));
    ins(&mut gt, "disable", Value::Array(g.disable.iter().map(|s| Value::String(s.clone())).collect()));
    ins(&mut gt, "exclude", Value::Array(g.exclude.iter().map(|s| Value::String(s.clone())).collect()));
    ins(&mut gt, "include", Value::Array(g.include.iter().map(|s| Value::String(s.clone())).collect()));
    ins(&mut gt, "respect-gitignore", Value::Boolean(g.respect_gitignore));
    ins(&mut gt, "line-length", Value::Integer(g.line_length));
    ins(&mut gt, "fixable", Value::Array(g.fixable.iter().map(|s| Value::String(s.clone())).collect()));
    ins(&mut gt, "unfixable", Value::Array(g.unfixable.iter().map(|s| Value::String(s.clone())).collect()));
    ins(&mut gt, "flavor", Value::String(g.flavor.toml().to_string()));
    ins(&mut gt, "force-exclude", Value::Boolean(g.force_exclude));
    ins(&mut gt, "cache", Value::Boolean(g.cache));
    ins(&mut root, "global", Value::Table(gt));

    let mut pfi = toml::map::Map::new();
    for (k, v) in &g.per_file_ignores {
        ins(&mut pfi, k, Value::Array(v.iter().map(|s| Value::String(s.clone())).collect()));
    }
    ins(&mut root, "per-file-ignores", Value::Table(pfi));
    let mut pff = toml::map::Map::new();
    for (k, v) in &g.per_file_flavor {
        ins(&mut pff, k, Value::String(v.toml().to_string()));
    }
    ins(&mut root, "per-file-flavor", Value::Table(pff));
    let mut cbt = toml::map::Map::new();
    ins(&mut cbt, "enabled", Value::Boolean(false));
    ins(&mut cbt, "normalize-language", Value::String("linguist".into()));
    ins(&mut cbt, "on-error", Value::String("fail".into()));
    ins(&mut cbt, "on-missing-language-definition", Value::String("ignore".into()));
    ins(&mut cbt, "on-missing-tool-binary", Value::String("ignore".into()));
    ins(&mut cbt, "timeout", Value::Integer(30000));
    ins(&mut cbt, "languages", Value::Table(toml::map::Map::new()));
    ins(&mut cbt, "language-aliases", Value::Table(toml::map::Map::new()));
    ins(&mut cbt, "tools", Value::Table(toml::map::Map::new()));
    ins(&mut root, "code-block-tools", Value::Table(cbt));

    for r in crate::rules::ALL {
        let keys = crate::config::known_keys_sorted(r.code);
        if keys.is_empty() {
            if no_defaults {
                if let Some(m) = cfg.rules.get(r.code) {
                    if !m.is_empty() {
                        let mut t = toml::map::Map::new();
                        for (k, v) in m {
                            t.insert(k.clone(), v.clone());
                        }
                        ins(&mut root, r.code, Value::Table(t));
                    }
                }
            }
            continue;
        }
        let provided: Vec<&str> = keys
            .iter()
            .filter(|k| crate::utils::rule_provided(cfg, r.code, k))
            .copied()
            .collect();
        let use_keys: Vec<&str> = if only_defaults {
            keys.clone()
        } else if no_defaults {
            provided.clone()
        } else if provided.is_empty() {
            keys.clone()
        } else {
            provided.clone()
        };
        if use_keys.is_empty() {
            continue;
        }
        let mut t = toml::map::Map::new();
        for k in &use_keys {
            if let Some(v) = cfg.get(r.code, k) {
                t.insert(k.to_string(), v.clone());
            } else if let Some(v) = crate::config::default_value(r.code, k) {
                t.insert(k.to_string(), v);
            }
        }
        ins(&mut root, r.code, Value::Table(t));
    }
    toml::to_string(&Value::Table(root)).unwrap_or_default()
}

