```
prohibited-texts = [
    "click here",
    ...
]
```
✓ (that's the toml crate's style).

Let me implement:
```rust
pub fn to_toml_string(cfg, only_defaults, no_defaults) -> String {
    let mut root = toml::map::Map::new();
    // global
    let mut g = toml::map::Map::new();
    g.insert("enable", ...); ... (in the canonical order)
    root.insert("global", Value::Table(g));
    // per-file-ignores, per-file-flavor, code-block-tools
    // rules: for each rule with entries
    toml::to_string(&Value::Table(root)).unwrap_or_default()
}
```
