s=s.replace('''pub fn import_to_string(''','''pub fn toml_value(cfg: &Config, only_defaults: bool, no_defaults: bool) -> Option<toml::Value> {
    use toml::Value;
    let mut root = toml::map::Map::new();
    let g = &cfg.global;
    let mut gt = toml::map::Map::new();
    gt.insert("enable".into(), Value::Array(g.enable.iter().map(|s| Value::String(s.clone())).collect()));
    gt.insert("disable".into(), Value::Array(g.disable.iter().map(|s| Value::String(s.clone())).collect()));
    gt.insert("exclude".into(), Value::Array(g.exclude.iter().map(|s| Value::String(s.clone())).collect()));
    gt.insert("include".into(), Value::Array(g.include.iter().map(|s| Value::String(s.clone())).collect()));
    gt.insert("respect-gitignore".into(), Value::Boolean(g.respect_gitignore));
    gt.insert("line-length".into(), Value::Integer(g.line_length));
    gt.insert("fixable".into(), Value::Array(g.fixable.iter().map(|s| Value::String(s.clone())).collect()));
    gt.insert("unfixable".into(), Value::Array(g.unfixable.iter().map(|s| Value::String(s.clone())).collect()));
    gt.insert("flavor".into(), Value::String(g.flavor.toml().to_string()));
    gt.insert("force-exclude".into(), Value::Boolean(g.force_exclude));
    gt.insert("cache".into(), Value::Boolean(g.cache));
    root.insert("global".into(), Value::Table(gt));
    let mut pfi = toml::map::Map::new();
    for (k, v) in &g.per_file_ignores {
        pfi.insert(k.clone(), Value::Array(v.iter().map(|s| Value::String(s.clone())).collect()));
    }
    root.insert("per-file-ignores".into(), Value::Table(pfi));
    let mut pff = toml::map::Map::new();
    for (k, v) in &g.per_file_flavor {
        pff.insert(k.clone(), Value::String(v.toml().to_string()));
    }
    root.insert("per-file-flavor".into(), Value::Table(pff));
    let mut cbt = toml::map::Map::new();
    cbt.insert("enabled".into(), Value::Boolean(false));
    cbt.insert("normalize-language".into(), Value::String("linguist".into()));
    cbt.insert("on-error".into(), Value::String("fail".into()));
    cbt.insert("on-missing-language-definition".into(), Value::String("ignore".into()));
    cbt.insert("on-missing-tool-binary".into(), Value::String("ignore".into()));
    cbt.insert("timeout".into(), Value::Integer(30000));
    cbt.insert("languages".into(), Value::Table(toml::map::Map::new()));
    cbt.insert("language-aliases".into(), Value::Table(toml::map::Map::new()));
    cbt.insert("tools".into(), Value::Table(toml::map::Map::new()));
    root.insert("code-block-tools".into(), Value::Table(cbt));
    for r in crate::rules::ALL {
        let keys = crate::config::known_keys_sorted(r.code);
        let provided: Vec<&str> = keys
            .iter()
            .filter(|k| crate::utils::rule_provided(cfg, r.code, k))
            .copied()
            .collect();
        let raw: Vec<String> = crate::config::Config::provided_keys_of(cfg, r.code);
        let use_keys: Vec<String> = if only_defaults {
            keys.iter().map(|s| s.to_string()).collect()
        } else if no_defaults {
            raw.clone()
        } else if provided.is_empty() {
            raw.clone()
        } else {
            provided.iter().map(|s| s.to_string()).collect()
        };
        if use_keys.is_empty() {
            continue;
        }
        let mut t = toml::map::Map::new();
        for k in &use_keys {
            if let Some(v) = cfg.get(r.code, k) {
                t.insert(k.clone(), v.clone());
            } else if let Some(v) = crate::config::default_value(r.code, k) {
                t.insert(k.clone(), v);
            }
        }
        if t.is_empty() {
            continue;
        }
        root.insert(r.code.to_string(), Value::Table(t));
    }
    Some(Value::Table(root))
}

