        if it.ordered {
            continue;
        }
        while stack.len() > 0 && it.indent <= stack.last().unwrap().0 {
            stack.pop();
        }
        let depth = stack.len();
        let expected = if depth == 0 {
            if start_indented {
                start_indent
            } else {
                0
            }
