new = '''pub fn md029(doc: &Doc, cfg: &Config, _ctx: &Ctx) -> Vec<Issue> {
    let mut out = Vec::new();
    let _style = cfg.string("MD029", "style", "one-or-ordered");
    let items = list_items(doc);
    let mut lists: Vec<(Vec<usize>, bool)> = Vec::new(); // (indices, nested-under-ul)
    let mut cur: Vec<usize> = Vec::new();
    let mut cur_nested = false;
    let mut prev_indent = usize::MAX;
    let mut prev_line = usize::MAX;
    let mut stack: Vec<(usize, bool)> = Vec::new();
    for (idx, it) in items.iter().enumerate() {
        while stack.len() > 0 && it.indent <= stack.last().unwrap().0 {
            stack.pop();
        }
        let nested_here = stack.len() > 0 && !stack.last().unwrap().1;
        if cur.is_empty() {
            cur_nested = nested_here;
        }
        if !cur.is_empty()
            && (it.indent != prev_indent
                || (prev_line != usize::MAX && it.line != prev_line + 1))
        {
            let fi = cur[0];
            lists.push((std::mem::take(&mut cur), cur_nested));
            cur_nested = nested_here;
        }
        cur.push(idx);
        prev_indent = it.indent;
        prev_line = it.line;
        stack.push((it.indent, it.ordered));
    }
    if !cur.is_empty() {
        lists.push((std::mem::take(&mut cur), cur_nested));
    }
    let mut prev_num = 0u64;
    for (l, nested) in lists.iter() {
        if !*nested {
            prev_num = items[*l.last().unwrap()].number;
            continue;
        }
        prev_num = 0;
        for (n, idx) in l.iter().enumerate() {
            let it = &items[*idx];
            let expected = if n == 0 {
                prev_num.saturating_add(1)
            } else {
                items[l[n - 1]].number.saturating_add(1)
            };
            if it.number != expected {
                let msg = format!(
                    "Ordered list item number {} does not match list style 'ordered' (expected {})",
                    it.number, expected
                );
                let s = doc.char_to_byte(it.line, it.indent);
                let e = doc.char_to_byte(it.line, it.indent + it.marker.chars().count());
                let rep = format!("{}{}", expected, &it.marker[it.marker.len() - 1..]);
                out.push(
                    Issue::new("MD029", it.line + 1, it.indent + 1, msg)
                        .with_fix(Fix::new(s, e, &rep)),
                );
            }
        }
        prev_num = items[*l.last().unwrap()].number;
    }
    out
}

