{"command": "cd /workspace && cat > src/fix.rs <<'RSEOF'
use crate::rules::Fix;

/// Apply non-overlapping fixes, processing from the lowest offset first and
/// adjusting subsequent offsets.
pub fn apply(text: &str, fixes: &[Fix]) -> (String, usize) {
    let mut sorted: Vec<&Fix> = fixes.iter().collect();
    sorted.sort_by_key(|f| (f.start, f.end));
    let bytes = text.as_bytes();
    let mut applied: Vec<(usize, usize)> = Vec::new();
    let mut out: Vec<(usize, usize, &str)> = Vec::new();
    let mut delta: i64 = 0;
    for f in sorted {
        if f.start > bytes.len() || f.end > bytes.len() || f.start > f.end {
            continue;
        }
        // the fix's original range must still correspond to untouched text
        if applied.iter().any(|(a, b)| f.start < *b && f.end > *a) {
            continue;
        }
        let start = (f.start as i64 + delta).max(0) as usize;
        let end = (f.end as i64 + delta).max(0) as usize;
        if end > text.len() || start > end {
            continue;
        }
        // verify the text at the adjusted range matches the original
        if &text[start..end] != &text[f.start..f.end] {
            continue;
        }
        applied.push((f.start, f.end));
        delta += f.replacement.len() as i64 - (f.end - f.start) as i64;
        out.push((start, end, &f.replacement));
    }
    let mut result = text.to_string();
    for (s, e, rep) in out {
        result.replace_range(s..e, rep);
    }
    (result, applied.len())
}
